window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0122", [{"word":"hazardous","ipa_uk":"/ˈhæzədəs/","ipa_us":"/ˈhæzərdəs/","definition_zh":"危险的；可能造成伤害或损害的；由运气决定的（古义）","definition_en":"dangerous or likely to cause harm, especially to health, safety or the environment","core_image":"一滩看不清底的不明液体摊在车间地面，旁边立着一块画有骷髅的黄色警示牌","scene":"车间地面上洇开一滩气味刺鼻的液体，班长伸手拦住刚进门的学徒，说 That puddle is hazardous, so nobody walks down this aisle until the spill team clears it.","sceneCN":"这里 hazardous 指「本身可能造成伤害或损害的」，取第 1 个义项（会直接伤人的危险）；句意为那滩液体有危险，在清理队处理干净之前谁都不许走这条通道。图中可辨识物件：警示牌、不明液体、防护靴、隔离栏。","pos":[{"tag":"adj.","zh":"危险的；有危害的（作定语或表语，可与 to 连用说明受害对象）"},{"tag":"adj.","zh":"（古义）由运气决定的、碰运气的"}],"collocations":[{"phrase":"hazardous waste","zh":"危险废物"},{"phrase":"hazardous material","zh":"危险物品、危险材料"},{"phrase":"hazardous conditions","zh":"危险状况（路面、天气等）"},{"phrase":"hazardous to health","zh":"对健康有害"},{"phrase":"potentially hazardous","zh":"有潜在危险的"},{"phrase":"hazardous cargo","zh":"危险货物"}],"forms":[{"label":"原级","form":"hazardous"},{"label":"比较级","form":"more hazardous"},{"label":"最高级","form":"most hazardous"},{"label":"副词","form":"hazardously"},{"label":"名词（危险性）","form":"hazardousness"}],"derivatives":[{"word":"hazardously","pos":"adv.","zh":"危险地；以可能致害的方式"},{"word":"hazardousness","pos":"n.","zh":"危险性；具有危害的属性"},{"word":"hazard","pos":"n./v.","zh":"危险、隐患；冒险试试"},{"word":"biohazard","pos":"n.","zh":"生物危害；生物危险源"}],"senses":[{"no":"01","title":"Able to hurt the body","titleCN":"会直接伤人的","definition":"likely to cause injury to people who touch it, stand near it or work with it","definitionCN":"人一旦接触、靠近或在其中作业就可能受伤的","example":"The broken railing made the whole stairwell hazardous for the workers.","exampleCN":"断裂的栏杆让整个楼梯间对工人来说都变得危险。","why":"The base noun hazard names a source of harm, and the suffix -ous means full of, so the adjective describes something that carries harm inside it.","whyCN":"本词由名词 hazard「危险源」加后缀 -ous「充满…的」构成，因此形容某物本身就带着伤人的因素。"},{"no":"02","title":"Harmful to health","titleCN":"有害健康的","definition":"having a harmful effect on the body when breathed in, swallowed or absorbed over time","definitionCN":"经呼吸、吞咽或长期接触而对身体产生损害的","example":"Hazardous fumes from the old paint drifted through the whole building.","exampleCN":"旧油漆散发的有害气体飘遍了整栋楼。","why":"The word is used where harm is not visible at once but accumulates, so health warnings attach it to smoke, dust and chemicals.","whyCN":"这类危害往往不是立刻可见而是慢慢累积，因此健康警示常把该词与烟、粉尘和化学品连用。"},{"no":"03","title":"Harmful to the environment","titleCN":"危害环境的","definition":"able to damage water, soil, air or living things when released into nature","definitionCN":"进入自然环境后会破坏水体、土壤、空气或生物的","example":"The label warns that the solvent is hazardous to aquatic life.","exampleCN":"标签警示这种溶剂对水生生物有害。","why":"Environmental law extended the same word from the human body to the ecosystem, because the test is still whether something can be damaged.","whyCN":"环境法规把这同一个词从人体扩展到生态系统，因为判断标准仍是某对象会不会被破坏。"},{"no":"04","title":"Dangerous conditions","titleCN":"状况本身危险的","definition":"describing roads, weather or working conditions in which accidents are likely","definitionCN":"形容路面、天气或作业环境容易发生事故的","example":"Drivers were told to slow down in the hazardous fog.","exampleCN":"司机被告知在危险的大雾中减速行驶。","why":"Here the danger comes from the situation rather than from an object, but the pattern stays the same: something in the setting can cause harm.","whyCN":"此处危险来自处境而非物品，但构词逻辑不变：环境中有某样东西能造成伤害。"},{"no":"05","title":"Regulated dangerous goods","titleCN":"法规分类中的危险品","definition":"a legal label for goods that must be packed, labelled and transported under special rules","definitionCN":"法规上指必须按特殊规则包装、标示和运输的货物","example":"Every container of hazardous cargo needs its own shipping document.","exampleCN":"每一箱危险货物都需要单独的运输单据。","why":"Once authorities had to inspect shipments, the adjective became a category name, so it now appears on forms and labels rather than in description.","whyCN":"当管理部门必须查验货运时，这个形容词就变成了分类名，于是它更多地出现在单据和标签上，而不是描写句里。"},{"no":"06","title":"A risky decision or guess","titleCN":"比喻：冒险的、不稳妥的","definition":"describing a step, assumption or investment that may fail badly","definitionCN":"形容某一步骤、假设或投资可能带来严重后果的","example":"Betting the whole budget on one client was a hazardous move.","exampleCN":"把全部预算押在一个客户身上是冒险之举。","why":"The old idea of a dice throw survives in this figurative use: the outcome is not controlled, and losing costs a lot.","whyCN":"这一比喻保留了旧时掷骰子的意味：结果不受控制，一旦输了代价很大。"},{"no":"07","title":"Decided by chance","titleCN":"古义：取决于运气的","definition":"an older use meaning that something depends on luck rather than on plan or skill","definitionCN":"旧用法，指某事成败取决于运气而非计划或技艺","example":"In older texts a hazardous voyage meant one whose end the sailors could not foresee.","exampleCN":"在较早的文本里，hazardous voyage 指水手无法预知结局的航行。","why":"Hazard first named a game of dice, so anything hazardous was literally something the dice would settle.","whyCN":"hazard 最初指一种掷骰子的赌局，因此 hazardous 字面上就是「由骰子决定的事」。"},{"no":"08","title":"Explosive-atmosphere area","titleCN":"防爆分区中的危险区域","definition":"a technical label for an area where flammable gas or dust may be present, so equipment must be certified","definitionCN":"技术用语，指可能存在可燃气体或粉尘、因而设备须经认证的区域","example":"Only certified lamps may be fitted in a hazardous area of the refinery.","exampleCN":"炼油厂的防爆危险区域内只能安装经过认证的灯具。","why":"Industrial safety turned the word into a zone classification, so a hazardous area is a mapped region rather than a described object.","whyCN":"工业安全把这词变成了区域等级，因此 hazardous area 指划定的区域，而不是被描写的物体。"}],"etymology":{"intro":{"en":"Hazardous is the noun hazard plus the Latin-derived suffix -ous. Hazard itself came into English from Old French hasard, the name of a dice game, and is generally traced through Spanish to Arabic for the dice. The suffix is the regular Latin -osus, meaning full of.","cn":"hazardous 是名词 hazard 加拉丁来源的后缀 -ous 构成的。hazard 本身来自古法语 hasard，原是一种掷骰子赌局的名字，一般认为经西班牙语可追到阿拉伯语表示骰子的说法。后缀即常规的拉丁 -osus，意为「充满…的」。"},"items":[{"era":"OLD FRENCH HASARD","en":"Hasard named both a dice game and whatever the dice decided, so chance and risk were one idea from the start.","cn":"hasard 既指掷骰子的赌局，也指骰子决定的结果，因此「偶然」与「风险」从一开始就是同一个概念。"},{"era":"ARABIC DICE","en":"Most dictionaries trace hasard through Spanish azar to Arabic az-zahr, the dice. This route is generally accepted, though the exact Arabic form behind it is still debated.","cn":"多数词典认为 hasard 经西班牙语 azar 追到阿拉伯语 az-zahr「骰子」。这条路径一般认为成立，但其后确切阿拉伯语形式仍有争论。"},{"era":"CHANCE TO DANGER","en":"By the sixteenth century English hazard covered a risk taken in a game and then any source of possible loss or injury, which is the sense the adjective inherits.","cn":"到十六世纪，英语 hazard 已从赌局中承担的风险扩展到任何可能造成损失或伤害的来源，这正是形容词所继承的词义。"},{"era":"LATIN -OSUS","en":"The suffix -ous descends from Latin -osus, full of or abounding in, as in dangerous and poisonous, so hazardous means full of hazard.","cn":"后缀 -ous 源自拉丁 -osus「充满…的、多…的」，如 dangerous 与 poisonous，因此 hazardous 意为「满是危险的」。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain for the pre-Arabic origin of the dice word: its deeper etymology is unsettled and no Latin relative exists. Separately, only the first-recorded date of hazardous in English is uncertain; the French and Arabic route itself is not in dispute.","cn":"来源不确定：这个骰子词在阿拉伯语之前的更深来源没有定论，也没有拉丁同族词可援。另需区分：hazardous 最早的英语书证年代各家记载不一，这属于仅首见年代存疑；法语与阿拉伯语这条路径本身并无争议。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close but do not all share the hazard root; group two holds near-synonyms that differ in how openly the danger shows.","cn":"第一组是形或音相近、但并非都含 hazard 词根的词；第二组是近义词，区别在于危险显露的程度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hazard","ipa":"/ˈhæzəd/","tag":"the base noun","definition":"The source noun meaning a thing or condition that may cause harm; the adjective only describes whatever carries it.","definitionCN":"作为来源的名词，指可能造成伤害的事物或状况；形容词只用来描述带有这种危险的东西。"},{"word":"haphazard","ipa":"/ˌhæpˈhæzəd/","tag":"same element, different whole","definition":"Built from hap, meaning chance, plus hazard: it describes something done without order or plan, not something dangerous.","definitionCN":"由表示偶然的 hap 加 hazard 构成：形容做事没有条理或计划，而不是形容危险。"},{"word":"hazel","ipa":"/ˈheɪzl/","tag":"look-alike only","definition":"The nut tree and its light brown colour, from Old English hæsl; it has no etymological link with hazard.","definitionCN":"指榛树及其浅褐色，来自古英语 hæsl；与 hazard 没有词源关系。"},{"word":"haze","ipa":"/heɪz/","tag":"look-alike only","definition":"Thin mist or blurred air, probably a back-formation from hazy; its origin is separate and itself uncertain.","definitionCN":"指薄雾或使空气模糊的状态，可能由 hazy 逆构而来；其来源与本词无关，本身亦不确定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dangerous","ipa":"/ˈdeɪndʒərəs/","tag":"general danger","definition":"The everyday word for anything likely to cause harm; hazardous is its more technical and regulatory cousin.","definitionCN":"最日常的说法，指任何可能造成伤害的事物；hazardous 是其更技术化、更常用于法规语境的说法。"},{"word":"unsafe","ipa":"/ˌʌnˈseɪf/","tag":"fails a standard","definition":"Not meeting a safety standard, often said of equipment or premises; it judges compliance rather than innate harm.","definitionCN":"不符合安全标准，多用于设备或场所；它评判的是合规性，而非事物本身的危害。"},{"word":"perilous","ipa":"/ˈperələs/","tag":"literary and grave","definition":"Highly dangerous in a dramatic, often life-threatening way; it is literary where hazardous is neutral and technical.","definitionCN":"以戏剧化、常危及生命的方式极度危险；它偏文学，而 hazardous 中性且技术化。"},{"word":"precarious","ipa":"/prɪˈkeəriəs/","tag":"unstable, not harmful","definition":"Depending on chance or on a shaky support, so it may collapse; the emphasis is instability rather than toxicity or injury.","definitionCN":"依靠偶然或不稳的支撑，因而可能垮掉；侧重不稳定，而不是毒性或伤害。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real French and Arabic route, real fixed phrases and real compounds, not invented rhymes.","cn":"正常联想：真实的法语与阿拉伯语来源、真实搭配与真实复合词，而非编造的顺口溜。"},"normal":[{"en":"hazard plus -ous equals full of danger, the same pattern as danger and dangerous.","cn":"hazard 加 -ous 就是「满是危险」，与 danger 变 dangerous 是同一套构词。"},{"en":"The word began as a dice game, so hazardous still carries the flavour of a throw you cannot control.","cn":"这个词最初是一场掷骰子的赌局，因此 hazardous 至今带着「掷出去就控制不了」的意味。"},{"en":"Fixed phrases mark the fields: hazardous waste, hazardous material, hazardous cargo.","cn":"固定搭配标出使用领域：危险废物、危险物品、危险货物。"},{"en":"The compound biohazard shows the same hazard element with a life-prefix.","cn":"复合词 biohazard 展示了同一个 hazard 成分加上表示生命的词缀。"},{"en":"Haphazard keeps hazard spelled the same but means unordered, a useful contrast to remember.","cn":"haphazard 拼写里保留同样的 hazard，意思却是「杂乱无章」，这个对照值得记住。"}],"abstract":[{"en":"Picture a dice still rolling on the table: the number has not settled, and that unsettled state is the original hazard.","cn":"想象桌上还在转的骰子：点数尚未落定，这种悬而未决正是 hazard 的本义。"},{"en":"Picture a sealed drum with no label on it: nobody can see the harm inside, yet the harm is real.","cn":"想象一只没有标签的密封桶：里面的危害看不见，但危害确实存在。"},{"en":"Picture a yellow triangle standing where the floor looks perfectly dry, warning about what is not visible.","cn":"想象一块立在看起来完全干燥地面上的黄色三角牌，警示的正是看不见的东西。"}]},"examples":[{"en":"The old pipes were hazardous and had to be replaced within a month.","cn":"这些旧管道有危险，必须在一个月内更换。"},{"en":"Smoking indoors is hazardous to everyone in the room, not only the smoker.","cn":"室内吸烟对房间里所有人都有害，不只是吸烟者本人。"},{"en":"Investing there felt hazardous, but the returns were real.","cn":"在那里投资让人觉得冒险，但回报是实实在在的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「害着得死」——害人的东西沾上就危险，于是 hazardous 就是危险的、有危害的","word":"hazardous"},"root":"hazard（古法语 hasard「掷骰子赌局」，一般认为经西班牙语 azar 追到阿拉伯语 az-zahr「骰子」）+ 拉丁后缀 -ous「充满…的」；本义「满是风险的」。","sensesIntro":{"en":"Eight senses follow one line: something carries harm, and the harm spreads outward from the body to health, to the environment, to conditions, to regulated goods, to a risky decision, back to the old sense of chance, and finally to an industrial zone label.","cn":"八个义项沿一条线索展开：某物身上带着危害，这种危害从身体扩展到健康、环境、处境、受管制的货物、冒险的决定，再回到旧时的运气义，最后落到工业分区标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unlabelled drum of liquid that can hurt whoever touches it.","cn":"核心意象：一只没有标签的液体桶，谁碰到都可能受伤。"},"chain":["BODILY INJURY","HEALTH HARM","ENVIRONMENTAL DAMAGE","DANGEROUS CONDITIONS","REGULATED GOODS","RISKY CHOICE"],"branches":[{"senses":"S1 · S2","en":"THE BODY: the harm is immediate for the skin and slow for the lungs.","cn":"身体：对皮肤是立刻的伤害，对肺则是缓慢的伤害。"},{"senses":"S3","en":"THE ECOSYSTEM: the same test moves from people to water, soil and fish.","cn":"生态系统：同一套判断标准从人移到水体、土壤与鱼。"},{"senses":"S4","en":"CONDITIONS: weather and roads can carry harm without being objects.","cn":"处境：天气与路面并非物品，却同样能带来危害。"},{"senses":"S5 · S8","en":"PAPERWORK AND ZONES: harm becomes a category on a shipping form and a colour on a factory map.","cn":"单据与分区：危害变成运单上的一个类别和工厂图上的一个色块。"},{"senses":"S6 · S7","en":"CHANCE: the dice game survives as a risky decision and as the older sense of luck.","cn":"偶然：掷骰子的赌局残留为冒险的决定，以及旧时的运气义。"}]},"affixes":{"intro":{"en":"Hazardous can be read as the noun stem hazard plus the suffix -ous, and the same two pieces build several other English words.","cn":"hazardous 可拆成名词词干 hazard 与后缀 -ous，这两块还构成若干其他英语词。"},"latinIntro":{"en":"The stem is French and ultimately Arabic, not Latin, but the suffix is genuinely Latin -osus. Latin contributed only the ending, so the Latin entries below are limited to that suffix.","cn":"词干来自法语并最终来自阿拉伯语，并非拉丁语，但后缀是真正的拉丁 -osus。拉丁语只贡献了词尾，因此下面的拉丁词条仅限于该后缀。"},"items":[{"word":"hazard","structure":"hazard (noun stem, from Old French hasard)","meaning":"a source of possible harm","meaningCN":"可能造成伤害的来源","example":"The loose cable is a hazard for anyone passing.","exampleCN":"那根松脱的电缆对经过的人是个隐患。"},{"word":"hasard","structure":"hasard (Old French source form, a dice game)","meaning":"the original dice game and its chances","meaningCN":"原指掷骰子赌局及其偶然结果","example":"The French word hasard still appears in histories of games.","exampleCN":"法语词 hasard 至今仍出现在博弈史著作中。"},{"word":"-ous","structure":"-ous (Latin suffix -osus, full of)","meaning":"full of; having the quality of","meaningCN":"充满…的；具有…性质的","example":"A poisonous plant is full of poison in the same way.","exampleCN":"有毒的植物同样是以「充满毒」的方式构词。"},{"word":"hazardously","structure":"hazardous + -ly (in a manner)","meaning":"in a dangerous manner","meaningCN":"以危险的方式","example":"The truck was hazardously overloaded.","exampleCN":"那辆卡车危险地超载了。"},{"word":"hazardousness","structure":"hazardous + -ness (state or quality)","meaning":"the quality of being dangerous","meaningCN":"危险的属性","example":"Inspectors rated the site for its hazardousness.","exampleCN":"检查员评估了该场地的危险程度。"},{"word":"nonhazardous","structure":"non- (not) + hazardous","meaning":"not classed as dangerous","meaningCN":"未被列为危险品的","example":"Nonhazardous waste goes to the ordinary landfill.","exampleCN":"非危险废物被送往普通填埋场。"},{"word":"haphazard","structure":"hap (chance) + hazard, compound","meaning":"without order or plan","meaningCN":"没有条理或计划的","example":"Books were stacked in a haphazard pile.","exampleCN":"书本被胡乱堆成一摞。"},{"word":"biohazard","structure":"bio- (life) + hazard, compound","meaning":"a biological source of danger","meaningCN":"生物性的危险源","example":"The lab door carried a biohazard sign.","exampleCN":"实验室门上挂着生物危害标志。"}],"latinEntries":[{"word":"-osus","structure":"Latin adjectival suffix -osus (full of)","meaning":"full of, abounding in","meaningCN":"充满…的、多…的","example":"It is the ending of Latin periculosus, full of danger.","exampleCN":"它是拉丁语 periculosus（充满危险的）中的词尾。"}]}},{"word":"hazard","ipa_uk":"/ˈhæzəd/","ipa_us":"/ˈhæzərd/","definition_zh":"危险；隐患；危险源；偶然、碰运气（古义）；（高尔夫）障碍区","definition_en":"a thing or condition that may cause harm; also to risk something or put it in danger","core_image":"山道上方的碎石松脱，滚落的一颗石子擦着行人的肩膀飞过","scene":"山道转角处碎石不断往下掉，向导抬头看了一眼坡面，说 Hazard comes from above on this stretch, so keep close to the inner wall.","sceneCN":"这里 hazard 指「可能造成伤害的来源」，取第 1 个义项（头顶上真正会落下来的东西）；句意为这一段路的危险来自上方，所以要紧贴内侧岩壁走。图中可辨识物件：碎石、坡面、岩壁、徒步者的头盔。","pos":[{"tag":"n.","zh":"危险；隐患；危险源（可数，复数 hazards）"},{"tag":"n.","zh":"偶然、碰运气的事（古义，多见于 by hazard 一类短语）"},{"tag":"v.","zh":"冒险提出（猜测、评论）；使遭受危险"}],"collocations":[{"phrase":"health hazard","zh":"健康危害"},{"phrase":"fire hazard","zh":"火灾隐患"},{"phrase":"safety hazard","zh":"安全隐患"},{"phrase":"occupational hazard","zh":"职业危害；工作本身带来的风险"},{"phrase":"hazard a guess","zh":"斗胆猜一猜"},{"phrase":"hazard warning lights","zh":"危险警示灯、双闪灯"}],"forms":[{"label":"复数","form":"hazards"},{"label":"第三人称单数","form":"hazards"},{"label":"过去式","form":"hazarded"},{"label":"过去分词","form":"hazarded"},{"label":"现在分词","form":"hazarding"}],"derivatives":[{"word":"hazardous","pos":"adj.","zh":"危险的；有危害的"},{"word":"hazardously","pos":"adv.","zh":"危险地"},{"word":"hazardousness","pos":"n.","zh":"危险性"},{"word":"haphazard","pos":"adj./adv.","zh":"杂乱无章的；碰巧地（由 hap 加 hazard 构成）"}],"senses":[{"no":"01","title":"A source of harm","titleCN":"危险源、隐患","definition":"a concrete thing such as a loose wire, a sharp edge or a toxic drum that may cause injury","definitionCN":"松脱的电线、尖锐的边缘或有毒的桶这类会致人受伤的具体物件","example":"Workers marked every hazard on the site with a red flag.","exampleCN":"工人用红旗把工地上的每一处隐患都标了出来。","why":"The word names the thing itself, not the feeling of fear, so a hazard can be pointed at and removed.","whyCN":"这个词指的是东西本身，而不是恐惧感，因此隐患可以被指出来、也可以被清除。"},{"no":"02","title":"Risk as a general condition","titleCN":"危险、风险（抽象）","definition":"the possibility of loss or injury, used without counting individual dangers","definitionCN":"发生损失或伤害的可能性，不具体计数某一处危险","example":"The job exposes young climbers to constant hazard.","exampleCN":"这份工作让年轻攀登者长期处在危险之中。","why":"English allows hazard to be uncountable when it means the state of being exposed rather than a list of threats.","whyCN":"当 hazard 指「处于暴露状态」而不是一串具体威胁时，英语中可用作不可数。"},{"no":"03","title":"Occupational hazard","titleCN":"职业危害、工作附带的风险","definition":"a danger that comes with a particular job and is hard to avoid while doing it","definitionCN":"某项工作本身带来的、在作业时难以避开的危险","example":"Sore knees are an occupational hazard for anyone who lays tiles.","exampleCN":"膝盖酸痛是铺砖工人这一行的职业危害。","why":"Because some risks are inseparable from the trade, the phrase became a set label in insurance and labour law.","whyCN":"有些风险与行业无法分开，这一说法因此在保险与劳动法中固定成一个标签。"},{"no":"04","title":"Fire, health and electrical hazards","titleCN":"按成因命名的具体隐患","definition":"a hazard named after what it would cause or where it comes from, as in fire hazard or health hazard","definitionCN":"按会造成的后果或来源命名的隐患，如火灾隐患、健康危害","example":"Overloaded sockets are the most common fire hazard in old flats.","exampleCN":"插座超载是老房子里最常见的火灾隐患。","why":"Inspectors need short labels, so the cause is placed before the word and the compound becomes a checklist item.","whyCN":"检查人员需要简短标签，于是把成因放在词前，复合词就成了清单上的一个项目。"},{"no":"05","title":"Chance, by hazard","titleCN":"古义：偶然、碰运气","definition":"the older sense of chance or luck, kept in phrases such as by hazard","definitionCN":"较早的「偶然或运气」义，保留在 by hazard 一类短语中","example":"The two travellers met by hazard at a roadside inn.","exampleCN":"两位旅人在路边客栈偶然相遇。","why":"The word entered English as a dice game, so chance was its first meaning and the danger sense grew out of it later.","whyCN":"这个词最初以掷骰子赌局的身份进入英语，因此「偶然」是第一层意思，危险义是后来从它长出来的。"},{"no":"06","title":"A golf-course obstacle","titleCN":"高尔夫球场障碍区","definition":"a bunker, pond or similar obstacle on a golf course that costs the player a stroke","definitionCN":"高尔夫球场上的沙坑、水塘等障碍，会让球手多打一杆","example":"His second shot landed in the hazard beside the green.","exampleCN":"他的第二杆落进了果岭旁的障碍区。","why":"Golf borrowed the word for anything that punishes a bad shot, keeping the core idea of an obstacle waiting to catch you.","whyCN":"高尔夫借用了这个词来指惩罚失误球的一切东西，保留了「等着抓住你的障碍」这一核心。"},{"no":"07","title":"To hazard a guess","titleCN":"动词：斗胆猜测、冒险提出","definition":"to say something without being sure, accepting that it may be wrong","definitionCN":"在无把握的情况下说出某事，并接受说错的可能","example":"Let me hazard a guess that the delay came from the weather.","exampleCN":"让我斗胆猜一句，延误是天气造成的。","why":"The verb keeps the dice metaphor: the speaker throws an answer out and lets chance decide whether it lands well.","whyCN":"动词保留了掷骰子的比喻：说话者把答案扔出去，让运气决定它落得好不好。"},{"no":"08","title":"To put something at risk","titleCN":"动词：拿…去冒险、使陷入危险","definition":"to expose something valuable, such as money or a life, to possible loss","definitionCN":"使金钱、生命等宝贵之物面临损失的可能","example":"He would not hazard his savings on a single harvest.","exampleCN":"他不肯把积蓄押在一季收成上。","why":"This use is transitive and older: what follows the verb is the thing being thrown into the game.","whyCN":"这一用法及物且较古老：动词后面接的正是被扔进赌局的那样东西。"}],"etymology":{"intro":{"en":"Hazard reached English from Old French hasard, a dice game and the chances it produced. The usual account takes it through Spanish azar to Arabic az-zahr, the dice. English later shifted the meaning from chance to the harm that chance may bring.","cn":"hazard 经古法语 hasard 进入英语，原指一种掷骰子赌局及其产生的各种结果。通常的说法是它经西班牙语 azar 追到阿拉伯语 az-zahr「骰子」。英语后来把词义从「偶然」转向「偶然可能带来的伤害」。"},"items":[{"era":"OLD FRENCH HASARD","en":"Hasard named the game and the throw, and by extension anything left to luck, so the noun began as a word about uncertainty.","cn":"hasard 既指赌局也指这一掷，并引申指任何交给运气决定的事，因此这个名词最初是个关于不确定的词。"},{"era":"ARABIC AZ-ZAHR","en":"The generally accepted route is Spanish azar from Arabic az-zahr, the dice; the articles al- and the exact noun form are still discussed by specialists.","cn":"一般认为的路径是西班牙语 azar 出自阿拉伯语 az-zahr「骰子」；其中冠词与确切名词形式仍在学界讨论。"},{"era":"CHANCE AND LOSS","en":"In medieval French and English the word covered a gambling stake, then any risk of loss, and finally a physical thing that could cause injury.","cn":"在中古法语与英语里，这个词先指赌注，再指任何损失风险，最后指可能造成伤害的具体物件。"},{"era":"ENGLISH NOUN AND VERB","en":"The noun sense of an obstacle is recorded by the sixteenth century, and the verb meaning to risk appears soon after, keeping the gambling image.","cn":"表示障碍的名词义在十六世纪已有书证，表示「冒风险」的动词义紧随其后出现，仍保留赌博意象。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of the dice word before Arabic is not established, and some older accounts offer different routes. These alternatives are listed side by side rather than settled.","cn":"来源不确定：这个骰子词在阿拉伯语之前的来源未得到证明，一些较早的说法还提出别的路径。这些假说并列列出，不作定论。"}]},"similar":{"note":{"en":"Group one contains words whose spelling or sound is close; group two contains words for danger that differ in scope or tone.","cn":"第一组是拼写或读音相近的词；第二组是表示危险但范围或语气有别的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hazardous","ipa":"/ˈhæzədəs/","tag":"adjective form","definition":"The adjective built from hazard with -ous; it describes something that carries danger rather than naming the danger.","definitionCN":"由 hazard 加 -ous 构成的形容词；它描述带着危险的东西，而不是给危险命名。"},{"word":"haphazard","ipa":"/ˌhæpˈhæzəd/","tag":"chance plus hazard","definition":"A compound of hap and hazard meaning disorganised or random; it keeps the chance sense and drops the danger sense.","definitionCN":"由 hap 与 hazard 构成的复合词，意为杂乱或随机；它保留了偶然义，丢掉了危险义。"},{"word":"hazel","ipa":"/ˈheɪzl/","tag":"look-alike only","definition":"A nut tree and a light brown colour, from Old English hæsl; no shared origin with hazard.","definitionCN":"指榛树与浅褐色，来自古英语 hæsl；与 hazard 不同源。"},{"word":"haze","ipa":"/heɪz/","tag":"look-alike only","definition":"Thin mist or a blurred view, probably from hazy; unrelated in origin and often confused in spelling.","definitionCN":"薄雾或模糊的视野，可能来自 hazy；词源无关，拼写常被混淆。"}]},{"heading":"NEAR MEANING","entries":[{"word":"danger","ipa":"/ˈdeɪndʒə/","tag":"general exposure","definition":"The general state of being exposed to harm; hazard usually points to a specific source inside that state.","definitionCN":"泛指处于受害可能之中的状态；hazard 通常指这种状态里某个具体的来源。"},{"word":"risk","ipa":"/rɪsk/","tag":"chance of loss","definition":"The probability of loss, often weighed against benefit; a hazard is the thing that creates the probability.","definitionCN":"损失发生的概率，常与收益一起权衡；hazard 是造成该概率的那个东西。"},{"word":"peril","ipa":"/ˈperəl/","tag":"grave, literary","definition":"Serious and immediate danger of death or ruin, stronger and more literary than hazard.","definitionCN":"严重而迫近的死亡或毁灭危险，比 hazard 更重、更偏文学。"},{"word":"threat","ipa":"/θret/","tag":"intention to harm","definition":"A person or thing that announces or promises harm; a hazard need not intend anything.","definitionCN":"宣告或预示要造成伤害的人或物；hazard 则不必带有意图。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Arabic route, real compounds and real fixed phrases.","cn":"正常联想：真实的阿拉伯语来源、真实复合词与真实搭配。"},"normal":[{"en":"Hazard began as a dice game: chance first, danger later.","cn":"hazard 最初是掷骰子的赌局：先有偶然，后有危险。"},{"en":"Occupational hazard is the phrase that keeps the word alive in everyday speech.","cn":"occupational hazard 这个说法让这个词在日常口语里保持活力。"},{"en":"Fire hazard and health hazard are formed by putting the cause in front.","cn":"fire hazard 与 health hazard 都是把成因放在前面构成的。"},{"en":"The verb survives mainly in hazard a guess and hazard an opinion.","cn":"动词义主要保留在 hazard a guess 与 hazard an opinion 里。"},{"en":"Golf keeps the old obstacle sense in bunkers and ponds.","cn":"高尔夫用沙坑和水塘保留了古老的障碍义。"}],"abstract":[{"en":"Picture a dice cup still in the air: whatever comes out is not chosen by anyone.","cn":"想象一只还在空中的骰盅：倒出来的是什么，没有人能选。"},{"en":"Picture a stone loosened by rain, waiting above a path without any intention to fall.","cn":"想象一块被雨泡松的石头悬在路上方，它并没有要掉下来的意图。"},{"en":"Picture a red flag planted on the ground at the exact spot where someone once tripped.","cn":"想象地面某处插着一面红旗，正是有人曾在那里绊倒的地方。"}]},"examples":[{"en":"The report lists every hazard found in the warehouse.","cn":"报告列出了仓库里发现的每一处隐患。"},{"en":"Lost luggage is an occupational hazard for tour guides.","cn":"行李丢失是导游这一行的职业风险。"},{"en":"She hazarded a guess that the meeting would run late.","cn":"她斗胆猜了一句，说会议会拖到很晚。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「害着得」——害人的东西落到身上就危险，hazard 就是危险、隐患","word":"hazard"},"root":"古法语 hasard「掷骰子赌局」，一般认为经西班牙语 azar 上溯阿拉伯语 az-zahr「骰子」；由「偶然」引申为「可能致害之物」，再派生 hazardous。","sensesIntro":{"en":"Eight senses move from the concrete threat to the abstract state, then to named categories, the older chance sense, a golf obstacle, and finally two verb uses that still throw something into the game.","cn":"八个义项从具体威胁走到抽象状态，再到按成因命名的类别、较早的偶然义、高尔夫障碍，最后是两个仍保留「把东西扔进赌局」意味的动词用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone loosened above a path, able to fall on whoever walks there.","cn":"核心意象：路上方一块松动的石头，随时可能砸到走过的人。"},"chain":["PHYSICAL SOURCE","EXPOSURE","JOB-RELATED RISK","NAMED CATEGORIES","CHANCE","VERBAL RISKING"],"branches":[{"senses":"S1 · S2","en":"THING AND STATE: one sense points at the object, the other at being surrounded by such objects.","cn":"物与状态：一个义项指着那个物件，另一个指着被这类物件包围的处境。"},{"senses":"S3 · S4","en":"LABELS: work and inspection turn the word into fixed compounds such as occupational hazard and fire hazard.","cn":"标签：工作与检查把该词固定成 occupational hazard、fire hazard 一类复合词。"},{"senses":"S5","en":"CHANCE: the oldest layer, still visible in by hazard.","cn":"偶然：最古老的一层，仍留在 by hazard 里。"},{"senses":"S6","en":"GOLF: an obstacle on the course borrows the word entire.","cn":"高尔夫：球场上的障碍整体借用了这个词。"},{"senses":"S7 · S8","en":"VERBS: guessing and risking both throw something out and wait for the result.","cn":"动词：猜测与冒险都是把某样东西扔出去，然后等结果。"}]},"affixes":{"intro":{"en":"Hazard is a borrowed stem rather than a built word, but it combines freely and feeds a small family of derived words.","cn":"hazard 是从外语借来的词干，而非由词根拼成，但它能自由组合，并衍生出一小族词。"},"latinIntro":{"en":"No Latin inherited form exists for this stem; only the derivative suffix -ous is Latin, so the Latin entry is limited to that ending.","cn":"这个词干没有拉丁语祖传形式；只有派生后缀 -ous 来自拉丁语，因此拉丁词条仅限于该词尾。"},"items":[{"word":"hazard","structure":"hazard (borrowed noun stem, Old French hasard)","meaning":"a source of possible harm","meaningCN":"可能造成伤害的来源","example":"The steep drop is the main hazard on this trail.","exampleCN":"陡降的崖边是这条小路上主要的危险源。"},{"word":"-ous","structure":"-ous (Latin -osus, full of)","meaning":"full of; having the quality of","meaningCN":"充满…的；具有…性质的","example":"A dangerous road is full of danger by the same pattern.","exampleCN":"危险的公路按同一构词模式就是「充满危险」。"},{"word":"hazardous","structure":"hazard + -ous (full of)","meaning":"carrying danger","meaningCN":"带着危险的","example":"The chemical is hazardous to skin.","exampleCN":"这种化学品对皮肤有害。"},{"word":"hazardously","structure":"hazardous + -ly (in a manner)","meaning":"dangerously","meaningCN":"危险地","example":"The van was hazardously packed.","exampleCN":"那辆小货车装得十分危险。"},{"word":"haphazard","structure":"hap + hazard (compound)","meaning":"without plan or order","meaningCN":"无计划、无次序的","example":"The shelves were built in a haphazard way.","exampleCN":"这些架子是胡乱搭起来的。"},{"word":"biohazard","structure":"bio- (life) + hazard","meaning":"a biological danger","meaningCN":"生物性危险","example":"Samples were moved in a biohazard box.","exampleCN":"样本装在生物危害箱里运送。"},{"word":"hazard-free","structure":"hazard + -free (without)","meaning":"containing no known danger","meaningCN":"不含已知危险的","example":"The playground was rebuilt as a hazard-free space.","exampleCN":"操场被重建为一个无隐患的空间。"},{"word":"hazarded","structure":"hazard + -ed (past tense and participle)","meaning":"risked; put forward as a guess","meaningCN":"冒了险；斗胆提出了","example":"He hazarded his reputation on the forecast.","exampleCN":"他把自己的名声押在这个预测上。"}],"latinEntries":[{"word":"-osus","structure":"Latin adjectival suffix -osus (full of)","meaning":"full of, abounding in","meaningCN":"充满…的、多…的","example":"English dangerous and hazardous share this same ending.","exampleCN":"英语 dangerous 与 hazardous 共用这一词尾。"}]}},{"word":"chemical","ipa_uk":"/ˈkemɪkl/","ipa_us":"/ˈkemɪkl/","definition_zh":"化学的；化学制品、化学品；化工的；人工合成的","definition_en":"relating to chemistry; a substance produced or used by chemistry","core_image":"实验台上两只烧杯里的液体相遇，腾起一缕白雾，旁边摆着一排贴了标签的瓶子","scene":"实验台上两瓶无色液体被倒进同一只烧杯，杯口立刻翻起白雾，助教按住通风橱的拉门，说 This chemical must stay under the hood until the vapour settles.","sceneCN":"这里 chemical 指「化学药品、化学品」，取第 2 个义项（瓶子里那类具体物质）；句意为这种化学品必须留在通风橱下，直到雾气散尽。图中可辨识物件：烧杯、白雾、通风橱、试剂瓶。","pos":[{"tag":"adj.","zh":"化学的；与化学有关的（作定语，常修饰过程、性质、工业）"},{"tag":"n.","zh":"化学品、化学制品（可数，常用复数 chemicals）"}],"collocations":[{"phrase":"chemical reaction","zh":"化学反应"},{"phrase":"chemical engineering","zh":"化学工程"},{"phrase":"chemical weapon","zh":"化学武器"},{"phrase":"chemical change","zh":"化学变化"},{"phrase":"toxic chemicals","zh":"有毒化学品"},{"phrase":"chemical analysis","zh":"化学分析"}],"forms":[{"label":"原级（形容词）","form":"chemical"},{"label":"比较级","form":"more chemical"},{"label":"最高级","form":"most chemical"},{"label":"复数（名词）","form":"chemicals"},{"label":"副词","form":"chemically"},{"label":"名词（化学）","form":"chemistry"}],"derivatives":[{"word":"chemically","pos":"adv.","zh":"化学上；通过化学方法"},{"word":"chemistry","pos":"n.","zh":"化学；化学成分与相互作用"},{"word":"chemist","pos":"n.","zh":"化学家；药师"},{"word":"biochemical","pos":"adj.","zh":"生物化学的"}],"senses":[{"no":"01","title":"Relating to chemistry","titleCN":"与化学有关的","definition":"connected with the science that studies substances and how they combine and change","definitionCN":"与研究物质及其结合、变化的学科有关的","example":"The course covers the chemical principles behind every cleaning product.","exampleCN":"这门课讲解每一种清洁产品背后的化学原理。","why":"The adjective simply points to the discipline, so it can modify principles, laws, bonds or laboratories without naming a substance.","whyCN":"这个形容词只指向那门学科，因此可修饰原理、定律、化学键或实验室，而不指某种具体物质。"},{"no":"02","title":"A substance made by chemistry","titleCN":"化学品、化学制品","definition":"a substance obtained by a chemical process or sold as a chemical product","definitionCN":"通过化学过程获得的物质，或作为化工产品出售的物质","example":"The factory stores hundreds of chemicals in labelled drums.","exampleCN":"这家工厂把数百种化学品存放在贴了标签的桶里。","why":"Because industry needed a countable noun for what it handles, the adjective became a noun and now takes a plural.","whyCN":"工业需要为所处理的物质找一个可数名词，于是这个形容词转为名词，并有了复数。"},{"no":"03","title":"Industrial and engineering use","titleCN":"化工的、化学工程的","definition":"describing large-scale industrial processes and the engineering that runs them","definitionCN":"形容大规模工业过程及支撑这些过程的工程","example":"She works at a chemical plant on the coast.","exampleCN":"她在海边的一家化工厂工作。","why":"Once chemistry moved from the bench to the plant, chemical began to mark scale and industry rather than pure science.","whyCN":"当化学从实验台走向工厂，chemical 便开始标示规模与工业，而不再指纯科学。"},{"no":"04","title":"Involving a chemical change","titleCN":"化学变化的、发生化学反应的","definition":"describing a process in which substances become different substances","definitionCN":"形容物质变成另一种物质的过程","example":"Rust is the result of a chemical change, not a physical one.","exampleCN":"铁锈是化学变化的结果，而不是物理变化。","why":"This use marks the boundary with physical change, so chemical names the kind of process rather than a product.","whyCN":"这一用法用来划清与物理变化的界限，因此 chemical 指过程类别，而非产物。"},{"no":"05","title":"Artificial, not natural","titleCN":"人工合成的、非天然的","definition":"used informally to suggest that something is manufactured rather than grown or natural","definitionCN":"口语中暗示某物是制造出来的，而非天然生成或栽培的","example":"Shoppers increasingly avoid bread with a chemical taste.","exampleCN":"顾客越来越不愿意买带有化学味的面包。","why":"Because manufactured additives became common in food, the adjective took on a disapproving tone without changing its core meaning.","whyCN":"由于食品里的人工添加剂变得普遍，这个形容词在核心词义不变的情况下带上了一层贬义。"},{"no":"06","title":"Chemical weapons and agents","titleCN":"化学战剂的、化学武器的","definition":"describing poisonous substances designed or used to harm people in warfare","definitionCN":"形容被设计或用于战争中伤害人的有毒物质","example":"The treaty bans the stockpiling of chemical agents.","exampleCN":"该条约禁止囤积化学战剂。","why":"Military and legal writing fixed armed chemical agents as a class of their own, so the adjective became part of a treaty term.","whyCN":"军事与法律文本把武器化的化学物质固定为一个类别，于是该形容词成了条约术语的一部分。"},{"no":"07","title":"Chemical analysis and tests","titleCN":"化学分析的、用化学方法的","definition":"describing tests and measurements that identify substances by their reactions","definitionCN":"形容通过反应来鉴定物质的检验与测量","example":"A chemical test showed traces of lead in the water.","exampleCN":"一次化学检验显示水中有微量铅。","why":"The method is named after the science, so a chemical test means one performed by chemical means rather than by sight or sound.","whyCN":"方法以学科命名，因此 chemical test 指用化学手段、而非用视觉或声学手段完成的检验。"},{"no":"08","title":"Laboratory reagents","titleCN":"实验室药品、试剂","definition":"the bottles and powders kept in a laboratory for experiments","definitionCN":"实验室里为做实验而存放的瓶装与粉状物质","example":"The cupboard holds the chemicals needed for the titration.","exampleCN":"柜子里放着滴定所需的药品。","why":"In a laboratory the plural is a practical inventory word, close to reagents but broader.","whyCN":"在实验室里，复数形式是个实用的清点词，接近「试剂」但范围更宽。"}],"etymology":{"intro":{"en":"Chemical goes back through French and Medieval Latin to Greek khēmeia, the art of working metals, which reached Europe largely through Arabic al-kīmiyā. The adjective ending is Latin -alis. The modern sense tied to a science dates from the seventeenth and eighteenth centuries.","cn":"chemical 经法语与中世纪拉丁语上溯希腊语 khēmeia「冶炼金属之术」，该词主要经阿拉伯语 al-kīmiyā 传入欧洲。形容词词尾为拉丁 -alis。与近代学科相连的现代词义则形成于十七、十八世纪。"},"items":[{"era":"GREEK KHĒMEIA","en":"Source uncertain: khēmeia named the craft of treating metals, and its own derivation is debated. Some connect it with a verb for pouring, others with an old name for Egypt.","cn":"来源不确定：khēmeia 指处理金属的技艺，其自身来源有争论，有人认为与表示「倾倒」的动词有关，也有人联系到埃及的旧称。"},{"era":"ARABIC AL-KĪMIYĀ","en":"Arabic al-kīmiyā carried the Greek craft word into the Islamic world and added the definite article al-, which survives in the English alchemy.","cn":"阿拉伯语 al-kīmiyā 把这门希腊技艺之名带入伊斯兰世界，并加上了定冠词 al-，该冠词保留在英语 alchemy 中。"},{"era":"MEDIEVAL LATIN","en":"Medieval Latin alchimia and French alchimie spread the word north; the shortened stem chim- provided the base for the science name chemistry.","cn":"中世纪拉丁 alchimia 与法语 alchimie 把这个词传到北方；缩短后的词干 chim- 成为学科名 chemistry 的基础。"},{"era":"LATIN -ALIS","en":"The ending -ical is Latin -alis, meaning relating to, so chemical means relating to the metal-working craft and later to the science built on it.","cn":"词尾 -ical 来自拉丁 -alis「与…有关的」，因此 chemical 意为「与冶炼之术有关的」，后来转为「与建立在它之上的学科有关的」。"},{"era":"MODERN SCIENCE","en":"From the seventeenth century the word was attached to the new experimental study of substances, and by the nineteenth century it also named industrial products.","cn":"从十七世纪起，这个词被附着于新兴的实物实验研究；到十九世纪，它也用来指工业产品。"}]},"similar":{"note":{"en":"Group one holds words built on the same khēmeia stem or its Arabic form; group two holds neighbouring terms about substances and matters.","cn":"第一组是建立在同一 khēmeia 词干或其阿拉伯语形式上的词；第二组是关于物质与实体的相邻术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chemistry","ipa":"/ˈkemɪstri/","tag":"the discipline","definition":"The name of the science itself, from the same stem plus the subject ending -istry.","definitionCN":"学科本身的名字，由同一词干加表示学科的结尾 -istry 构成。"},{"word":"chemist","ipa":"/ˈkemɪst/","tag":"person, not substance","definition":"A person who practises chemistry, or in British use a pharmacist; in American English pharmacist is the usual word.","definitionCN":"从事化学的人，英式英语中也指药剂师；美式英语中药剂师通常另用 pharmacist。"},{"word":"alchemy","ipa":"/ˈælkəmi/","tag":"same Arabic article","definition":"The older metal-transmuting craft with al- attached; chemistry is the later science that grew out of it.","definitionCN":"带 al- 冠词的更早炼金术；chemistry 是从中长出的近代学科。"},{"word":"chemicals","ipa":"/ˈkemɪklz/","tag":"plural only","definition":"The plural noun for substances handled in quantity; the singular chemical is both adjective and countable noun.","definitionCN":"指被大量处理的物质的复数名词；单数 chemical 既是形容词也是可数名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"substance","ipa":"/ˈsʌbstəns/","tag":"neutral, general","definition":"Any kind of matter, natural or made; chemical adds the association with laboratory or industry.","definitionCN":"任何物质，天然或人造皆可；chemical 则附加了实验室或工业的联想。"},{"word":"compound","ipa":"/ˈkɒmpaʊnd/","tag":"technical, precise","definition":"A substance made of two or more elements chemically joined; it is narrower and more technical than chemical.","definitionCN":"由两种或以上元素以化学方式结合成的物质；比 chemical 更窄、更技术化。"},{"word":"reagent","ipa":"/riˈeɪdʒənt/","tag":"used to react","definition":"A substance added to produce a reaction or a test result; a chemical need not be used for reacting.","definitionCN":"为引发反应或产生检测结果而加入的物质；chemical 不必用于反应。"},{"word":"material","ipa":"/məˈtɪəriəl/","tag":"stuff for making","definition":"Matter used to make things, such as wood or metal; it stresses use, while chemical stresses composition.","definitionCN":"用于制造物品的物质，如木材或金属；它侧重用途，chemical 侧重成分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek and Arabic route, real fixed phrases and real derived words.","cn":"正常联想：真实的希腊语与阿拉伯语来源、真实搭配与真实派生词。"},"normal":[{"en":"Chemistry is the subject, chemical is the adjective, chemist is the person: one stem, three jobs.","cn":"chemistry 是学科，chemical 是形容词，chemist 是人：同一词干承担三种角色。"},{"en":"Alchemy keeps the Arabic article al-, a visible trace of the route into Europe.","cn":"alchemy 保留了阿拉伯语冠词 al-，是这条传入欧洲路径的可见痕迹。"},{"en":"Chemical change and physical change are a standard pair in textbooks.","cn":"化学变化与物理变化是教科书里的标准对照。"},{"en":"Chemical engineering and chemical plant mark the industrial scale.","cn":"化学工程与化工厂标出的是工业规模。"},{"en":"The plural chemicals is a cupboard inventory word in every laboratory.","cn":"复数 chemicals 是每个实验室清点柜子时的用语。"}],"abstract":[{"en":"Picture two clear liquids that become green the moment they touch: the change is the point.","cn":"想象两瓶澄清液体一接触就变绿：变化本身就是重点。"},{"en":"Picture a row of identical bottles whose only difference is the label on the cap.","cn":"想象一排一样的瓶子，唯一的区别是瓶盖上的标签。"},{"en":"Picture a fume hood drawing white vapour away before anyone breathes it.","cn":"想象通风橱在任何人吸入之前把白雾抽走。"}]},"examples":[{"en":"The label lists every chemical used in the finishing process.","cn":"标签列出了后整理工序中用到的每一种化学品。"},{"en":"Chemical analysis found no trace of the banned additive.","cn":"化学分析未发现禁用添加剂的痕迹。"},{"en":"The river carries chemical waste from three upstream plants.","cn":"这条河承载着上游三家工厂排出的化学废料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「开米扣」——实验台上开瓶、量米、扣上盖子，全是化学动作，chemical 就是化学的、化学品","word":"chemical"},"root":"希腊 khēmeia「冶炼金属之术」，经阿拉伯语 al-kīmiyā 与中世纪拉丁 alchimia 传入欧洲，加拉丁形容词后缀 -alis 成 chemical；同词干另出 chemistry、chemist、alchemy。","sensesIntro":{"en":"Eight senses move from the adjective that points at the science, to the countable substance, to industry, to the kind of change, to an artificial taste, to weapons, to tests, and back to the laboratory shelf.","cn":"八个义项从指向学科的形容词，走到可数的物质、工业规模、变化类别、人工合成的贬义、化学武器、化学检验，最后回到实验室的柜子。"},"semanticMap":{"core":{"en":"CORE IMAGE: two liquids meeting in a beaker and turning into something else.","cn":"核心意象：两只烧杯里的液体相遇，变成另一样东西。"},"chain":["THE SCIENCE","THE SUBSTANCE","INDUSTRIAL SCALE","CHEMICAL CHANGE","WEAPONISED AGENT","ANALYTICAL METHOD"],"branches":[{"senses":"S1","en":"DISCIPLINE: the adjective can modify laws, bonds and classrooms without naming any substance.","cn":"学科：该形容词可修饰定律、化学键与课堂，而不指任何物质。"},{"senses":"S2 · S8","en":"THINGS ON A SHELF: countable bottles in a factory store and reagents in a laboratory cupboard.","cn":"架上的东西：工厂仓库里可数的桶与实验室柜里的试剂。"},{"senses":"S3","en":"SCALE: the plant and the engineering turn a bench science into an industry.","cn":"规模：工厂与工程把实验台上的学问变成一门工业。"},{"senses":"S4 · S6 · S7","en":"PROCESS AND PURPOSE: the change itself, the weapon built on it, and the test that detects it.","cn":"过程与用途：变化本身、由它造出的武器，以及检出它的检验。"},{"senses":"S5","en":"TASTE: the everyday disapproving sense of something manufactured rather than natural.","cn":"口感：日常贬义，指制造出来的而非天然的东西。"}]},"affixes":{"intro":{"en":"Chemical can be read as the stem chem- plus the adjective ending -ical, and the same stem also builds the subject name and the person noun.","cn":"chemical 可拆成词干 chem- 加形容词词尾 -ical，同一词干还构成学科名与人名名词。"},"latinIntro":{"en":"The stem is Greek and its route runs through Arabic, so there is no inherited Latin noun for the science; Latin supplied the adjective ending -alis and the article-shaped al- came from Arabic.","cn":"词干来自希腊语，且路径经过阿拉伯语，因此这门学问没有拉丁语祖传名词；拉丁语提供的是形容词词尾 -alis，而形似冠词的 al- 来自阿拉伯语。"},"items":[{"word":"chem-","structure":"chem- (Greek stem from khēmeia, metal-working craft)","meaning":"chemistry; chemical treatment","meaningCN":"化学；化学处理","example":"The prefix appears in chemistry, chemist and chemical.","exampleCN":"这一词干出现在 chemistry、chemist 与 chemical 中。"},{"word":"al-","structure":"al- (Arabic definite article)","meaning":"the, in Arabic phrases","meaningCN":"阿拉伯语定冠词","example":"Alchemy preserves this article at the front of the word.","exampleCN":"alchemy 把这个冠词保留在词首。"},{"word":"-ical","structure":"-ical (Latin -alis, relating to)","meaning":"relating to","meaningCN":"与…有关的","example":"Chemical, physical and historical all use the same ending.","exampleCN":"chemical、physical 与 historical 都用同一个词尾。"},{"word":"chemistry","structure":"chem- + -istry (subject or practice)","meaning":"the science of substances","meaningCN":"研究物质的学科","example":"Chemistry explains why iron rusts.","exampleCN":"化学解释了铁为什么生锈。"},{"word":"chemist","structure":"chem- + -ist (person who practises)","meaning":"a specialist in chemistry","meaningCN":"化学专业者","example":"The chemist tested the sample twice.","exampleCN":"这位化学家把样品测了两遍。"},{"word":"chemically","structure":"chemical + -ly (in a manner)","meaning":"by chemical means","meaningCN":"以化学方式","example":"The paper was chemically treated to resist water.","exampleCN":"这种纸经过化学处理以防水。"},{"word":"alchemy","structure":"al- + chem- (Arabic article plus Greek stem)","meaning":"the older craft of transmuting metals","meaningCN":"较早的金属转化之术","example":"Alchemy sought a way to turn lead into gold.","exampleCN":"炼金术寻找把铅变成金的办法。"},{"word":"biochemical","structure":"bio- (life) + chemical","meaning":"relating to the chemistry of living things","meaningCN":"与生物体内化学有关的","example":"Biochemical tests trace the enzyme in the blood.","exampleCN":"生化检验追踪血液中的这种酶。"},{"word":"petrochemical","structure":"petro- (rock, oil) + chemical","meaning":"a chemical derived from petroleum","meaningCN":"由石油提炼的化学品","example":"Petrochemicals feed the plastics industry.","exampleCN":"石油化学品支撑着塑料工业。"},{"word":"chemical-free","structure":"chemical + -free (without)","meaning":"claimed to contain no added chemicals","meaningCN":"声称未加化学制品的","example":"The label says chemical-free, though the law is loose.","exampleCN":"标签写着无化学添加，尽管法规对此较宽松。"}],"latinEntries":[{"word":"-alis","structure":"Latin adjectival suffix -alis (relating to)","meaning":"relating to","meaningCN":"与…有关的","example":"Latin naturalis, relating to nature, uses the same ending.","exampleCN":"拉丁语 naturalis（与自然有关的）使用同一词尾。"}]}},{"word":"chemical reaction","ipa_uk":"/ˈkemɪkl riˈækʃn/","ipa_us":"/ˈkemɪkl riˈækʃn/","definition_zh":"化学反应；物质相互转化为新物质的过程","definition_en":"a process in which substances change into different substances by rearranging their atoms","core_image":"烧杯里一蓝一绿两种溶液相遇，蓝色迅速褪去，气泡沿杯壁一串串往上爬","scene":"演示台上，学生把两种溶液倒进同一只烧杯，蓝色立即褪成浅绿，气泡顺着杯壁上浮，老师说 That colour change is proof that a chemical reaction has already begun.","sceneCN":"这里 chemical reaction 指「物质转变成新物质的过程」，取第 1 个义项（反应本身）；句意为这个颜色变化证明化学反应已经开始。图中可辨识物件：烧杯、气泡、滴管、实验记录板。","pos":[{"tag":"n.","zh":"化学反应（可数，复数 chemical reactions）"}],"collocations":[{"phrase":"a chemical reaction takes place","zh":"发生化学反应"},{"phrase":"chemical reaction rate","zh":"化学反应速率"},{"phrase":"reversible chemical reaction","zh":"可逆化学反应"},{"phrase":"exothermic chemical reaction","zh":"放热化学反应"},{"phrase":"chemical reaction between A and B","zh":"甲与乙之间的化学反应"},{"phrase":"trigger a chemical reaction","zh":"引发化学反应"}],"forms":[{"label":"复数","form":"chemical reactions"},{"label":"相关动词","form":"react"},{"label":"相关名词（反应物）","form":"reactant"},{"label":"相关名词（生成物）","form":"product"},{"label":"相关形容词（反应性的）","form":"reactive"}],"derivatives":[{"word":"react","pos":"v.","zh":"反应；起化学反应"},{"word":"reaction","pos":"n.","zh":"反应；反应过程"},{"word":"reactant","pos":"n.","zh":"反应物"},{"word":"reactivity","pos":"n.","zh":"反应活性、活泼性"}],"senses":[{"no":"01","title":"Substances becoming new substances","titleCN":"化学反应（基本定义）","definition":"a process in which atoms regroup so that the starting materials become different materials","definitionCN":"原子重新组合，使原来的物质变成不同物质的过程","example":"Baking soda and vinegar give a familiar chemical reaction at home.","exampleCN":"小苏打与醋在家里就能做出一个熟悉的化学反应。","why":"Reaction here means the mutual action of two substances, so the phrase names what happens when they act on each other.","whyCN":"reaction 意为「相互作用」，因此这个短语命名的是两种物质彼此作用时发生的事。"},{"no":"02","title":"Heat released or absorbed","titleCN":"放热与吸热反应","definition":"the same process described by whether it warms its surroundings or draws heat in","definitionCN":"同一过程按它使周围变热还是吸走热量来描述的两种情形","example":"The chemical reaction in the hand warmer releases heat for hours.","exampleCN":"暖手宝里的化学反应会持续放热数小时。","why":"Breaking and forming bonds either costs or releases energy, so every reaction can be placed on a heat scale.","whyCN":"化学键的断裂与形成要么消耗能量、要么释放能量，因此每个反应都能放在一条热量尺度上。"},{"no":"03","title":"Types of reaction","titleCN":"反应类型：化合、分解、置换等","definition":"a classification such as combination, decomposition, displacement or double displacement","definitionCN":"按化合、分解、置换或复分解等方式划分的类别","example":"The teacher drew a displacement chemical reaction on the board.","exampleCN":"老师在黑板上画了一个置换反应。","why":"Classification follows the pattern of what leaves and what joins, so the phrase is reused as a label for each pattern.","whyCN":"分类依据的是哪些成分离开、哪些成分结合，因此这个短语被反复用作各类模式的标签。"},{"no":"04","title":"Rate and conditions","titleCN":"反应速率与条件","definition":"the speed of the process and the temperature, pressure or catalyst that control it","definitionCN":"该过程进行的快慢，以及控制它的温度、压强或催化剂","example":"A catalyst speeds up the chemical reaction without being consumed.","exampleCN":"催化剂能加快化学反应而不被消耗。","why":"Industry cares how fast a batch finishes, so the phrase often appears alongside rate, time and yield.","whyCN":"工业关心一批料多快做完，因此这个短语常与速率、时间和产率一起出现。"},{"no":"05","title":"Reversible reactions and equilibrium","titleCN":"可逆反应与化学平衡","definition":"a process that can run backwards, settling at a balance between forward and reverse change","definitionCN":"能反向进行、并在正逆变化之间达到平衡的过程","example":"In a closed tube the chemical reaction reaches equilibrium and appears to stop.","exampleCN":"在封闭管中，该化学反应达到平衡，表面看像停止了。","why":"Because many reactions do not run to completion, the same phrase covers the two-way case and its balance point.","whyCN":"许多反应并不会进行到底，因此同一短语也覆盖双向进行的情形及其平衡点。"},{"no":"06","title":"Reactions inside living things","titleCN":"生物体内的化学反应","definition":"the reactions of metabolism, such as digestion or respiration, that keep an organism alive","definitionCN":"消化、呼吸这类维持生物体存活的代谢反应","example":"Enzymes control every chemical reaction that keeps the cell alive.","exampleCN":"酶控制着维持细胞存活的每一个化学反应。","why":"Biochemistry applies the same phrase to cells, adding the idea that the reactions are guided by proteins.","whyCN":"生物化学把这同一短语用于细胞，并附加了「反应由蛋白质引导」这一层意思。"},{"no":"07","title":"A chain of consequences","titleCN":"比喻：连锁反应","definition":"a figurative use for one event setting off a series of related changes","definitionCN":"比喻用法，指一个事件引发一连串相关变化","example":"The tariff set off a chemical reaction across three industries.","exampleCN":"这项关税在三个行业间引发了一连串反应。","why":"The metaphor borrows the idea that a small trigger can change the whole mixture, not just its starting point.","whyCN":"这一比喻借用了「少量触发物能改变整锅混合物」的观念，而不只是改变起始处。"},{"no":"08","title":"Instant personal chemistry","titleCN":"口语：人与人之间立刻来电或立刻不合","definition":"an informal use for an immediate, almost physical attraction or clash between two people","definitionCN":"口语用法，指两人之间立刻产生近乎本能的吸引或冲突","example":"There was an obvious chemical reaction when the two leads first read together.","exampleCN":"两位主角第一次对台词时，明显立刻有了化学反应。","why":"Everyday speech borrowed the laboratory phrase because attraction also feels like something happening beyond deliberate choice.","whyCN":"日常口语借用实验室的说法，因为吸引力也像是发生在自觉选择之外的事情。"}],"etymology":{"intro":{"en":"The phrase joins chemical, from Greek khēmeia through Arabic al-kīmiyā, with reaction, from Latin re- back plus agere to do. Reaction first meant any response and was narrowed to chemical processes in the seventeenth and eighteenth centuries.","cn":"这个短语把 chemical 与 reaction 结合：前者来自希腊 khēmeia 并经阿拉伯语 al-kīmiyā，后者由拉丁 re-「回」加 agere「做」构成。reaction 最初指任何回应，十七、十八世纪才收窄到化学过程。"},"items":[{"era":"LATIN AGERE","en":"Agere meant to drive, do or act, and its participle actus underlies act, action and reaction.","cn":"agere 意为驱动、做、行动，其分词 actus 是 act、action 与 reaction 的共同基础。"},{"era":"RE- PLUS ACT","en":"Latin reagere meant to act back or act in return, so reaction began as the answer one thing gives to another.","cn":"拉丁 reagere 意为反过来作用、回应，因此 reaction 最初指一物对另一物给出的回应。"},{"era":"CHEMISTRY ADOPTS IT","en":"From the seventeenth century experimenters described two substances acting on each other as a reaction, and the phrase chemical reaction fixed that usage.","cn":"从十七世纪起，实验者把两种物质彼此作用描述为 reaction，chemical reaction 这一短语把该用法固定下来。"},{"era":"MEASUREMENT ERA","en":"Nineteenth-century chemistry added rate, equilibrium and catalysis, so the phrase also came to name a quantity that can be timed and balanced.","cn":"十九世纪的化学加入了速率、平衡与催化，于是这个短语也开始指可以被计时和配平的量。"},{"era":"FIGURATIVE SPREAD","en":"Modern journalism and everyday speech applied the phrase to social chains and personal attraction, keeping the image of one thing setting another off.","cn":"现代新闻与日常口语把这个短语用到社会连锁与个人吸引上，保留了「一物触发另一物」的意象。"}]},"similar":{"note":{"en":"Group one holds phrases built on the same chemical or reaction element; group two holds neighbouring process words that are often confused with a reaction.","cn":"第一组是含相同 chemical 或 reaction 成分的短语；第二组是容易被误当成反应的过程词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chemical change","ipa":"/ˈkemɪkl tʃeɪndʒ/","tag":"the outcome, not the event","definition":"The kind of change a reaction produces, named by its result; textbooks contrast it with physical change.","definitionCN":"指反应所产生的那类变化，以结果命名；教科书把它与物理变化对照。"},{"word":"chemical equation","ipa":"/ˈkemɪkl ɪˈkweɪʒn/","tag":"the written form","definition":"The symbolic record of a reaction, showing reactants and products with coefficients.","definitionCN":"反应的符号记录，用系数列出反应物与生成物。"},{"word":"nuclear reaction","ipa":"/ˈnjuːkliə riˈækʃn/","tag":"changed nucleus","definition":"A process that alters atomic nuclei and releases far more energy; electrons are untouched.","definitionCN":"改变原子核并释放远多能量的过程；电子并不参与。"},{"word":"reaction","ipa":"/riˈækʃn/","tag":"the general noun","definition":"Any response, from a person's reply to a chemical process; the full phrase narrows it to substances.","definitionCN":"任何回应，从人的反应到化学过程；完整短语把它收窄到物质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"physical change","ipa":"/ˈfɪzɪkl tʃeɪndʒ/","tag":"no new substance","definition":"A change of shape, state or size with no new substance formed, such as melting ice.","definitionCN":"形状、状态或大小的改变，不产生新物质，例如冰融化。"},{"word":"process","ipa":"/ˈprəʊses/","tag":"wider term","definition":"Any series of steps producing a result; a reaction is one kind of process with new substances as its result.","definitionCN":"产生结果的任何一系列步骤；反应是其中以新物质为结果的一类。"},{"word":"transformation","ipa":"/ˌtrænsfəˈmeɪʃn/","tag":"emphasis on result","definition":"A thorough change of form; it stresses the end state rather than the mechanism that brings it about.","definitionCN":"形式上的彻底改变；侧重最终状态，而非造成改变的作用机制。"},{"word":"interaction","ipa":"/ˌɪntərˈækʃn/","tag":"mutual effect","definition":"Any mutual effect between things; it becomes a reaction only when new substances form.","definitionCN":"事物之间的任何相互影响；只有形成新物质时才成为反应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, real textbook pairs and real fixed phrases.","cn":"正常联想：真实的拉丁构件、真实教科书对照与真实搭配。"},"normal":[{"en":"Re- plus act equals acting back: two substances act on each other.","cn":"re- 加 act 就是「反过来作用」：两种物质彼此作用。"},{"en":"Reactant in, product out: the two words frame every reaction.","cn":"反应物进去，生成物出来：这两个词框住了每一个反应。"},{"en":"Chemical change is the result, chemical reaction is the event.","cn":"化学变化是结果，化学反应是事件。"},{"en":"Exothermic and endothermic mark the heat direction of a reaction.","cn":"放热与吸热标出反应的热量方向。"},{"en":"A catalyst changes the speed, never the reactants.","cn":"催化剂改变速度，从不改变反应物。"}],"abstract":[{"en":"Picture a match struck in a dark room: one small action sets the whole mixture alight.","cn":"想象在暗室里划亮一根火柴：一个微小动作点燃了整团混合物。"},{"en":"Picture a seesaw that settles and then looks perfectly still while both ends still move.","cn":"想象一架跷跷板停下来看似纹丝不动，其实两端仍在动。"},{"en":"Picture blue ink dropped into clear water until every part of the glass has changed colour.","cn":"想象一滴蓝墨落进清水，直到整杯水都换了颜色。"}]},"examples":[{"en":"A chemical reaction in the battery supplies the phone with current.","cn":"电池里的化学反应为手机提供电流。"},{"en":"The experiment failed because the chemical reaction ran too slowly.","cn":"实验失败是因为化学反应进行得太慢。"},{"en":"Rusting is a slow chemical reaction that no paint can fully stop.","cn":"生锈是一种缓慢的化学反应，任何油漆都无法完全阻止。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「开米扣 瑞爱克神」——开瓶量米扣盖，两种东西一碰就翻脸，正是化学反应","word":"chemical reaction"},"root":"chemical（希腊 khēmeia 经阿拉伯语 al-kīmiyā、中世纪拉丁 alchimia，加拉丁 -alis）+ reaction（拉丁 re-「回、再」+ agere「做、驱动」的名词形式 reactio）；「物质彼此作用而生成新物质」。","sensesIntro":{"en":"Eight senses follow one process viewed from different angles: the basic event, its heat, its type, its speed, its reversibility, its version inside a cell, and two figurative uses borrowed by journalism and everyday speech.","cn":"八个义项是同一过程的不同侧面：基本事件、热量、类型、速率、可逆性、细胞内的版本，以及被新闻与口语借走的两个比喻用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: two clear liquids meeting and turning green with bubbles.","cn":"核心意象：两瓶澄清液体相遇，变绿并冒起气泡。"},"chain":["NEW SUBSTANCE","HEAT EXCHANGE","REACTION TYPE","RATE AND CATALYST","EQUILIBRIUM","LIVING CELLS"],"branches":[{"senses":"S1","en":"THE EVENT: atoms regroup and the starting materials are gone.","cn":"事件：原子重新组合，原来的物质不再存在。"},{"senses":"S2 · S3","en":"ACCOUNTING AND NAMING: heat tells you the energy side, structure tells you the type.","cn":"记账与命名：热量说明能量收支，结构说明反应类型。"},{"senses":"S4 · S5","en":"TIME: how fast it runs, and whether it can also run backwards.","cn":"时间：它跑得多快，以及能否反向跑。"},{"senses":"S6","en":"CELLS: the same event, guided by enzymes, keeps an organism alive.","cn":"细胞：同一事件在酶的引导下维持着生物体存活。"},{"senses":"S7 · S8","en":"METAPHOR: chains of consequences and instant attraction both borrow the laboratory image.","cn":"比喻：连锁后果与即时吸引都借用了实验室的意象。"}]},"affixes":{"intro":{"en":"The phrase is built from two analyzable words: chemical from the chem- stem, and reaction from re- plus the act- root plus -ion.","cn":"这个短语由两个可分析的词构成：chemical 来自 chem- 词干，reaction 由 re- 加 act- 词根再加 -ion。"},"latinIntro":{"en":"Reaction is fully Latin in its pieces, while the chem- stem is Greek with an Arabic route. The Latin entries below therefore cover the re-, act- and -ion elements.","cn":"reaction 的各个构件都来自拉丁语，而 chem- 词干来自希腊语并经过阿拉伯语。因此下面的拉丁词条覆盖 re-、act- 与 -ion 三部分。"},"items":[{"word":"re-","structure":"re- (Latin prefix, back or again)","meaning":"back; again","meaningCN":"回；再次","example":"Return, recall and react all begin with the same prefix.","exampleCN":"return、recall 与 react 都以同一前缀开头。"},{"word":"act-","structure":"act- (Latin root from agere, to do or drive)","meaning":"do; drive; set in motion","meaningCN":"做；驱动；使运动","example":"Action and agent grow from the same root.","exampleCN":"action 与 agent 由同一词根长出。"},{"word":"-ion","structure":"-ion (Latin noun suffix, act or result)","meaning":"the act or result of","meaningCN":"…的行为或结果","example":"Reaction names the act of acting back.","exampleCN":"reaction 指「反过来作用」这一行为。"},{"word":"react","structure":"re- + act (verb)","meaning":"to act in response","meaningCN":"作出反应；起反应","example":"Sodium reacts violently with water.","exampleCN":"钠与水剧烈反应。"},{"word":"reaction","structure":"re- + act- + -ion","meaning":"a response or a chemical process","meaningCN":"反应；化学过程","example":"The reaction produced a gas and a salt.","exampleCN":"该反应生成了一种气体和一种盐。"},{"word":"reactant","structure":"react + -ant (thing that performs the action)","meaning":"a substance that undergoes a reaction","meaningCN":"参与反应的物质","example":"Oxygen is a reactant in combustion.","exampleCN":"氧是燃烧中的一种反应物。"},{"word":"reactive","structure":"react + -ive (having the quality)","meaning":"ready to undergo reaction","meaningCN":"容易发生反应的","example":"Reactive metals must be stored under oil.","exampleCN":"活泼金属必须存放在油下。"},{"word":"reactivity","structure":"reactive + -ity (state)","meaning":"the tendency to react","meaningCN":"反应活性、活泼程度","example":"Reactivity falls down the group.","exampleCN":"反应活性沿该族向下递减。"},{"word":"reactor","structure":"react + -or (device or agent)","meaning":"a vessel where a reaction is carried out","meaningCN":"进行反应的容器或装置","example":"The reactor was cooled before the next batch.","exampleCN":"下一批之前反应器被冷却了。"},{"word":"chem-","structure":"chem- (Greek stem, metal-working craft)","meaning":"chemistry","meaningCN":"化学","example":"The stem appears in chemical and chemistry.","exampleCN":"该词干出现在 chemical 与 chemistry 中。"}],"latinEntries":[{"word":"agere","structure":"Latin verb agere (ag-, actum; to do or drive)","meaning":"to do, drive, act","meaningCN":"做、驱动、行动","example":"Latin agit means he does or drives.","exampleCN":"拉丁语 agit 意为「他做、他驱动」。"},{"word":"reagere","structure":"re- (back, again) + agere (do, drive)","meaning":"to act back, react","meaningCN":"反过来作用、回应","example":"English react is built from the same re- plus act, not borrowed whole from Latin.","exampleCN":"英语 react 用的是同一组 re- 加 act，并非整体借自拉丁语。"}]}},{"word":"chemical weathering","ipa_uk":"/ˈkemɪkl ˈweðərɪŋ/","ipa_us":"/ˈkemɪkl ˈweðərɪŋ/","definition_zh":"化学风化；岩石因化学作用而分解、改变成分的过程","definition_en":"the breakdown of rock by chemical processes such as dissolution, oxidation and hydrolysis","core_image":"石灰岩崖面被雨水冲出密密的浅沟，岩石边缘发白疏松，脚边落着细碎的岩屑","scene":"雨后的石灰岩崖面布满浅浅的溶蚀沟纹，岩角用手一摸就掉渣，地理老师指着崖壁说 Chemical weathering has carved these grooves over thousands of years.","sceneCN":"这里 chemical weathering 指「岩石因化学作用而分解的过程」，取第 1 个义项（总称）；句意为化学风化在数千年间刻出了这些沟纹。图中可辨识物件：石灰岩崖面、溶蚀沟、岩屑、雨水痕。","pos":[{"tag":"n.","zh":"化学风化（不可数，地质学与地理学用语）"}],"collocations":[{"phrase":"chemical weathering of limestone","zh":"石灰岩的化学风化"},{"phrase":"rate of chemical weathering","zh":"化学风化速率"},{"phrase":"chemical weathering processes","zh":"化学风化过程"},{"phrase":"chemical weathering and erosion","zh":"化学风化与侵蚀"},{"phrase":"enhanced chemical weathering","zh":"强化化学风化（固碳技术用语）"},{"phrase":"susceptible to chemical weathering","zh":"易受化学风化"}],"forms":[{"label":"不可数名词","form":"chemical weathering"},{"label":"相关动词","form":"weather"},{"label":"相关形容词（风化的）","form":"weathered"},{"label":"对照术语（物理风化）","form":"physical weathering"},{"label":"对照术语（生物风化）","form":"biological weathering"}],"derivatives":[{"word":"weather","pos":"v.","zh":"风化；使受风吹雨打"},{"word":"weathered","pos":"adj.","zh":"风化的；受日晒雨淋而变旧的"},{"word":"weathering","pos":"n.","zh":"风化作用"},{"word":"chemical","pos":"adj./n.","zh":"化学的；化学品"}],"senses":[{"no":"01","title":"Rock broken down by chemistry","titleCN":"化学风化（总称）","definition":"the whole set of processes in which chemical reactions alter rock at the surface","definitionCN":"地表岩石因化学反应而被改变的整套过程","example":"Chemical weathering turns hard granite into soft clay over long periods.","exampleCN":"化学风化在漫长时间里把坚硬的花岗岩变成松软的黏土。","why":"Weathering means exposure to the elements, and the modifier says the damage is done by reaction rather than by force.","whyCN":"weathering 指受自然力作用，前面的修饰语说明破坏来自化学反应而非机械力。"},{"no":"02","title":"Dissolution","titleCN":"溶解作用","definition":"the process in which water simply takes soluble minerals out of the rock and carries them away","definitionCN":"水把岩石中的可溶矿物直接带走的过程","example":"Dissolution removed the salt beds and left hollows in the cliff.","exampleCN":"溶解作用带走了盐层，在崖壁上留下空洞。","why":"Some minerals dissolve in pure water without any new compound forming, so this is the simplest branch of chemical weathering.","whyCN":"有些矿物在纯水中即可溶解而不生成新化合物，因此这是化学风化里最单纯的一支。"},{"no":"03","title":"Oxidation","titleCN":"氧化作用","definition":"the reaction of iron-bearing minerals with oxygen, which leaves rock stained and crumbly","definitionCN":"含铁矿物与氧反应，使岩石染上锈色且变脆的过程","example":"Oxidation gives the sandstone its red bands and weakens the cement between grains.","exampleCN":"氧化作用给砂岩留下红色条带，并削弱颗粒间的胶结。","why":"Iron loses electrons to oxygen and forms oxides, which take up more space and crack the surrounding mineral.","whyCN":"铁把电子让给氧而形成氧化物，体积变大，撑裂周围的矿物。"},{"no":"04","title":"Hydrolysis","titleCN":"水解作用","definition":"the reaction of silicate minerals with water, producing clays and freeing soluble ions","definitionCN":"硅酸盐矿物与水反应，生成黏土并释放可溶离子的过程","example":"Hydrolysis of feldspar is the main reason granite turns to clay.","exampleCN":"长石的水解是花岗岩变成黏土的主要原因。","why":"Water splits the mineral structure and inserts hydrogen, so the crystal is rebuilt as a softer sheet silicate.","whyCN":"水把矿物结构拆开并插入氢，于是晶体被重组成较软的层状硅酸盐。"},{"no":"05","title":"Carbonation","titleCN":"碳酸化作用（碳酸溶蚀）","definition":"the attack of weak carbonic acid on limestone and similar rocks, carving caves and grooves","definitionCN":"弱碳酸对石灰岩一类岩石的侵蚀，形成洞穴与沟纹","example":"Carbonation widened the joints into the deep grooves on the limestone pavement.","exampleCN":"碳酸化作用把节理拓宽成石灰岩台面上的深沟。","why":"Rain absorbs carbon dioxide and becomes a weak acid that dissolves calcium carbonate, which is why limestone landscapes are so pitted.","whyCN":"雨水吸收二氧化碳变成弱酸，能溶解碳酸钙，因此石灰岩地貌千疮百孔。"},{"no":"06","title":"Weathering helped by organisms","titleCN":"生物参与的化学风化","definition":"the same reactions speeded up by acids released from roots, lichen and soil microbes","definitionCN":"由根系、地衣与土壤微生物释放的酸所加速的同类反应","example":"Lichen acids drive chemical weathering on bare rock long before soil forms.","exampleCN":"地衣分泌的酸在土壤形成之前很久就在裸岩上推动化学风化。","why":"Living things supply the acid and the chelating agents, so biology can be the engine even though the process stays chemical.","whyCN":"生物提供酸与螯合剂，因此过程虽仍是化学的，引擎却来自生物。"},{"no":"07","title":"Decay of building stone","titleCN":"建筑石材的化学风化","definition":"the damage done to monuments and facades by rain, salts and polluted air","definitionCN":"雨水、盐分与污染空气对纪念碑和建筑立面的破坏","example":"Chemical weathering has softened the carved letters on the old cathedral.","exampleCN":"化学风化已经把老教堂上雕刻的字母侵蚀得发软。","why":"Conservation adopted the geological term because stone in a city faces the same reactions at a much faster rate.","whyCN":"文物保护借用了这个地质术语，因为城市里的石头面对的是同样的反应，只是速度快得多。"},{"no":"08","title":"A figurative slow corrosion","titleCN":"比喻：制度或语言的缓慢侵蚀","definition":"a figurative use for the gradual wearing away of rules, meanings or trust","definitionCN":"比喻用法，指规则、词义或信任被慢慢磨蚀","example":"Critics describe the slow chemical weathering of the old legal wording.","exampleCN":"批评者把旧法律措辞的缓慢侵蚀称为一种化学风化。","why":"The metaphor works because the change is invisible day to day yet undeniable over decades, exactly like rock decay.","whyCN":"这个比喻成立，是因为变化日常看不见，几十年后却无法否认，正与岩石的衰变相同。"}],"etymology":{"intro":{"en":"The phrase pairs chemical, from Greek khēmeia through Arabic al-kīmiyā, with weathering, from Old English weder, weather. The geological sense of weathering was fixed in the eighteenth and nineteenth centuries.","cn":"这个短语把 chemical 与 weathering 结合：前者出自希腊 khēmeia 并经阿拉伯语 al-kīmiyā，后者来自古英语 weder「天气」。风化在地质学上的含义于十八、十九世纪固定下来。"},"items":[{"era":"OLD ENGLISH WEDER","en":"Weder meant weather, wind and storm, and the verb weather meant to expose something to the open air and its effects.","cn":"weder 意为天气、风与风暴，动词 weather 意为把某物暴露在户外及其影响之下。"},{"era":"WEATHERING AS A TERM","en":"Geologists took the noun weathering for the decay of rock in place, as distinct from erosion, which removes the debris.","cn":"地质学家用 weathering 这一名词指岩石在原地发生的衰变，以区别于把碎屑搬走的侵蚀。"},{"era":"CHEMICAL VERSUS PHYSICAL","en":"Once the term was split, chemical weathering covered reactions such as dissolution and oxidation, while physical weathering covered fracturing by frost and pressure.","cn":"术语分化之后，化学风化涵盖溶解、氧化一类反应，物理风化则涵盖冰冻与压力造成的破裂。"},{"era":"GREEK STEM","en":"Chemical carries the Greek craft word khēmeia, which reached Europe through Arabic al-kīmiyā and Medieval Latin alchimia.","cn":"chemical 携带希腊技艺之名 khēmeia，该词经阿拉伯语 al-kīmiyā 与中世纪拉丁 alchimia 传入欧洲。"},{"era":"MODERN USE","en":"Twentieth-century soil science and climate research widened the phrase to rates, budgets and even deliberate carbon capture by rock powder.","cn":"二十世纪的土壤学与气候研究把这个短语扩展到速率、收支，甚至用岩石粉末刻意固碳的做法。"}]},"similar":{"note":{"en":"Group one holds the two sibling terms that are most often confused with this one; group two holds related landscape and decay words.","cn":"第一组是最常与本词混淆的两个并列术语；第二组是相关的地貌与衰变用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"physical weathering","ipa":"/ˈfɪzɪkl ˈweðərɪŋ/","tag":"force, not reaction","definition":"Breakdown by frost, salt growth, pressure release or abrasion, with the mineral makeup unchanged.","definitionCN":"由冰冻、盐结晶、卸荷或磨蚀造成的破碎，矿物成分不变。"},{"word":"biological weathering","ipa":"/ˌbaɪəˈlɒdʒɪkl ˈweðərɪŋ/","tag":"agent, not mechanism","definition":"Weathering in which roots, animals or microbes provide the force or the acid; chemically it may overlap with this term.","definitionCN":"由根系、动物或微生物提供力或酸的风化；在化学机制上可与化学风化重叠。"},{"word":"erosion","ipa":"/ɪˈrəʊʒn/","tag":"removal, not decay","definition":"The transport of loosened material by water, wind or ice; weathering breaks rock, erosion carries it away.","definitionCN":"被松动的物质被水、风或冰搬运走；风化把岩石弄碎，侵蚀把碎屑带走。"},{"word":"chemical change","ipa":"/ˈkemɪkl tʃeɪndʒ/","tag":"general chemistry","definition":"Any change producing new substances; it says nothing about rock, climate or landscape.","definitionCN":"任何生成新物质的改变；与岩石、气候或地貌无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dissolution","ipa":"/ˌdɪsəˈluːʃn/","tag":"one branch","definition":"The specific process of a mineral going into solution; it is one mechanism inside chemical weathering.","definitionCN":"矿物进入溶液的具体过程；它是化学风化的机制之一。"},{"word":"corrosion","ipa":"/kəˈrəʊʒn/","tag":"usually metals","definition":"Gradual chemical attack, most often of metal; for stone the same idea is usually called weathering.","definitionCN":"渐进性的化学侵蚀，多用于金属；对石材而言同一概念通常称作风化。"},{"word":"decomposition","ipa":"/ˌdiːkɒmpəˈzɪʃn/","tag":"breaking down","definition":"The breaking apart of a substance into simpler parts; it stresses the result rather than the setting.","definitionCN":"物质裂解为更简单成分；侧重结果，而非发生场所。"},{"word":"leaching","ipa":"/ˈliːtʃɪŋ/","tag":"removal by water","definition":"The removal of soluble material by water moving through soil or rock; it is often the visible consequence of weathering.","definitionCN":"流水带走土壤或岩石中可溶物质；常是风化可见的后果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Old English weather word, real branches of the process and real paired terms.","cn":"正常联想：真实的古英语 weather 词、真实的机制分支与真实的成对术语。"},"normal":[{"en":"Weathering is rock left out in the weather; chemical says the weather attacks by reaction.","cn":"风化就是岩石被丢在天气里；chemical 说明这场天气是以化学反应方式进攻的。"},{"en":"Four branches: dissolve, oxidise, hydrolyse, carbonate.","cn":"四条分支：溶解、氧化、水解、碳酸化。"},{"en":"Weathering breaks, erosion carries: the pair is a standard exam contrast.","cn":"风化弄碎，侵蚀搬走：这对术语是考试里的标准对照。"},{"en":"Limestone grooves and caves are the signature of carbonation.","cn":"石灰岩上的沟纹与洞穴是碳酸化作用的标志。"},{"en":"Red sandstone bands are the signature of oxidation.","cn":"砂岩上的红色条带是氧化作用的标志。"}],"abstract":[{"en":"Picture rain as a weak acid that slowly writes on stone and never stops.","cn":"想象雨水是一支弱酸写的笔，在石头上慢慢写字，从不停止。"},{"en":"Picture a carved name on a tombstone that becomes unreadable without anyone touching it.","cn":"想象墓碑上刻的名字在无人触碰的情况下变得读不出来。"},{"en":"Picture an iron nail left in a cliff face until the rock around it turns the colour of rust.","cn":"想象一根铁钉留在崖壁里，直到周围的岩石变成锈色。"}]},"examples":[{"en":"Chemical weathering is fastest where rainfall is heavy and warm.","cn":"在降雨充沛而温暖的地区，化学风化最快。"},{"en":"The cave system was created by chemical weathering of limestone.","cn":"这个洞穴系统是石灰岩化学风化的产物。"},{"en":"Acid rain accelerates chemical weathering on city monuments.","cn":"酸雨加速了城市纪念碑上的化学风化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「化学 + 风吹雨淋」——石头被雨水和空气一点点化掉，就是化学风化","word":"chemical weathering"},"root":"chemical（希腊 khēmeia，经阿拉伯语 al-kīmiyā 与中世纪拉丁 alchimia）+ weathering（古英语 weder「天气」加 -ing）；字面「被天气化学反应掉」，指岩石在原地被化学反应分解。","sensesIntro":{"en":"Eight senses move from the general process to its four chemical branches, then to the biological accelerator, the damage done to buildings, and a figurative slow corrosion.","cn":"八个义项从总过程走到四条化学分支，再到生物加速、建筑石材受损，最后是一个缓慢侵蚀的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: rain-watered limestone turning crumbly and grooved.","cn":"核心意象：被雨水打湿的石灰岩变得疏松并布满沟纹。"},"chain":["ROCK ATTACKED","MINERALS DISSOLVE","IRON OXIDISES","SILICATES HYDROLOSE","CARBONATE DISSOLVES","STONE DECAYS"],"branches":[{"senses":"S1","en":"THE WHOLE: any reaction that alters rock in place belongs here.","cn":"整体：任何在原地改变岩石的反应都归入此类。"},{"senses":"S2 · S5","en":"DISSOLVING: plain water takes salt away, weak acid takes limestone away.","cn":"溶解：纯水带走盐，弱酸带走石灰岩。"},{"senses":"S3","en":"OXIDISING: iron plus oxygen leaves rust colours and a crumbled framework.","cn":"氧化：铁加氧留下锈色与松散的骨架。"},{"senses":"S4","en":"HYDROLYSING: water rebuilds feldspar as clay.","cn":"水解：水把长石重组成黏土。"},{"senses":"S6 · S7 · S8","en":"ACCELERATORS: roots and lichen speed it up, cities make it visible, and metaphor makes it a slow erosion of anything.","cn":"加速者：根系与地衣加快它，城市让它显形，比喻让它成为任何事物的缓慢侵蚀。"}]},"affixes":{"intro":{"en":"The phrase is readable in parts: chemical holds the chem- stem and -ical ending, weathering holds the weather root and -ing.","cn":"这个短语可按部分拆读：chemical 含 chem- 词干与 -ical 词尾，weathering 含 weather 词根与 -ing。"},"latinIntro":{"en":"Only the -ical ending of chemical is Latin; weather is an Old English word and the geological noun is an English formation. The Latin entry is therefore limited to the adjective ending.","cn":"只有 chemical 的 -ical 词尾来自拉丁语；weather 是古英语词，地质学名词是英语自身构成。因此拉丁词条仅限于形容词词尾。"},"items":[{"word":"weather","structure":"weather (Old English weder, weather and storm)","meaning":"the state of the air; to expose to it","meaningCN":"天气；使暴露于天气之中","example":"The statue weathered for a century before it cracked.","exampleCN":"那尊雕像在户外受了一百年的风吹雨打才开裂。"},{"word":"-ing","structure":"-ing (noun-forming suffix, process)","meaning":"the process of","meaningCN":"…的过程","example":"Weathering names the process rather than its result.","exampleCN":"weathering 命名的是过程，而不是结果。"},{"word":"weathered","structure":"weather + -ed (having undergone)","meaning":"worn by exposure to the air","meaningCN":"因暴露于空气而变旧的","example":"Weathered timber turns silver outdoors.","exampleCN":"风化的木材在户外会变银灰色。"},{"word":"chem-","structure":"chem- (Greek stem from khēmeia)","meaning":"chemistry","meaningCN":"化学","example":"The same stem appears in chemist and chemistry.","exampleCN":"同一词干出现在 chemist 与 chemistry 中。"},{"word":"-ical","structure":"-ical (Latin -alis, relating to)","meaning":"relating to","meaningCN":"与…有关的","example":"Chemical, physical and biological form a set.","exampleCN":"chemical、physical 与 biological 构成一组。"},{"word":"hydrolysis","structure":"hydro- (water) + -lysis (loosening)","meaning":"chemical splitting by water","meaningCN":"由水引起的化学分解","example":"Hydrolysis converts feldspar into clay.","exampleCN":"水解把长石转化成黏土。"},{"word":"oxidation","structure":"oxid- (oxygen) + -ation (process)","meaning":"combination with oxygen","meaningCN":"与氧结合的过程","example":"Oxidation stains the rock face red.","exampleCN":"氧化把岩面染成红色。"},{"word":"carbonation","structure":"carbon + -ation (process)","meaning":"attack by carbon dioxide or carbonic acid","meaningCN":"由二氧化碳或碳酸造成的侵蚀","example":"Carbonation hollows out limestone caves.","exampleCN":"碳酸化作用掏出石灰岩洞穴。"},{"word":"dissolution","structure":"dissolv- (dissolve) + -ion (process)","meaning":"the process of going into solution","meaningCN":"溶解进入溶液的过程","example":"Dissolution removes halite from the cliff.","exampleCN":"溶解作用把岩盐从崖体中带走。"}],"latinEntries":[{"word":"-alis","structure":"Latin adjectival suffix -alis (relating to)","meaning":"relating to","meaningCN":"与…有关的","example":"It supplies the -ical of chemical in this phrase.","exampleCN":"它提供该短语中 chemical 的 -ical。"}]}},{"word":"physical weathering","ipa_uk":"/ˈfɪzɪkl ˈweðərɪŋ/","ipa_us":"/ˈfɪzɪkl ˈweðərɪŋ/","definition_zh":"物理风化；岩石因机械力量破碎而成分不变的过程","definition_en":"the breakdown of rock by mechanical forces such as frost, salt growth, pressure release or abrasion","core_image":"高山岩缝里的一层冰把两侧岩壁顶开，清晨一块碎石落在雪面上","scene":"高山上裸露的岩缝在夜里灌进雪水，天亮时冰把两侧岩壁撑开，碎石滚了一地，向导说 Physical weathering splits this granite without changing what it is made of.","sceneCN":"这里 physical weathering 指「岩石被机械力量弄碎而成分不变的过程」，取第 1 个义项（总称）；句意为物理风化把这花岗岩劈裂，却不改变它的成分。图中可辨识物件：岩缝、冰楔、碎石、雪面。","pos":[{"tag":"n.","zh":"物理风化、机械风化（不可数，地质学用语）"}],"collocations":[{"phrase":"physical weathering of rock","zh":"岩石的物理风化"},{"phrase":"physical weathering processes","zh":"物理风化过程"},{"phrase":"freeze-thaw physical weathering","zh":"冻融物理风化"},{"phrase":"physical weathering and erosion","zh":"物理风化与侵蚀"},{"phrase":"dominated by physical weathering","zh":"以物理风化为主"},{"phrase":"physical weathering rates","zh":"物理风化速率"}],"forms":[{"label":"不可数名词","form":"physical weathering"},{"label":"相关动词","form":"weather"},{"label":"相关形容词","form":"weathered"},{"label":"对照术语（化学风化）","form":"chemical weathering"},{"label":"对照术语（生物风化）","form":"biological weathering"}],"derivatives":[{"word":"weather","pos":"v.","zh":"风化；使受自然力侵蚀"},{"word":"weathered","pos":"adj.","zh":"风化的；表面被自然力磨损的"},{"word":"weathering","pos":"n.","zh":"风化作用"},{"word":"physical","pos":"adj.","zh":"物理的；物质的、身体的"}],"senses":[{"no":"01","title":"Rock broken by force alone","titleCN":"物理风化（总称）","definition":"the set of processes that break rock into pieces without altering its mineral composition","definitionCN":"把岩石弄碎而不改变其矿物成分的一整套过程","example":"Physical weathering leaves the same minerals behind, only in smaller pieces.","exampleCN":"物理风化留下的还是同样的矿物，只是碎成了小块。","why":"Physical here means mechanical: the rock loses shape and coherence, not its chemical identity.","whyCN":"这里的 physical 指机械方式：岩石失去的是形状与整体性，而不是化学身份。"},{"no":"02","title":"Frost wedging","titleCN":"冻融作用、冰楔撑裂","definition":"water entering cracks, freezing, expanding and prising the rock apart, then repeating","definitionCN":"水进入裂缝后结冰膨胀，把岩石撑开，如此反复","example":"Frost wedging is the leading form of physical weathering in alpine valleys.","exampleCN":"冻融作用是高寒河谷里物理风化的主要形式。","why":"Water expands when it freezes, so a filled crack pushes outward with force far beyond what the rock can bear.","whyCN":"水结冰时体积膨胀，因此灌满的裂缝向外顶出的力量远超岩石的承受能力。"},{"no":"03","title":"Salt crystallisation","titleCN":"盐结晶撑裂","definition":"salts growing in pores as water evaporates, pushing the grain boundaries apart","definitionCN":"水分蒸发后盐在孔隙中结晶，把颗粒边界顶开","example":"Salt crystallisation flakes the sandstone of desert cliffs.","exampleCN":"盐结晶使沙漠崖壁的砂岩层层剥落。","why":"Growing crystals exert pressure against the pore walls, and repeated wetting and drying multiplies the damage.","whyCN":"生长的晶体对孔隙壁施加压力，反复的干湿交替又把这破坏成倍放大。"},{"no":"04","title":"Unloading and exfoliation","titleCN":"卸荷与页状剥离","definition":"rock expanding and sheeting off in slabs once the weight above it is removed","definitionCN":"上方压力被移除后，岩石膨胀并按板状层层剥离","example":"Unloading produced the curved sheets of granite on the dome.","exampleCN":"卸荷作用使花岗岩穹丘上出现弯曲的剥落板片。","why":"Deep rock is compressed; when erosion uncovers it, stored strain is released and the surface peels away.","whyCN":"深处的岩石原本受压，侵蚀把它暴露后，储存的应变释放出来，表层便成片剥落。"},{"no":"05","title":"Abrasion and impact","titleCN":"磨蚀与撞击","definition":"sand, gravel or ice grinding and hammering the rock surface away","definitionCN":"沙、砾石或冰对岩石表面的磨擦与撞击消耗","example":"Wind abrasion is physical weathering that polishes as well as cuts.","exampleCN":"风蚀磨蚀是一种既切割又打磨的物理风化。","why":"Moving sediment carries kinetic energy, so repeated collisions chip the rock grain by grain.","whyCN":"移动的泥沙携带动能，反复撞击便一粒一粒地把岩石削掉。"},{"no":"06","title":"Thermal expansion and contraction","titleCN":"热胀冷缩引起的崩解","definition":"repeated heating and cooling cracking the surface through differential expansion","definitionCN":"反复加热与冷却因膨胀差异而使表层开裂","example":"Thermal expansion splits dark stones in the desert faster than pale ones.","exampleCN":"在沙漠里，热胀冷缩使深色石头比浅色石头开裂得更快。","why":"Minerals expand at different rates, so a hot day and a cold night pull the grain boundaries apart.","whyCN":"不同矿物膨胀速率不同，因此白天高温与夜间低温把颗粒边界拉开。"},{"no":"07","title":"Mechanical work by living things","titleCN":"生物造成的机械破坏","definition":"roots prising joints open and animals digging or trampling rock and soil","definitionCN":"根系把节理撑开，动物挖掘或踩踏岩石与土壤","example":"Root wedging counts as physical weathering even though a plant provides the force.","exampleCN":"根劈作用虽由植物提供力量，仍算作物理风化。","why":"The category is defined by mechanism rather than by agent, so a root that acts like a wedge stays inside it.","whyCN":"分类依据是机制而非施力者，因此像楔子一样起作用的根仍属此类。"},{"no":"08","title":"Damage to building stone","titleCN":"建筑石材的机械劣化","definition":"frost, salt and thermal cycling breaking the surface of masonry and monuments","definitionCN":"冻融、盐析与温度循环破坏砌体与纪念碑的表面","example":"Physical weathering has crumbled the carved edge of the old fountain.","exampleCN":"物理风化已经把老喷泉的雕花边缘蚀成碎屑。","why":"Conservation borrowed the geological term because city stone meets the same forces in a shorter cycle.","whyCN":"文物保护借用了这个地质术语，因为城市石材在更短的周期里遭遇同样的力量。"}],"etymology":{"intro":{"en":"The phrase joins physical, from Greek physis nature through Latin physicalis, with weathering, the English noun built on Old English weder, weather.","cn":"这个短语把 physical 与 weathering 结合：前者出自希腊 physis「自然」，经拉丁 physicalis 传入；后者是英语名词，建立在古英语 weder「天气」之上。"},"items":[{"era":"GREEK PHYSIS","en":"Physis meant nature, the way things grow and behave, and the adjective physikos described what belongs to the natural order.","cn":"physis 意为自然、万物生长与运作的方式，形容词 physikos 描述属于自然秩序的事物。"},{"era":"LATIN PHYSICALIS","en":"Medieval Latin physicalis rendered the Greek adjective, and English physical arrived through French with the sense of the material world as opposed to the mind.","cn":"中世纪拉丁 physicalis 转写了这个希腊形容词，英语 physical 经法语传入，取得「物质世界、与精神相对」的含义。"},{"era":"OLD ENGLISH WEDER","en":"Weder meant weather and storm; the verb weather meant to leave something exposed to wind, rain and frost.","cn":"weder 意为天气与风暴；动词 weather 意为让某物暴露在风雨与霜冻之中。"},{"era":"THE GEOLOGICAL SPLIT","en":"Nineteenth-century geology divided weathering into a mechanical kind and a chemical kind, and physical was chosen for the mechanical one.","cn":"十九世纪的地质学把风化分为机械与化学两类，机械一类便选用了 physical 这个词。"},{"era":"TERM SPREAD","en":"Engineering and conservation adopted the phrase in the twentieth century for concrete, masonry and monuments, without changing its meaning.","cn":"二十世纪，工程与文物保护把这短语用于混凝土、砌体与纪念碑，词义并未改变。"}]},"similar":{"note":{"en":"Group one holds the sibling weathering terms; group two holds processes that are often mistaken for weathering itself.","cn":"第一组是并列的风化术语；第二组是常被误当成风化本身的过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chemical weathering","ipa":"/ˈkemɪkl ˈweðərɪŋ/","tag":"composition changes","definition":"Breakdown by reaction, so the minerals are altered or removed rather than merely broken.","definitionCN":"由反应造成的分解，矿物被改变或带走，而不只是被弄碎。"},{"word":"biological weathering","ipa":"/ˌbaɪəˈlɒdʒɪkl ˈweðərɪŋ/","tag":"agent-based name","definition":"Weathering where plants, animals or microbes supply the force or the acid; it can be physical or chemical underneath.","definitionCN":"由植物、动物或微生物提供力或酸的风化；底层机制可以是物理的或化学的。"},{"word":"weathering","ipa":"/ˈweðərɪŋ/","tag":"the umbrella term","definition":"The general decay of rock in place, of which the physical kind is one branch.","definitionCN":"岩石在原地衰变的统称，物理一类是其中一个分支。"},{"word":"physical","ipa":"/ˈfɪzɪkl/","tag":"adjective only","definition":"Relating to matter and force; on its own it says nothing about rock decay.","definitionCN":"与物质和力有关的；单独使用时不涉及岩石衰变。"}]},{"heading":"NEAR MEANING","entries":[{"word":"erosion","ipa":"/ɪˈrəʊʒn/","tag":"transport afterwards","definition":"The removal and carrying away of loosened material; weathering produces the material, erosion moves it.","definitionCN":"把松动的物质剥离并搬走；风化产生物质，侵蚀搬运物质。"},{"word":"disintegration","ipa":"/ˌdɪsɪntɪˈɡreɪʃn/","tag":"result, not process name","definition":"Falling apart into small pieces; it describes the outcome rather than the geological category.","definitionCN":"碎成小块；描述的是结果，而非地质学分类。"},{"word":"abrasion","ipa":"/əˈbreɪʒn/","tag":"one mechanism","definition":"Wearing away by friction from moving sediment, ice or wind; it is one mechanism inside physical weathering.","definitionCN":"被移动的泥沙、冰或风摩擦磨损；它是物理风化的机制之一。"},{"word":"weathering","ipa":"/ˈweðərɪŋ/","tag":"in-place decay","definition":"Decay where the rock stays put; if the debris is carried away the process has become erosion.","definitionCN":"岩石留在原地的衰变；一旦碎屑被搬走，该过程就变成侵蚀。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek nature word, real mechanisms and real textbook contrasts.","cn":"正常联想：真实的希腊「自然」词、真实机制与真实教科书对照。"},"normal":[{"en":"Physical means by force: the rock breaks, the minerals stay the same.","cn":"physical 指靠力气：石头碎了，矿物还是原来的矿物。"},{"en":"The classic list is frost, salt, unloading, abrasion and heat.","cn":"经典清单是冻融、盐析、卸荷、磨蚀与冷热。"},{"en":"Weathering stays in place, erosion carries away: keep the pair together.","cn":"风化留在原地，侵蚀负责搬运：把这对词一起记。"},{"en":"Root wedging shows that the mechanism, not the agent, decides the category.","cn":"根劈说明决定分类的是机制，而不是施力者。"},{"en":"Physical evidence is the same mineral in smaller pieces.","cn":"物理风化的证据就是同样的矿物变成了更小的块。"}],"abstract":[{"en":"Picture water in a crack turning to ice and pushing like a slow jack.","cn":"想象裂缝里的水结成冰，像一只缓慢的千斤顶往外顶。"},{"en":"Picture a cliff peeling like the layers of an onion once the weight above is gone.","cn":"想象上方的重量消失后，崖壁像洋葱一样一层层剥开。"},{"en":"Picture wind carrying sand that sands down a stone pillar over a century.","cn":"想象风带着沙，用一百年把一根石柱磨细。"}]},"examples":[{"en":"Physical weathering prepares the rock for chemical attack by exposing fresh surfaces.","cn":"物理风化通过暴露新鲜表面，为化学侵蚀做好准备。"},{"en":"In polar regions physical weathering dominates because water keeps freezing.","cn":"在极地，由于水反复结冰，物理风化占主导。"},{"en":"The study measured physical weathering on exposed granite blocks.","cn":"这项研究测量了裸露花岗岩块上的物理风化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「物理 + 风化」——冻、盐、胀、磨，全用蛮力把石头拆开，成分一点没变","word":"physical weathering"},"root":"physical（希腊 physis「自然」加 -ikos，经拉丁 physicalis 与法语）+ weathering（古英语 weder「天气」加 -ing）；「以机械力把岩石弄碎而成分不变」。","sensesIntro":{"en":"Eight senses run from the umbrella process to five concrete mechanisms, then to plants acting as wedges and finally to the same damage seen on buildings.","cn":"八个义项从总过程走到五种具体机制，再到植物充当楔子，最后落到建筑上看到的同一类破坏。"},"semanticMap":{"core":{"en":"CORE IMAGE: ice in a crack pushing a block loose.","cn":"核心意象：裂缝里的冰把石块顶松。"},"chain":["MECHANICAL BREAKDOWN","FROST WEDGING","SALT GROWTH","UNLOADING","ABRASION","BUILDING DECAY"],"branches":[{"senses":"S1","en":"THE CATEGORY: force does the work and chemistry stays unchanged.","cn":"类别：由力量做功，化学性质不变。"},{"senses":"S2 · S3","en":"GROWING THINGS IN PORES: ice and salt both push outward from inside.","cn":"孔隙里的生长物：冰与盐都从内部向外顶。"},{"senses":"S4","en":"RELEASED PRESSURE: rock expands and sheets off once the load is gone.","cn":"释放的压力：荷载消失后岩石膨胀并成片剥落。"},{"senses":"S5 · S6","en":"MOVEMENT AND HEAT: grinding by sediment and cracking by daily temperature swings.","cn":"运动与热：泥沙的磨擦与日夜温差造成的开裂。"},{"senses":"S7 · S8","en":"OTHER AGENTS: roots act as wedges, and city stone suffers the same fate faster.","cn":"其他施力者：根充当楔子，城市石材更快遭遇同样的命运。"}]},"affixes":{"intro":{"en":"Physical weathering is readable as phys- plus -ical for the first word, and weather plus -ing for the second.","cn":"physical weathering 可拆读：前一词为 phys- 加 -ical，后一词为 weather 加 -ing。"},"latinIntro":{"en":"The phys- stem is Greek, mediated by Latin physicalis; weather is native English. The Latin entries below record the mediating forms rather than an inherited Latin compound.","cn":"phys- 词干来自希腊语，经拉丁 physicalis 中介；weather 是英语本族词。下面的拉丁词条记录的是中介形式，而不是拉丁语祖传复合词。"},"items":[{"word":"phys-","structure":"phys- (Greek physis, nature)","meaning":"nature; the natural order","meaningCN":"自然；自然秩序","example":"The stem appears in physics, physical and physician.","exampleCN":"该词干出现在 physics、physical 与 physician 中。"},{"word":"-ical","structure":"-ical (Latin -alis, relating to)","meaning":"relating to","meaningCN":"与…有关的","example":"Physical and chemical are a standard pair.","exampleCN":"physical 与 chemical 是标准的一对。"},{"word":"physics","structure":"phys- + -ics (subject of study)","meaning":"the science of matter and energy","meaningCN":"研究物质与能量的学科","example":"Physics explains why ice expands when it freezes.","exampleCN":"物理学解释了冰结冰时为何膨胀。"},{"word":"physically","structure":"physical + -ly (in a manner)","meaning":"by material force","meaningCN":"以物质力量方式","example":"The rock was physically broken, not dissolved.","exampleCN":"这块岩石是被物理弄碎的，而不是被溶解的。"},{"word":"weather","structure":"weather (Old English weder, weather)","meaning":"the state of the air; to expose to it","meaningCN":"天气；使暴露在天气中","example":"The stone weathered until its corners rounded.","exampleCN":"那块石头一直被风化，直到棱角变圆。"},{"word":"-ing","structure":"-ing (process noun suffix)","meaning":"the process of","meaningCN":"…的过程","example":"Weathering names the process, not the rubble.","exampleCN":"weathering 命名的是过程，而不是碎屑。"},{"word":"weathered","structure":"weather + -ed (having undergone)","meaning":"worn by exposure","meaningCN":"因暴露而磨损的","example":"Weathered granite feels rough under the hand.","exampleCN":"风化的花岗岩摸上去很粗糙。"},{"word":"freeze-thaw","structure":"freeze + thaw (compound label)","meaning":"the alternation of freezing and melting","meaningCN":"冻结与融化的交替","example":"Freeze-thaw cycles drive frost wedging.","exampleCN":"冻融循环驱动冰楔作用。"}],"latinEntries":[{"word":"physicalis","structure":"Medieval Latin physicalis, from Greek physikos + Latin -alis","meaning":"natural, relating to nature","meaningCN":"自然的、与自然有关的","example":"Medieval Latin physicalis is the adjective behind English physical.","exampleCN":"中世纪拉丁语 physicalis 是英语 physical 背后的形容词。"}]}},{"word":"biological weathering","ipa_uk":"/ˌbaɪəˈlɒdʒɪkl ˈweðərɪŋ/","ipa_us":"/ˌbaɪəˈlɑːdʒɪkl ˈweðərɪŋ/","definition_zh":"生物风化；岩石因生物活动而破碎或分解的过程","definition_en":"the breakdown of rock caused by living organisms, whether by mechanical force or by the acids they release","core_image":"地衣在裸岩表面摊开一层灰绿色的壳，根须顺着细缝往下钻，缝边的岩石已经发酥","scene":"裸岩表面铺着一层灰绿色的地衣，细缝里伸进几缕根须，缝口的岩屑一碰就落，老师说 Biological weathering starts on bare rock long before any soil can form.","sceneCN":"这里 biological weathering 指「岩石因生物活动而破碎或分解的过程」，取第 1 个义项（总称）；句意为生物风化在土壤形成之前很久就在裸岩上开始了。图中可辨识物件：地衣、根须、岩缝、岩屑。","pos":[{"tag":"n.","zh":"生物风化（不可数，地质学与地理学用语）"}],"collocations":[{"phrase":"biological weathering of rock","zh":"岩石的生物风化"},{"phrase":"biological weathering processes","zh":"生物风化过程"},{"phrase":"biological weathering by lichen","zh":"地衣造成的生物风化"},{"phrase":"biological weathering and soil formation","zh":"生物风化与土壤形成"},{"phrase":"root-driven biological weathering","zh":"根系驱动的生物风化"}],"forms":[{"label":"不可数名词","form":"biological weathering"},{"label":"相关形容词","form":"biological"},{"label":"相关名词（生物学）","form":"biology"},{"label":"相关动词","form":"weather"},{"label":"对照术语（物理风化）","form":"physical weathering"}],"derivatives":[{"word":"biology","pos":"n.","zh":"生物学；生命现象"},{"word":"biological","pos":"adj.","zh":"生物的；与生命有关的"},{"word":"biologically","pos":"adv.","zh":"从生物学角度；在生物意义上"},{"word":"weathering","pos":"n.","zh":"风化作用"}],"senses":[{"no":"01","title":"Life breaking down rock","titleCN":"生物风化（总称）","definition":"any weathering in which a living organism provides the force, the acid or both","definitionCN":"由生物提供力量、酸或两者兼有的任何风化过程","example":"Biological weathering is the first step in turning bare lava into living soil.","exampleCN":"生物风化是把裸露熔岩变成有生命的土壤的第一步。","why":"The label names the agent, not the mechanism, which is why the same process can sit between physical and chemical weathering.","whyCN":"这个标签命名的是施力者而非机制，因此同一过程可以夹在物理风化与化学风化之间。"},{"no":"02","title":"Roots prising joints open","titleCN":"根系撑裂","definition":"roots growing into cracks and widening them as they thicken","definitionCN":"根系长进裂缝，随着变粗而把裂缝撑大","example":"Root wedging is biological weathering with a purely mechanical effect.","exampleCN":"根劈作用是一种效果纯属机械的生物风化。","why":"A root exerts pressure like a wedge, so the rock breaks without any change in its minerals.","whyCN":"根像楔子一样施加压力，因此岩石被撑破而矿物并不改变。"},{"no":"03","title":"Lichen and moss acids","titleCN":"地衣与苔藓的酸蚀","definition":"organic acids from lichens and mosses dissolving minerals at the rock surface","definitionCN":"地衣与苔藓分泌的有机酸溶解岩石表层的矿物","example":"Lichen acids are biological weathering that also happens to be chemical.","exampleCN":"地衣酸造成的生物风化，同时也属于化学风化。","why":"The organism supplies the acid, so the category follows the agent while the mechanism is dissolution.","whyCN":"酸由生物提供，因此分类跟随施力者，而机制其实是溶解。"},{"no":"04","title":"Animals mixing and digging","titleCN":"动物翻动与挖掘","definition":"burrowing, trampling and wallowing that expose fresh rock and disturb the soil","definitionCN":"穴居、踩踏与打滚使新鲜岩石暴露并扰动土壤","example":"Burrowing animals speed up biological weathering by opening the ground.","exampleCN":"穴居动物通过把地面翻开，加快了生物风化。","why":"Digging does not dissolve anything, but it breaks the protective crust and lets water and air in.","whyCN":"挖掘本身并不溶解任何东西，但它破坏保护性结皮，让水和空气进入。"},{"no":"05","title":"Microbes and algae","titleCN":"微生物与藻类的作用","definition":"bacteria and algae that dissolve minerals, accumulate salts and hold water against the rock","definitionCN":"细菌与藻类溶解矿物、积累盐分并让水停留在岩石表面","example":"Microbes carry out biological weathering inside the pores of the stone.","exampleCN":"微生物在石材孔隙内部进行生物风化。","why":"Their waste products are acids and chelating compounds, so the smallest organisms can do the most persistent work.","whyCN":"它们的代谢产物是酸与螯合物，因此最小的生物反而能做最持久的功。"},{"no":"06","title":"Swelling and shrinking by plants","titleCN":"植物吸水与失水引起的胀缩","definition":"wet roots and stems swelling in pores, then contracting and loosening the surrounding rock","definitionCN":"湿润的根与茎在孔隙中膨胀，随后收缩并把周围岩石松脱","example":"Water uptake and loss add a slow biological weathering to the cliff.","exampleCN":"水的吸收与散失给崖壁添上一种缓慢的生物风化。","why":"Repeated swelling and shrinking works like a many-small wedges, each one widening what the last one loosened.","whyCN":"反复胀缩就像许多小楔子，每一个都把上一个弄松的地方再扩开一点。"},{"no":"07","title":"Damage to stone monuments","titleCN":"石质文物的生物劣化","definition":"the same organisms growing on carved stone and destroying its surface and inscriptions","definitionCN":"同一类生物长在雕琢过的石头上，破坏其表面与铭文","example":"Conservators treat biological weathering as a serious threat to the inscriptions.","exampleCN":"文物保护人员把生物风化视为对铭文的严重威胁。","why":"Because carved stone is a cultural record rather than a natural outcrop, the term moved into conservation with a sense of loss.","whyCN":"由于雕石是文化记录而非天然露头，这个词进入文物保护领域时便带上「损失」的意味。"},{"no":"08","title":"Boring and scraping by marine life","titleCN":"海洋生物钻孔与刮蚀","definition":"shellfish, worms and grazing animals that bore into or scrape away coastal rock","definitionCN":"贝类、蠕虫与食藻动物钻入或刮去海岸岩石","example":"Boring clams perform biological weathering along the whole shoreline.","exampleCN":"钻孔蛤沿着整条海岸线进行生物风化。","why":"On coasts the biological damage is measurable in cubic metres, so the term is used with the same confidence as for frost.","whyCN":"在海岸，生物造成的破坏可以用立方米计量，因此这个词用在潮间带时与用于霜冻时同样确定。"}],"etymology":{"intro":{"en":"Biological derives from Greek bios life plus logos study, through French biologie. Weathering is the native English noun from Old English weder. The compound label belongs to twentieth-century earth science.","cn":"biological 出自希腊 bios「生命」加 logos「研究」，经法语 biologie 传入。weathering 是英语本族名词，来自古英语 weder。这个复合标签属于二十世纪的地球科学。"},"items":[{"era":"GREEK BIOS","en":"Bios meant life and the span of a life, and it supplies the bio- element in biology, biography and biosphere.","cn":"bios 意为生命与一生的长度，是 biology、biography 与 biosphere 中 bio- 成分的来源。"},{"era":"GREEK LOGOS","en":"Logos meant word, account or reasoned study, and the ending -logy names a field of inquiry rather than a thing.","cn":"logos 意为语词、叙述或理性研究，词尾 -logy 命名的是一个研究领域，而不是某个实物。"},{"era":"FRENCH BIOLOGIE","en":"The compound biologie is recorded in French around the turn of the nineteenth century, and English biology followed soon after.","cn":"复合词 biologie 在十九世纪之交出现于法语书证，英语 biology 紧随其后。"},{"era":"LATIN -ALIS","en":"The adjective ending -ical comes from Latin -alis, so biological means relating to the study of life.","cn":"形容词词尾 -ical 来自拉丁 -alis，因此 biological 意为「与生命研究有关的」。"},{"era":"SOIL SCIENCE","en":"Twentieth-century soil science and conservation set biological weathering beside the physical and chemical kinds, naming the agent rather than the mechanism.","cn":"二十世纪的土壤学与文物保护把生物风化与物理、化学两类并列，命名的是施力者而非机制。"}]},"similar":{"note":{"en":"Group one holds the sibling weathering categories; group two holds biological processes that are not weathering.","cn":"第一组是并列的风化类别；第二组是并非风化的生物过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"physical weathering","ipa":"/ˈfɪzɪkl ˈweðərɪŋ/","tag":"mechanism name","definition":"Breakdown by force with the minerals unchanged; roots can cause it while the category stays physical.","definitionCN":"由力量造成的破碎、矿物不变；根系可造成它，而类别仍属物理风化。"},{"word":"chemical weathering","ipa":"/ˈkemɪkl ˈweðərɪŋ/","tag":"reaction name","definition":"Breakdown by reaction such as dissolution or oxidation; lichen acids cause it while the category stays chemical.","definitionCN":"由溶解、氧化一类反应造成的分解；地衣酸可造成它，而类别仍属化学风化。"},{"word":"bioerosion","ipa":"/ˌbaɪəʊɪˈrəʊʒn/","tag":"removal, not decay","definition":"The removal of coastal or submarine rock by boring and grazing organisms, including the transport of the debris.","definitionCN":"钻孔与刮食生物把海岸或海底岩石移除，并包括碎屑的搬运。"},{"word":"bioweathering","ipa":"/ˌbaɪəʊˈweðərɪŋ/","tag":"compressed synonym","definition":"A shorter form used in some journals for the same idea; the full phrase is standard in teaching.","definitionCN":"部分期刊使用的较短形式，含义相同；教学中仍以完整短语为标准。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pedogenesis","ipa":"/ˌpiːdəʊˈdʒenəsɪs/","tag":"soil formation","definition":"The formation of soil from rock and organic matter; it follows weathering but is a different process.","definitionCN":"由岩石与有机物形成土壤的过程；它发生在风化之后，但属于另一过程。"},{"word":"decomposition","ipa":"/ˌdiːkɒmpəˈzɪʃn/","tag":"organic decay","definition":"The breakdown of dead organic matter by microbes; it is not the breakdown of rock.","definitionCN":"微生物把死的有机物分解；对象并不是岩石。"},{"word":"chelation","ipa":"/kəˈleɪʃn/","tag":"one mechanism","definition":"The binding of metal ions by organic molecules, one way organisms pull minerals out of rock.","definitionCN":"有机分子结合金属离子，是生物把矿物从岩石中取出的方式之一。"},{"word":"root wedging","ipa":"/ruːt ˈwedʒɪŋ/","tag":"one mechanism","definition":"The specific widening of cracks by growing roots, the simplest example of this category.","definitionCN":"生长的根把裂缝撑宽的具体过程，是本类别中最简单的例子。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek life word, real organisms and real paired categories.","cn":"正常联想：真实的希腊「生命」词、真实生物与真实的成对类别。"},"normal":[{"en":"Bio means life and logos means study, so biological simply points to living agents.","cn":"bio 是生命，logos 是研究，因此 biological 只是指向有生命的施力者。"},{"en":"Two mechanisms sit inside one label: roots push, lichens dissolve.","cn":"一个标签里有两种机制：根在推，地衣在溶。"},{"en":"Lichen on bare lava is the textbook opening scene of soil formation.","cn":"裸熔岩上的地衣是教科书里土壤形成的第一幕。"},{"en":"Boring clams and grazing fish show the same word working on the coast.","cn":"钻孔蛤与刮食鱼类说明这个词在海岸同样适用。"},{"en":"The pair to remember is biological weathering versus bioerosion: decay in place against removal.","cn":"要记住的一对是生物风化与生物侵蚀：原地分解对搬运移除。"}],"abstract":[{"en":"Picture a lichen spreading like a slow grey stain that eats the stone under it.","cn":"想象地衣像一块慢慢扩大的灰斑，把下面的石头吃掉。"},{"en":"Picture a root feeling its way into a hairline crack and then thickening until the crack opens.","cn":"想象一条根摸索着钻进发丝般的裂缝，然后变粗直到裂缝张开。"},{"en":"Picture a shoreline where every hole in the rock was drilled by something alive.","cn":"想象一片海岸，岩石上每个孔都是活物钻出来的。"}]},"examples":[{"en":"Biological weathering by lichen is often the first sign that rock is breaking down.","cn":"地衣造成的生物风化往往是岩石开始分解的第一个迹象。"},{"en":"Tree roots cause biological weathering along the whole cliff edge.","cn":"树根沿着整条崖边造成生物风化。"},{"en":"The paper compares biological weathering with frost action at the same site.","cn":"这篇论文比较了同一地点上的生物风化与冻融作用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「生物 + 风化」——根在撑、地衣在蚀、动物在刨，全是活物在拆石头","word":"biological weathering"},"root":"biological（希腊 bios「生命」+ logos「研究」，经法语 biologie，加拉丁 -alis）+ weathering（古英语 weder「天气」加 -ing）；字面「由生命造成风化」。","sensesIntro":{"en":"Eight senses move from the umbrella label to roots, lichens, animals, microbes, plant swelling, carved stone, and finally the sea.","cn":"八个义项从总标签走到根系、地衣、动物、微生物、植物胀缩、雕石，最后到海洋。"},"semanticMap":{"core":{"en":"CORE IMAGE: lichen and roots working on bare rock.","cn":"核心意象：地衣与根须在裸岩上作业。"},"chain":["LIVING AGENT","ROOT PRESSURE","ORGANIC ACIDS","ANIMAL DISTURBANCE","MICROBES","COASTAL BORING"],"branches":[{"senses":"S1","en":"THE LABEL: it names who acts, so the mechanism may be either force or reaction.","cn":"标签：它命名谁在施力，因此机制可以是力，也可以是反应。"},{"senses":"S2 · S6","en":"PRESSURE: roots push and swell, both acting like small wedges.","cn":"压力：根会推也会胀，都像小楔子。"},{"senses":"S3 · S5","en":"ACIDS: lichens and microbes dissolve minerals with what they release.","cn":"酸：地衣与微生物用分泌物溶解矿物。"},{"senses":"S4","en":"DIGGING: animals break the crust and let water and air in.","cn":"挖掘：动物破坏结皮，让水与空气进入。"},{"senses":"S7 · S8","en":"TWO SETTINGS: carved monuments lose their inscriptions, and coasts lose their rock.","cn":"两个场景：雕石失去铭文，海岸失去岩石。"}]},"affixes":{"intro":{"en":"Biological weathering is built from bio- plus -logical, then weathering from weather plus -ing.","cn":"biological weathering 由 bio- 加 -logical 构成前一词，再由 weather 加 -ing 构成后一词。"},"latinIntro":{"en":"Both stems are Greek and the adjective ending is Latin -alis; Latin has no inherited form of the compound itself, so the entries below record only the ending and the Greek pieces.","cn":"两个词干都来自希腊语，形容词词尾为拉丁 -alis；拉丁语没有这个复合词本身的祖传形式，因此下面的词条只记录词尾与希腊构件。"},"items":[{"word":"bio-","structure":"bio- (Greek bios, life)","meaning":"life; living things","meaningCN":"生命；生物","example":"Biology and biosphere both begin with the same element.","exampleCN":"biology 与 biosphere 都以同一成分开头。"},{"word":"logos","structure":"logos (Greek, word or reasoned account)","meaning":"study; reasoned account","meaningCN":"研究；理性叙述","example":"The ending -logy in geology keeps this sense.","exampleCN":"geology 中的 -logy 保留了这一含义。"},{"word":"-logical","structure":"-logical (from -logia plus -alis)","meaning":"relating to a field of study","meaningCN":"与某一研究领域有关的","example":"Biological and geological share the same ending.","exampleCN":"biological 与 geological 共用同一词尾。"},{"word":"biology","structure":"bio- + -logy (study of)","meaning":"the science of living things","meaningCN":"研究生物的学科","example":"Biology explains how lichens colonise bare rock.","exampleCN":"生物学解释了地衣如何占据裸岩。"},{"word":"biological","structure":"biology + -ical (relating to)","meaning":"relating to life or living things","meaningCN":"与生命或生物有关的","example":"Biological agents break rock in several ways.","exampleCN":"生物媒介以多种方式破坏岩石。"},{"word":"biologically","structure":"biological + -ly (in a manner)","meaning":"from a biological point of view","meaningCN":"从生物学角度","example":"The crust is biologically active even in winter.","exampleCN":"这层结皮即使在冬天也有生物活动。"},{"word":"weather","structure":"weather (Old English weder)","meaning":"to expose to the elements","meaningCN":"使暴露于自然力","example":"The outcrop weathered slowly under the moss.","exampleCN":"苔藓之下的露头缓慢风化。"},{"word":"-ing","structure":"-ing (process noun suffix)","meaning":"the process of","meaningCN":"…的过程","example":"Weathering is the process, not the broken stone.","exampleCN":"weathering 是过程，而不是碎掉的石头。"},{"word":"bioerosion","structure":"bio- + erosion (compound)","meaning":"removal of rock by organisms","meaningCN":"生物造成的岩石移除","example":"Bioerosion differs from weathering because the debris is carried off.","exampleCN":"生物侵蚀与风化的区别在于碎屑被搬走。"}],"latinEntries":[{"word":"-alis","structure":"Latin adjectival suffix -alis, through French -al","meaning":"relating to","meaningCN":"与…有关的","example":"The -ical of biological rests on this Latin ending.","exampleCN":"biological 的 -ical 建立在这个拉丁词尾上。"}]}},{"word":"soil","ipa_uk":"/sɔɪl/","ipa_us":"/sɔɪl/","definition_zh":"土壤；土地、国土；弄脏；玷污","definition_en":"the loose upper layer of the earth in which plants grow; also to make something dirty","core_image":"田埂边一把土从指缝间漏下，掌心里留下几粒未碎的土块","scene":"田埂边上，农人蹲下抓了一把土在掌心里搓开，让土粒从指缝漏下去，说 This soil holds enough clay to keep water through a dry week.","sceneCN":"这里 soil 指「地表能长植物的疏松土层」，取第 1 个义项（土壤本身）；句意为这土含黏土足够多，能在干旱的一周里保住水分。图中可辨识物件：土块、指缝、田埂、草根。","pos":[{"tag":"n.","zh":"土壤；地表土层（多作不可数，指类型时可加限定词）"},{"tag":"n.","zh":"土地、国土（书面，如 on foreign soil）"},{"tag":"v.","zh":"弄脏（衣物、地面）；玷污（名誉）"}],"collocations":[{"phrase":"fertile soil","zh":"肥沃的土壤"},{"phrase":"soil erosion","zh":"土壤侵蚀"},{"phrase":"soil moisture","zh":"土壤水分"},{"phrase":"on foreign soil","zh":"在异国土地上"},{"phrase":"poor soil","zh":"贫瘠的土壤"},{"phrase":"soil formation","zh":"土壤形成"}],"forms":[{"label":"不可数名词","form":"soil"},{"label":"复数（指土类）","form":"soils"},{"label":"第三人称单数（动词）","form":"soils"},{"label":"过去式","form":"soiled"},{"label":"过去分词","form":"soiled"},{"label":"现在分词","form":"soiling"}],"derivatives":[{"word":"soiled","pos":"adj.","zh":"弄脏的；沾污的"},{"word":"soiling","pos":"n.","zh":"沾污；积尘造成的脏污"},{"word":"topsoil","pos":"n.","zh":"表土"},{"word":"subsoil","pos":"n.","zh":"底土、心土"}],"senses":[{"no":"01","title":"The layer plants grow in","titleCN":"土壤","definition":"the loose surface material of the earth, made of minerals, organic matter, water and air, in which roots grow","definitionCN":"地表由矿物、有机物、水和空气组成的疏松物质，根系在其中生长","example":"The soil in the valley is deep enough to grow wheat.","exampleCN":"谷地里的土壤深厚得足以种小麦。","why":"The word came from a French term for a piece of ground, so the earth itself rather than any one ingredient is named.","whyCN":"这个词来自法语表示「一块地」的说法，因此命名的是土地本身，而不是其中某一种成分。"},{"no":"02","title":"Land or territory","titleCN":"土地、国土","definition":"a country or region thought of as ground, especially in phrases about being born or buried there","definitionCN":"把国家或地区视为一片土地，尤用于出生或安葬之地的说法","example":"The regiment had not set foot on home soil for three years.","exampleCN":"这支部队已经三年没有踏上本国土地。","why":"Because ground stands for the nation, the word carries emotional weight in patriotic and legal writing.","whyCN":"由于地面被用来代指国家，这个词在爱国与法律文本中带有情感分量。"},{"no":"03","title":"Farming and the land","titleCN":"耕地；务农","definition":"the ground worked by farmers, and by extension farming as a way of life","definitionCN":"农民所耕作的土地，并引申指务农这一生活方式","example":"Three generations of the family have worked this soil.","exampleCN":"这家人已有三代在这片土地上耕作。","why":"The phrase work the soil treats the ground as material to be laboured, so the word enters idioms about livelihood.","whyCN":"work the soil 把土地当作可施加劳力的材料，因此这个词进入了关于生计的习语。"},{"no":"04","title":"Dirt or filth","titleCN":"污秽、脏东西（书面）","definition":"unclean matter on a surface or on the body, an older and more literary use","definitionCN":"附着在表面或身体上的不洁之物，属较古老、偏书面的用法","example":"The soil of the road clung to their boots.","exampleCN":"路上的污泥粘在他们的靴子上。","why":"This sense belongs to a separate verb source meaning to wallow or muddy, which later merged in spelling with the earth noun.","whyCN":"这一义项出自另一个表示「在泥里打滚、弄脏」的动词来源，后来在拼写上并入了表示土地的名词。"},{"no":"05","title":"To make dirty","titleCN":"弄脏（衣物、地面）","definition":"to mark clothes, floors or hands with dirt","definitionCN":"把泥土或污物弄到衣物、地板或手上","example":"He soiled his shirt while fixing the pump.","exampleCN":"他修水泵时把衬衫弄脏了。","why":"The verb is transitive and concrete: something clean is made unclean by contact.","whyCN":"这个动词及物且具体：干净的东西因接触而变脏。"},{"no":"06","title":"To stain a reputation","titleCN":"玷污（名誉、名声）","definition":"to damage someone's good name by association with something shameful","definitionCN":"因与不光彩之事关联而损害某人的好名声","example":"One leaked memo soiled the minister's reputation for honesty.","exampleCN":"一份泄露的备忘录玷污了这位部长以诚实著称的名声。","why":"The metaphor treats reputation as a clean surface that can be marked, so the same verb works without any physical dirt.","whyCN":"这一比喻把名誉当作可被弄脏的干净表面，因此同一动词无需任何实际污物也能成立。"},{"no":"07","title":"A breeding ground figuratively","titleCN":"比喻：温床、滋生条件","definition":"conditions that allow something unwanted, such as rumour or crime, to grow","definitionCN":"让谣言或犯罪这类不受欢迎之事得以滋长的条件","example":"Neglect made the estate fertile soil for gossip.","exampleCN":"疏于管理让这片住宅区成了流言的温床。","why":"The metaphor keeps the agricultural image: something is planted in the ground and grows from it.","whyCN":"这一比喻保留了农业意象：某样东西被种进土里，并从土里长出来。"},{"no":"08","title":"Soil types and textures","titleCN":"土壤类型与质地","definition":"a named kind of ground, such as sandy, clay or loamy soil, classified by its particles","definitionCN":"按颗粒划分的土类，如砂土、黏土或壤土","example":"Sandy soil drains fast but dries out in summer.","exampleCN":"砂土排水快，但夏天容易干透。","why":"Once farmers and scientists needed to compare grounds, the uncountable noun became countable with a classifier.","whyCN":"当农民与学者需要比较不同地块时，这个不可数名词加上了分类词而变得可数。"}],"etymology":{"intro":{"en":"English has two soils. The noun for earth comes from Old French soil, a piece of land, from Latin solum, ground or sole. The verb meaning to dirty comes from Old French soillier, to wallow, whose own origin is disputed. The two merged in form but not in source.","cn":"英语里有两个 soil。表示土地的名词来自古法语 soil「一块地」，再上溯拉丁 solum「地面、脚底」。表示弄脏的动词来自古法语 soillier「在泥里打滚」，其自身来源有争议。两者形式合并，但来源不同。"},"items":[{"era":"LATIN SOLUM","en":"Solum meant ground, floor or the sole of a foot, and it survives in English sole and in the scientific term solum.","cn":"solum 意为地面、地板或脚底，在英语 sole 与科学术语 solum 中留存。"},{"era":"OLD FRENCH SOIL","en":"Old French soil named a piece of land or a plot, and English borrowed it for the ground itself.","cn":"古法语 soil 指一块地或一小片田，英语借来表示土地本身。"},{"era":"THE SECOND SOIL","en":"Source uncertain at a deeper level: the verb to soil came from soillier, to muddy or wallow, related to a noun for a pigsty; its earlier origin is unsettled and may involve a Germanic or Latin source.","cn":"来源不确定（更深一层）：表示弄脏的动词来自 soillier「弄脏、在泥中打滚」，与指猪圈的名词相关；其更早来源没有定论，可能涉及日耳曼语或拉丁语。"},{"era":"SPELLING MERGER","en":"The two words came to be spelled alike, so dictionaries now list them as senses of one entry although the histories differ.","cn":"两个词后来拼写相同，因此词典如今把它们列为同一词条下的不同义项，尽管历史来源不同。"},{"era":"SCIENTIFIC SOIL","en":"Nineteenth-century soil science fixed the meaning as the weathered surface layer, and the countable use for soil types followed.","cn":"十九世纪的土壤学把词义固定为风化表层，随后出现了按土类计数的用法。"}]},"similar":{"note":{"en":"Group one holds earthy words that are constantly confused with soil; group two holds verbs and nouns of contamination.","cn":"第一组是常与 soil 混淆的土相关词；第二组是表示污染的动词与名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dirt","ipa":"/dɜːt/","tag":"unclean matter","definition":"Any unclean substance, especially on a surface or body; it has no scientific sense of a plant-growing layer.","definitionCN":"任何不洁之物，尤指附在表面或身上的；没有「可供植物生长的土层」这一科学义。"},{"word":"earth","ipa":"/ɜːθ/","tag":"the planet or ground","definition":"The planet, or the material of the ground; soil is the specific upper layer that supports plants.","definitionCN":"指行星，或指地面的材料；soil 特指能供养植物的上部土层。"},{"word":"land","ipa":"/lænd/","tag":"area, not material","definition":"A measured area of ground owned or used; it is a surface unit, not the substance in it.","definitionCN":"被拥有或使用的一块地面；它是个面积单位，而不是其中的物质。"},{"word":"mud","ipa":"/mʌd/","tag":"wet, no structure","definition":"Wet, sticky earth with no soil structure; it is what soil becomes when it is saturated.","definitionCN":"湿而黏的土，没有土壤结构；它是土壤饱和后的样子。"}]},{"heading":"NEAR MEANING","entries":[{"word":"loam","ipa":"/ləʊm/","tag":"a soil type","definition":"A balanced mixture of sand, silt and clay, the best soil for most crops.","definitionCN":"砂、粉砂与黏土的均衡混合，是多数作物最好的土壤。"},{"word":"humus","ipa":"/ˈhjuːməs/","tag":"one component","definition":"The dark decomposed organic matter inside soil; it is a part of soil, not soil itself.","definitionCN":"土壤中深色的腐解有机物；它是土壤的一部分，而不是土壤本身。"},{"word":"contaminate","ipa":"/kənˈtæmɪneɪt/","tag":"pollute, technical","definition":"To introduce a harmful substance; soil as a verb usually means visible dirt or moral stain.","definitionCN":"引入有害物质；动词 soil 通常指看得见的脏污或名誉污点。"},{"word":"stain","ipa":"/steɪn/","tag":"leave a mark","definition":"To leave a coloured mark that resists washing; soiling is broader and softer.","definitionCN":"留下洗不掉的有色痕迹；soiling 范围更宽、语气更轻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin solum, the real second source of the verb and real fixed phrases.","cn":"正常联想：真实的拉丁 solum、动词真实的第二个来源，以及真实搭配。"},"normal":[{"en":"Soil as ground comes from solum, the same root as sole.","cn":"表示土地的 soil 来自 solum，与 sole 同根。"},{"en":"Soil as dirt comes from a different French verb, so the two senses merely share a spelling.","cn":"表示脏污的 soil 来自另一个法语动词，因此两个义项只是共用拼写。"},{"en":"Fertile soil, poor soil and soil erosion are the phrases that keep the noun alive.","cn":"fertile soil、poor soil 与 soil erosion 是让这个名词保持活力的搭配。"},{"en":"On foreign soil turns ground into a country.","cn":"on foreign soil 把地面变成了国家。"},{"en":"Sandy soil and clay soil show the countable use for types.","cn":"sandy soil 与 clay soil 展示了按土类计数的用法。"}],"abstract":[{"en":"Picture a handful of earth that holds water in its crumbs like a sponge.","cn":"想象一把土像海绵一样把水含在土粒之间。"},{"en":"Picture a white shirt marked by one dark fingerprint that will not come out.","cn":"想象一件白衬衫上留下一个洗不掉的深色指印。"},{"en":"Picture a rumour planted in neglect and growing like a weed in loose ground.","cn":"想象一个谣言被种进疏于管理的土壤里，像杂草一样长出来。"}]},"examples":[{"en":"Good soil holds water without staying wet for days.","cn":"好的土壤能保住水分，又不会连续几天湿透。"},{"en":"The soldiers were glad to be back on home soil.","cn":"士兵们为回到本国土地而高兴。"},{"en":"He soiled his gloves with oil and could not get them clean.","cn":"他的手套沾上了油，怎么也弄不干净。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「搜一搂」——蹲下去搜一把土、搂进掌心，soil 就是土壤；手上脏了也就 soil 了","word":"soil"},"root":"名词 soil 来自古法语 soil「一块地」，上溯拉丁 solum「地面、脚底」；动词 soil 另有来源，出自古法语 soillier「弄脏、在泥中打滚」，两者拼写合并而来源不同。","sensesIntro":{"en":"Eight senses move from the growing layer to territory, farming, visible dirt, two verbs of staining, a figurative breeding ground, and finally named soil types.","cn":"八个义项从能长植物的土层走到国土、务农、可见的脏污、两个「弄脏」的动词义、比喻的温床，最后到按类型命名的土壤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a handful of earth crumbling between the fingers.","cn":"核心意象：一把土在指缝间搓碎。"},"chain":["GROWING LAYER","TERRITORY","FARMING","FILTH","MORAL STAIN","SOIL TYPES"],"branches":[{"senses":"S1 · S8","en":"MATERIAL: the substance itself, and the named kinds it is sorted into.","cn":"材质：物质本身，以及据此分出的各种类型。"},{"senses":"S2 · S3","en":"PLACE: ground becomes a nation, then a livelihood worked by hand.","cn":"地方：地面变成国家，再变成用手劳作的生计。"},{"senses":"S4 · S5","en":"DIRT: one sense is the unclean matter, the other the act of putting it there.","cn":"脏污：一个义项是不洁之物，另一个是把脏物弄上去的动作。"},{"senses":"S6","en":"REPUTATION: the same mark is made on a name rather than on cloth.","cn":"名声：同样的痕迹被留在名字上，而不是布料上。"},{"senses":"S7","en":"METAPHOR: bad conditions become ground in which unwanted things grow.","cn":"比喻：不良环境成了长出不受欢迎之事的土壤。"}]},"affixes":{"intro":{"en":"Soil is a short borrowed stem, but it forms compounds with top, sub- and borne, and it takes the ordinary English inflections.","cn":"soil 是一个简短的借入词干，但能与 top、sub- 与 borne 构成复合词，并带有普通英语屈折变化。"},"latinIntro":{"en":"The noun traces back to Latin solum, so one genuine Latin entry exists for that sense; the dirtying verb has a separate and uncertain origin and supplies no Latin form.","cn":"这个名词上溯拉丁 solum，因此该义项确有一条拉丁词条；表示弄脏的动词来源独立且不确定，不提供拉丁形式。"},"items":[{"word":"solum","structure":"solum (Latin, ground or sole)","meaning":"ground; the base of something","meaningCN":"地面；某物的底部","example":"The scientific term solum names a soil profile in place.","exampleCN":"科学术语 solum 指原地的土壤剖面。"},{"word":"topsoil","structure":"top + soil (compound)","meaning":"the upper, fertile layer","meaningCN":"上部肥沃的表土层","example":"Topsoil was stripped before the foundations went in.","exampleCN":"打地基前先把表土剥离了。"},{"word":"subsoil","structure":"sub- (under) + soil","meaning":"the layer beneath the topsoil","meaningCN":"表土之下的土层","example":"Subsoil here is heavy clay with little air.","exampleCN":"这里的底土是缺少空气的重黏土。"},{"word":"soiled","structure":"soil + -ed (having been affected)","meaning":"made dirty","meaningCN":"被弄脏的","example":"Soiled linen was piled by the door.","exampleCN":"脏床单被堆在门边。"},{"word":"soiling","structure":"soil + -ing (process noun)","meaning":"the act or result of dirtying","meaningCN":"弄脏的行为或结果","example":"Soiling of the facade comes mainly from traffic dust.","exampleCN":"立面的脏污主要来自交通扬尘。"},{"word":"soil-borne","structure":"soil + borne (carried by)","meaning":"carried in or by the soil","meaningCN":"由土壤携带的","example":"Soil-borne diseases survive in the field between crops.","exampleCN":"土传病害在两季作物之间存活于田间。"},{"word":"soil-less","structure":"soil + -less (without)","meaning":"not using soil","meaningCN":"不使用土壤的","example":"Soil-less culture feeds plants through water.","exampleCN":"无土栽培通过水供给植物养分。"},{"word":"soil-forming","structure":"soil + forming (compound adjective)","meaning":"producing soil","meaningCN":"形成土壤的","example":"Climate is the strongest soil-forming factor.","exampleCN":"气候是最强的成土因素。"}],"latinEntries":[{"word":"solum","structure":"Latin noun solum (ground, base)","meaning":"ground, floor, sole","meaningCN":"地面、地板、脚底","example":"Latin solum is the noun behind English soil and sole.","exampleCN":"拉丁语名词 solum 是英语 soil 与 sole 背后的词。"}]}},{"word":"soil profile","ipa_uk":"/sɔɪl ˈprəʊfaɪl/","ipa_us":"/sɔɪl ˈproʊfaɪl/","definition_zh":"土壤剖面；自地表向下到母质的垂直土层断面","definition_en":"a vertical section through soil showing the sequence of layers from the surface down to the parent material","core_image":"探坑壁上自上而下露出一条条深浅不同的土层，卷尺贴着坑壁垂直挂下","scene":"探坑挖开以后，壁上自上而下露出深褐、灰白与浅黄三段土层，学生把卷尺贴着坑壁量下去，说 Read this soil profile from the dark band downwards before you take a sample.","sceneCN":"这里 soil profile 指「自地表到母质的垂直土层断面」，取第 1 个义项（断面整体）；句意为取样之前要先从深色土层往下读这个剖面。图中可辨识物件：探坑壁、分层土色、卷尺、取样铲。","pos":[{"tag":"n.","zh":"土壤剖面（可数，复数 soil profiles）"}],"collocations":[{"phrase":"a typical soil profile","zh":"典型土壤剖面"},{"phrase":"describe a soil profile","zh":"描述土壤剖面"},{"phrase":"soil profile description","zh":"土壤剖面描述"},{"phrase":"expose a soil profile","zh":"露出土壤剖面"},{"phrase":"soil profile pit","zh":"土壤剖面坑"},{"phrase":"depth of the soil profile","zh":"土壤剖面深度"}],"forms":[{"label":"复数","form":"soil profiles"},{"label":"相关名词（土层）","form":"soil horizon"},{"label":"相关名词（剖面描述）","form":"profile description"},{"label":"相关名词（剖面）","form":"profile"},{"label":"相关术语（母质）","form":"parent material"}],"derivatives":[{"word":"profile","pos":"n./v.","zh":"剖面、侧影；作剖面记录"},{"word":"profiled","pos":"adj.","zh":"有剖面记录的；按剖面呈现的"},{"word":"profiling","pos":"n.","zh":"剖面测量；侧影描绘"},{"word":"horizon","pos":"n.","zh":"土层；地平线"}],"senses":[{"no":"01","title":"The vertical section as a whole","titleCN":"土壤剖面（整体断面）","definition":"the whole vertical cut from the surface down to unweathered material, seen as one object of study","definitionCN":"从地表一直切到未风化物质、被当作一个研究对象来看的整体垂直切面","example":"The soil profile in the pit was almost two metres deep.","exampleCN":"坑里的土壤剖面差不多有两米深。","why":"Profile first meant an outline drawing seen from the side, so a soil profile is the soil seen in side view.","whyCN":"profile 原指从侧面看的外形图，因此土壤剖面就是从侧面看的土壤。"},{"no":"02","title":"The sequence of layers","titleCN":"剖面中的层次序列","definition":"the ordered list of horizons, which is the information a profile is read for","definitionCN":"各土层的有序排列，也正是读剖面时所要获取的信息","example":"The soil profile at this site runs A, B, then C over granite.","exampleCN":"该地的土壤剖面依次为甲层、乙层，然后是覆盖在花岗岩上的丙层。","why":"Because layers form one above another in a fixed order, the profile is also the record of that order.","whyCN":"由于土层按固定次序上下叠置，剖面同时也是这一次序的记录。"},{"no":"03","title":"Field description and recording","titleCN":"野外剖面描述与记录","definition":"the standard written account of colours, textures, boundaries and depths seen in a pit","definitionCN":"对坑壁上所见颜色、质地、层界与深度所做的规范书面记录","example":"His soil profile description filled two pages of the field book.","exampleCN":"他的土壤剖面描述写满了野外记录本的两页。","why":"Soil survey depends on comparable records, so the term also names the document rather than the ground.","whyCN":"土壤调查依赖可比较的记录，因此这个词也指文件，而不只是土地。"},{"no":"04","title":"Sampling and monoliths","titleCN":"剖面采样与整段标本","definition":"the practice of taking samples by horizon or of lifting a whole face as a mounted specimen","definitionCN":"按层取样，或把整个剖面壁取下做成装框标本的做法","example":"They cut a soil profile into a box for the museum.","exampleCN":"他们把一段土壤剖面切进木箱，送进博物馆。","why":"Because a profile is a fixed arrangement, it can be lifted out whole, which is impossible for loose soil.","whyCN":"由于剖面是固定排列，它可以被整体取出，而松散的土则做不到。"},{"no":"05","title":"Degree of development","titleCN":"剖面的发育程度","definition":"how clearly horizons have differentiated, from a young profile to a mature one","definitionCN":"土层分化得有多明显，从幼年剖面到成熟剖面","example":"A young soil profile on fresh lava shows hardly any layering.","exampleCN":"新鲜熔岩上的幼年土壤剖面几乎看不出分层。","why":"Time and climate deepen the differences between layers, so the same word measures how far that process has gone.","whyCN":"时间与气候加深层间差异，因此同一个词也用来衡量这一过程走了多远。"},{"no":"06","title":"Classification evidence","titleCN":"土壤分类的依据","definition":"the set of horizons used to place a soil in a taxonomic class","definitionCN":"用来把某种土壤归入某一分类单元的那组土层","example":"The diagnostic horizons in this soil profile place it in the clay-rich order.","exampleCN":"这个土壤剖面里的诊断层把它归入富黏土的那一类。","why":"Classification systems are built on horizon sequences, so a described profile is the primary evidence for a soil name.","whyCN":"分类系统建立在土层序列之上，因此描述过的剖面是给土壤命名的首要证据。"},{"no":"07","title":"A section in a trench","titleCN":"探沟或考古坑中的剖面","definition":"the exposed face in an excavation, read for both soil and buried features","definitionCN":"发掘坑中露出的壁面，既读土壤也读埋藏遗迹","example":"The archaeologists drew the soil profile before digging deeper.","exampleCN":"考古队在下挖之前先把这个土壤剖面画了下来。","why":"Excavation borrows the term because a trench wall shows the same vertical sequence, sometimes with floors and pits cut into it.","whyCN":"考古发掘借用这个术语，因为探沟壁显示同样的垂直序列，只是其中还可能切进居住面与灰坑。"},{"no":"08","title":"A geotechnical section","titleCN":"工程勘察中的土层剖面","definition":"the layered section used by engineers to judge bearing capacity and drainage","definitionCN":"工程人员用来判断承载力与排水条件的分层断面","example":"The engineer read the soil profile to decide where to put the footings.","exampleCN":"工程师读了土层剖面，据此决定基础放在哪里。","why":"Building loads travel through layers, so the same section is read with different questions in mind.","whyCN":"建筑荷载要穿过各层，因此同一断面会被带着不同的问题去读。"}],"etymology":{"intro":{"en":"The phrase pairs soil, from Old French soil and Latin solum, with profile, from Italian profilo, an outline drawing, built on Latin filum, thread. The soil sense of profile dates from nineteenth-century soil survey.","cn":"这个短语把 soil 与 profile 结合：soil 出自古法语 soil 与拉丁 solum，profile 出自意大利语 profilo「外形轮廓图」，其基础是拉丁 filum「线」。profile 的土壤义形成于十九世纪的土壤调查。"},"items":[{"era":"ITALIAN PROFILO","en":"Profilo meant a drawing in outline, especially of a face or a building seen from the side.","cn":"profilo 指轮廓图，尤指从侧面看的人脸或建筑。"},{"era":"FILUM, THREAD","en":"The Italian verb profilare meant to draw a line, from filum, a thread, so the image is a single continuous line defining an edge.","cn":"意大利语动词 profilare 意为画线，来自 filum「线」，因此意象是一条连续线勾出边缘。"},{"era":"PRO- FORWARD","en":"The prefix pro- adds the idea of drawing the line forward along the edge, which is why the word implies a side view rather than a plan.","cn":"前缀 pro- 附加「沿边缘向前画」的意思，因此这个词暗含侧视而非俯视。"},{"era":"SOIL SURVEY","en":"Nineteenth and twentieth-century soil survey applied the word to the vertical face of a pit, since such a face is literally the soil seen in profile.","cn":"十九、二十世纪的土壤调查把这个词用于探坑的垂直壁面，因为这样的壁面正是从侧面看到的土壤。"},{"era":"LATIN SOLUM","en":"The soil half goes back to Latin solum, ground or sole, through Old French soil, a plot of land.","cn":"短语中的 soil 一半经古法语 soil「一块地」上溯拉丁 solum「地面、脚底」。"}]},"similar":{"note":{"en":"Group one holds terms from the same soil-description family; group two holds general section words that can be mistaken for a profile.","cn":"第一组是同属土壤描述体系的术语；第二组是容易被当成剖面的普通断面词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"soil horizon","ipa":"/sɔɪl ˈhɒrɪzn/","tag":"one layer inside it","definition":"A single layer within a profile, such as the topsoil or the clay-enriched subsoil.","definitionCN":"剖面中的单独一层，如表土或富黏土的底土层。"},{"word":"soil monolith","ipa":"/sɔɪl ˈmɒnəlɪθ/","tag":"a preserved specimen","definition":"A profile lifted intact and mounted for display or teaching.","definitionCN":"完整取下的剖面，装框用于展示或教学。"},{"word":"soil sample","ipa":"/sɔɪl ˈsæmpl/","tag":"a portion, not a face","definition":"A small quantity taken for laboratory analysis; it carries no layered structure.","definitionCN":"取来做实验室分析的小份材料；它不携带分层结构。"},{"word":"profile","ipa":"/ˈprəʊfaɪl/","tag":"the general word","definition":"Any side view or outline, from a face to a company summary; only with soil does it mean a layered section.","definitionCN":"任何侧视或轮廓，从人脸到公司简介；只有与 soil 连用才指分层断面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"section","ipa":"/ˈsekʃn/","tag":"cut surface, general","definition":"A surface exposed by cutting through something; it is neutral and needs no layering.","definitionCN":"切开某物后露出的面；中性词，不要求分层。"},{"word":"stratigraphy","ipa":"/strəˈtɪɡrəfi/","tag":"layer order as a science","definition":"The study of layered sequences, usually of rock or sediment rather than soil.","definitionCN":"研究分层序列的学问，对象通常是岩石或沉积物，而非土壤。"},{"word":"cross-section","ipa":"/ˌkrɒs ˈsekʃn/","tag":"cut at right angles","definition":"A cut across an object at right angles to its length; a soil profile is specifically a vertical face.","definitionCN":"与物体长度成直角切开的断面；土壤剖面特指垂直壁面。"},{"word":"pedon","ipa":"/ˈpiːdɒn/","tag":"the three-dimensional unit","definition":"A three-dimensional body of soil large enough to study, of which a profile is the visible face.","definitionCN":"足够大可供研究的三维土体，剖面只是它露出的那一面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Italian outline word, the real soil-survey usage and real companion terms.","cn":"正常联想：真实的意大利语「轮廓」词、真实的土壤调查用法与真实的配套术语。"},"normal":[{"en":"Profile means side view: a soil profile is the soil seen from the side.","cn":"profile 意为侧视：土壤剖面就是从侧面看到的土壤。"},{"en":"The profile is the whole face, each horizon is one band in it.","cn":"剖面是整个壁面，每个土层是里面的一条带。"},{"en":"A monolith is a profile lifted out; a sample is only a handful.","cn":"整段标本是被取出的剖面，样品只是一把土。"},{"en":"Field books record profiles with colour, texture, depth and boundary.","cn":"野外记录本用颜色、质地、深度与层界来记剖面。"},{"en":"Soil survey made the phrase standard in the nineteenth century.","cn":"土壤调查在十九世纪让这个短语成为标准术语。"}],"abstract":[{"en":"Picture a cake cut cleanly so that every layer shows at once.","cn":"想象一只蛋糕被切得整齐，所有层一次全露出来。"},{"en":"Picture a ruler laid against a wall of earth, counting downwards instead of upwards.","cn":"想象一把尺贴着土壁，不是往上量，而是往下数。"},{"en":"Picture a museum case holding a metre of ground like a painting.","cn":"想象博物馆的展柜里像挂画一样放着一米深的土地。"}]},"examples":[{"en":"The soil profile showed a thin dark surface over thick red clay.","cn":"这个土壤剖面显示，薄薄的深色表层下面是厚厚的红色黏土。"},{"en":"Every student had to draw the soil profile in the pit.","cn":"每个学生都要把坑里的土壤剖面画下来。"},{"en":"Drainage problems were obvious from the soil profile alone.","cn":"仅从土壤剖面就能看出排水问题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「土 + 侧面轮廓」——把土从侧面切开看，一层层像侧脸轮廓，就是土壤剖面","word":"soil profile"},"root":"soil（古法语 soil「一块地」，上溯拉丁 solum「地面」）+ profile（意大利语 profilo「轮廓图」，由 pro- 向前 + filum「线」构成）；字面「从侧面看到的土地轮廓」。","sensesIntro":{"en":"Eight senses follow the reading of one pit wall: the whole face, its layer order, the written record, the lifted specimen, its maturity, its taxonomic use, an excavation wall and an engineering section.","cn":"八个义项围绕一次读壁面的过程展开：整个壁面、层次次序、书面记录、取出的标本、发育程度、分类用途、发掘坑壁与工程断面。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pit wall showing bands of different colour.","cn":"核心意象：探坑壁上颜色不同的土带。"},"chain":["VERTICAL FACE","LAYER ORDER","FIELD RECORD","SPECIMEN","MATURITY","CLASSIFICATION"],"branches":[{"senses":"S1 · S2","en":"FACE AND ORDER: the visible cut and the sequence it displays.","cn":"壁面与次序：可见的切面，以及它所展示的排列。"},{"senses":"S3","en":"PAPER: the same information written down in a standard form.","cn":"纸面：同样的信息按规范形式写下来。"},{"senses":"S4","en":"OBJECT: a face can be lifted whole and kept as a specimen.","cn":"实物：壁面可以被整体取下并保存为标本。"},{"senses":"S5 · S6","en":"JUDGEMENT: how far layers have formed, and what class they place the soil in.","cn":"判断：分层形成了多少，以及据此把土壤归入哪一类。"},{"senses":"S7 · S8","en":"BORROWED SETTINGS: archaeologists and engineers read the same wall for other questions.","cn":"借用的场景：考古与工程人员读同一壁面，问的是别的问题。"}]},"affixes":{"intro":{"en":"Soil profile is built from two analyzable words: soil from Latin solum, and profile from pro- plus filum.","cn":"soil profile 由两个可分析的词构成：soil 来自拉丁 solum，profile 由 pro- 与 filum 构成。"},"latinIntro":{"en":"Both halves have genuine Latin ancestry: solum for the ground, and filum with the prefix pro- for the outline. The Latin entries below record those forms.","cn":"两半都有真实的拉丁语来源：表示地面的 solum，以及构成轮廓义的 filum 与前缀 pro-。下面的拉丁词条记录这些形式。"},"items":[{"word":"solum","structure":"solum (Latin, ground or sole)","meaning":"ground; base","meaningCN":"地面；底部","example":"Soil and sole both descend from solum.","exampleCN":"soil 与 sole 都源自 solum。"},{"word":"pro-","structure":"pro- (Latin prefix, forward)","meaning":"forward; in front","meaningCN":"向前；在前","example":"Profile draws its line forward along the edge.","exampleCN":"profile 把线沿边缘向前画出。"},{"word":"filum","structure":"filum (Latin, thread)","meaning":"thread; a thin line","meaningCN":"线；细线","example":"Filament and file both come from filum.","exampleCN":"filament 与 file 都出自 filum。"},{"word":"profile","structure":"pro- + filum (through Italian profilo)","meaning":"an outline seen from the side","meaningCN":"从侧面看到的外形轮廓","example":"The profile of the hill stood black against the sky.","exampleCN":"山丘的侧影在天幕下呈黑色。"},{"word":"profiled","structure":"profile + -ed (having been described)","meaning":"recorded in section","meaningCN":"以剖面形式记录的","example":"The profiled pit was filled in the next day.","exampleCN":"做过剖面记录的探坑第二天被回填了。"},{"word":"profiling","structure":"profile + -ing (process noun)","meaning":"the act of drawing or recording a section","meaningCN":"绘制或记录剖面的行为","example":"Profiling the wall took the whole morning.","exampleCN":"给壁面做剖面记录花了整个上午。"},{"word":"topsoil","structure":"top + soil","meaning":"the upper layer shown at the top of a profile","meaningCN":"剖面顶部的上部土层","example":"The topsoil band was only ten centimetres deep.","exampleCN":"表土层只有十厘米厚。"},{"word":"subsoil","structure":"sub- (under) + soil","meaning":"the lower layer in the profile","meaningCN":"剖面中较下的土层","example":"The subsoil band was dense and sticky.","exampleCN":"底土层紧实而黏。"},{"word":"horizon","structure":"horizon (Greek-derived layer term)","meaning":"a layer within the profile","meaningCN":"剖面中的一层","example":"Each horizon was marked with a pin.","exampleCN":"每一层都用一根针标出。"}],"latinEntries":[{"word":"solum","structure":"Latin noun solum (ground, base)","meaning":"ground, floor, sole","meaningCN":"地面、地板、脚底","example":"It is the source of the soil half of the phrase.","exampleCN":"它是该短语中 soil 一半的来源。"},{"word":"filum","structure":"Latin noun filum (thread)","meaning":"thread","meaningCN":"线","example":"Latin filum means thread and lies behind profile and filament.","exampleCN":"拉丁语 filum 意为线，是 profile 与 filament 的词源。"}]}},{"word":"soil horizon","ipa_uk":"/sɔɪl ˈhɒrɪzn/","ipa_us":"/sɔɪl həˈraɪzn/","definition_zh":"土壤发生层；土壤剖面中因成土作用而形成的一层","definition_en":"a layer within a soil profile, roughly parallel to the surface and distinguished by colour, texture or composition","core_image":"剖面上一条深褐色与浅黄色之间的清晰界线，铲尖正沿着这条线划过","scene":"剖面上深褐色的一条带在浅黄砂层处突然收住，界线十分清楚，老师说 The dark band marks the bottom of a soil horizon where clay has collected.","sceneCN":"这里 soil horizon 指「剖面中因成土作用形成的一层」，取第 1 个义项（发生层本身）；句意为这条深色带标出一个土壤层的底部，那里聚集了黏土。图中可辨识物件：层界、深色土带、浅黄砂层、取样铲。","pos":[{"tag":"n.","zh":"土壤发生层、土层（可数，复数 soil horizons）"}],"collocations":[{"phrase":"a distinct soil horizon","zh":"一个明显的土层"},{"phrase":"boundary between soil horizons","zh":"土层之间的界线"},{"phrase":"surface soil horizon","zh":"表层土壤发生层"},{"phrase":"diagnostic soil horizon","zh":"诊断土层"},{"phrase":"thickness of the soil horizon","zh":"土层厚度"},{"phrase":"soil horizon boundary","zh":"土层界线"}],"forms":[{"label":"复数","form":"soil horizons"},{"label":"相关名词（剖面）","form":"soil profile"},{"label":"相关形容词（水平的）","form":"horizontal"},{"label":"相关名词（界线）","form":"boundary"},{"label":"相关术语（母质层）","form":"parent material"}],"derivatives":[{"word":"horizon","pos":"n.","zh":"土层；地平线"},{"word":"horizontal","pos":"adj./n.","zh":"水平的；水平线"},{"word":"horizontally","pos":"adv.","zh":"水平地"},{"word":"horizonation","pos":"n.","zh":"土层分化；剖面中各发生层形成与分异的过程"}],"senses":[{"no":"01","title":"A layer formed by soil processes","titleCN":"土壤发生层（总称）","definition":"a layer in the profile whose features result from soil-forming processes rather than from the original rock","definitionCN":"剖面中其特征由成土过程而非原岩决定的一层","example":"Each soil horizon carries evidence of how water has moved through it.","exampleCN":"每个土壤层都带着水如何穿过的证据。","why":"Horizon in Greek meant a bounding circle, so a soil horizon is a band bounded off from the bands above and below.","whyCN":"horizon 在希腊语中意为「划界的圈」，因此土壤层就是与上下两层划开的一条带。"},{"no":"02","title":"The surface mineral layer","titleCN":"表土层（甲层）","definition":"the upper mineral layer darkened by organic matter and worked by roots and soil animals","definitionCN":"被有机物染深、受根系与土壤动物扰动的上部矿质层","example":"The surface soil horizon is where most roots and seeds are found.","exampleCN":"表土层是大多数根与种子所在之处。","why":"Because life is concentrated at the top, the uppermost mineral band is the first one named in any description.","whyCN":"由于生命集中在上部，最上的矿质带在任何描述中总是第一个被命名。"},{"no":"03","title":"The leached layer","titleCN":"淋溶层（漂白层）","definition":"a pale layer from which clay, iron and organic matter have been washed downward","definitionCN":"黏土、铁与有机物被向下淋洗后留下的浅色层","example":"The pale soil horizon below the surface is a sign of strong leaching.","exampleCN":"表层之下那条浅色土层是强烈淋溶的标志。","why":"Water moving down carries fine particles away, leaving the sand grains behind and the band bleached.","whyCN":"下渗的水带走了细颗粒，留下砂粒，于是这一带被漂白。"},{"no":"04","title":"The accumulation layer","titleCN":"淀积层（乙层）","definition":"a layer enriched in clay, iron or carbonate that arrived from above","definitionCN":"由上方迁入的黏土、铁或碳酸盐富集而成的层","example":"The red soil horizon owes its colour to iron deposited from above.","exampleCN":"那条红色土层的颜色来自从上面积淀下来的铁。","why":"Whatever the upper layers lose has to arrive somewhere, so the band below becomes the store.","whyCN":"上层失去的东西总要落到某处，因此下面那条带就成了仓库。"},{"no":"05","title":"The parent-material layer","titleCN":"母质层（丙层）","definition":"weathered rock or sediment that has been little altered by soil processes","definitionCN":"受成土过程影响很小的风化岩石或沉积物","example":"The lowest soil horizon still looks like the rock it came from.","exampleCN":"最下面的土层看起来还像它原来的岩石。","why":"This layer marks the boundary between soil and geology, which is why descriptions often stop there.","whyCN":"这一层标出土壤与地质的界线，因此描述常在此止步。"},{"no":"06","title":"The organic layer","titleCN":"有机层（枯落物层）","definition":"litter and partly decayed plant matter sitting above the mineral soil","definitionCN":"覆在矿质土壤之上的枯落物与部分腐解的植物残体","example":"A thick organic soil horizon keeps the ground cool and damp.","exampleCN":"厚厚一层有机土层让地面保持阴凉潮湿。","why":"Forest floors accumulate litter faster than it decays, so a separate organic band forms above the mineral layers.","whyCN":"林地枯落物堆积快于分解，因此在矿质层之上形成了一个独立的有机带。"},{"no":"07","title":"Transitional boundaries","titleCN":"过渡层与层界","definition":"a mixed band between two horizons, or the sharpness of the boundary itself","definitionCN":"两层之间的混合带，或界线本身的清晰程度","example":"The boundary between these soil horizons is abrupt rather than gradual.","exampleCN":"这些土层之间的界线是突变的，而不是渐变的。","why":"Layers rarely stop sharply, so surveyors describe both the mixed zone and the kind of boundary.","whyCN":"土层很少陡然终止，因此调查者既描述混合带，也描述界线的类型。"},{"no":"08","title":"A diagnostic horizon","titleCN":"诊断土层","definition":"a horizon whose specific features are used to assign the soil to a taxonomic class","definitionCN":"以其特定特征把该土壤归入某一分类单元的土层","example":"A clay-enriched soil horizon is diagnostic for the order it belongs to.","exampleCN":"富黏土的土层是该土所属纲的诊断依据。","why":"Classification needs features that can be checked in the field, and a named horizon supplies exactly that.","whyCN":"分类需要能在野外核对的特征，而一个有名字的土层正好提供这种特征。"}],"etymology":{"intro":{"en":"The phrase joins soil, from Latin solum through Old French, with horizon, from Greek horizōn, the bounding circle. Soil science took the word in the twentieth century for a layer marked off inside a profile.","cn":"这个短语把 soil 与 horizon 结合：soil 经古法语上溯拉丁 solum，horizon 出自希腊 horizōn「划界的圈」。土壤学在二十世纪把这个词用于剖面内部被划出的一层。"},"items":[{"era":"GREEK HOROS","en":"Horos meant a boundary or a marker stone, and the verb horizein meant to bound or separate.","cn":"horos 意为边界或界石，动词 horizein 意为划界、分开。"},{"era":"HORIZŌN KYKLOS","en":"The phrase horizōn kyklos, the bounding circle, named the line where earth and sky appear to meet, and the noun horizon was kept from it.","cn":"horizōn kyklos「划界的圈」指天地看似相接的那条线，名词 horizon 即由此截取而来。"},{"era":"ENGLISH HORIZON","en":"English horizon arrived through Latin and French with the geographical sense, and later gained figurative uses such as a horizon of possibilities.","cn":"英语 horizon 经拉丁与法语传入，先有地理义，后来又获得「可能性的视野」这类比喻用法。"},{"era":"LAYER SENSE","en":"Twentieth-century soil survey applied horizon to layers that are bounded above and below, matching the original sense of a bounding line.","cn":"二十世纪的土壤调查把 horizon 用于上下都有界线的土层，正与原义「划界的线」相合。"},{"era":"LATIN SOLUM","en":"The soil half of the phrase descends from Latin solum, ground or sole, by way of Old French.","cn":"短语中的 soil 一半经古法语上溯拉丁 solum「地面、脚底」。"}]},"similar":{"note":{"en":"Group one holds terms for layers and their arrangement; group two holds words sharing the horizon form but meaning something else.","cn":"第一组是表示土层及其排列的术语；第二组是共用 horizon 形式但含义不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"soil profile","ipa":"/sɔɪl ˈprəʊfaɪl/","tag":"the whole face","definition":"The complete vertical section, of which each horizon is one band.","definitionCN":"完整的垂直断面，每个土层只是其中一条带。"},{"word":"soil layer","ipa":"/sɔɪl ˈleɪə/","tag":"informal, general","definition":"A neutral word for any band of soil; horizon implies it was formed by soil processes and can be named.","definitionCN":"任何土带的中性说法；horizon 暗含它由成土过程形成、可以命名。"},{"word":"stratum","ipa":"/ˈstrɑːtəm/","tag":"rock or sediment","definition":"A layer of rock or sediment, usually geological rather than pedological.","definitionCN":"岩石或沉积物的一层，通常属地质学而非土壤学。"},{"word":"band","ipa":"/bænd/","tag":"visual only","definition":"A visible stripe of colour; it may cut across horizons rather than follow their boundaries.","definitionCN":"可见的色带；它可能横切土层，而不沿层界分布。"}]},{"heading":"NEAR MEANING","entries":[{"word":"horizon","ipa":"/həˈraɪzn/","tag":"the general noun","definition":"The line where sky meets land, or a limit of experience; the soil sense is a technical narrowing.","definitionCN":"天地相接的线，或经验的范围；土壤义是技术性的收窄。"},{"word":"topsoil","ipa":"/ˈtɒpsɔɪl/","tag":"a named layer","definition":"The uppermost fertile layer, one particular horizon in most profiles.","definitionCN":"最上部肥沃的一层，在多数剖面中是某一个特定土层。"},{"word":"subsoil","ipa":"/ˌsʌbˈsɔɪl/","tag":"a named layer","definition":"The layer beneath the topsoil, often corresponding to the accumulation horizon.","definitionCN":"表土之下的一层，常对应淀积层。"},{"word":"parent material","ipa":"/ˈpeərənt məˈtɪəriəl/","tag":"not a horizon","definition":"The rock or deposit from which the soil formed; it may sit below the lowest horizon or be the lowest one.","definitionCN":"形成土壤的岩石或沉积物；它可能位于最低土层之下，也可能就是最低那层。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek boundary word, the real letter names used in descriptions and real paired terms.","cn":"正常联想：真实的希腊「界线」词、描述中真实使用的字母代号，以及真实的成对术语。"},"normal":[{"en":"Horizon means a line that bounds: a horizon bounds the soil above from the soil below.","cn":"horizon 意为划界的线：一个土层把上面的土与下面的土分开。"},{"en":"Leached above, accumulated below: the pale and the red layers come as a pair.","cn":"上面淋走，下面淀积：浅色层与红色层成对出现。"},{"en":"Litter on top, parent material at the bottom: the profile has two fixed ends.","cn":"顶部是枯落物，底部是母质：剖面两端是固定的。"},{"en":"Boundaries are described as sharp, gradual or mixed.","cn":"层界被描述为突变、渐变或混合。"},{"en":"A diagnostic horizon is the one a classifier points to when naming the soil.","cn":"诊断层就是分类者给土壤命名时所指的那一层。"}],"abstract":[{"en":"Picture a stack of coloured papers where each sheet ends exactly where the next begins.","cn":"想象一叠彩色纸，每张纸结束的地方正是下一张开始的地方。"},{"en":"Picture a sieve that keeps the sand and lets the clay fall to the shelf below.","cn":"想象一只筛子留下砂，让黏土落到下面那一层。"},{"en":"Picture a line drawn on a wall so clean that nobody argues where one band ends.","cn":"想象在墙上划的一条线干净利落，没人争论一条带在哪里结束。"}]},"examples":[{"en":"The clay-enriched soil horizon was almost a metre thick.","cn":"这个富黏土的土层差不多有一米厚。"},{"en":"Colour alone is not enough to identify a soil horizon.","cn":"仅凭颜色不足以辨认一个土壤层。"},{"en":"Water stops at the boundary of the dense soil horizon.","cn":"水在那个紧实土层的界线上停住。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「土 + 地平线」——剖面里也有一条条像地平线的分界，跨过去就换了一层土","word":"soil horizon"},"root":"soil（古法语 soil，上溯拉丁 solum「地面」）+ horizon（希腊 horizōn「划界的圈」，源于 horos「边界」）；「剖面中被界线划出的一层土」。","sensesIntro":{"en":"Eight senses move down a profile: the general layer, the surface layer, the leached layer, the accumulation layer, the parent material, the organic layer on top, the boundary itself, and the diagnostic layer used in classification.","cn":"八个义项沿着剖面自上而下推进：总称的层、表层、淋溶层、淀积层、母质层、顶部的有机层、界线本身，以及分类所用的诊断层。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sharp line on a pit wall where dark soil ends and pale sand begins.","cn":"核心意象：坑壁上一条清晰的界线，深色土到此为止，浅黄砂从此开始。"},"chain":["BOUNDED LAYER","SURFACE LAYER","LEACHED LAYER","ACCUMULATION LAYER","PARENT MATERIAL","ORGANIC TOP"],"branches":[{"senses":"S1 · S7","en":"BOUNDARIES: a layer is defined by the lines above and below it, and by how sharp those lines are.","cn":"界线：一层由上下两条线界定，也由这两条线的清晰程度界定。"},{"senses":"S2","en":"LIFE AT THE TOP: roots and animals mix organic matter into the upper mineral band.","cn":"顶部的生命：根系与动物把有机物混进上部矿质带。"},{"senses":"S3 · S4","en":"MOVEMENT: one band loses clay and iron, the band beneath stores them.","cn":"迁移：一条带失去黏土与铁，下面那条把它们存起来。"},{"senses":"S5","en":"GEOLOGY: the lowest band is rock that soil processes have barely touched.","cn":"地质：最下面那条是成土过程几乎未触及的岩石。"},{"senses":"S6 · S8","en":"BOOKENDS: litter above, and the diagnostic layer that gives the soil its name.","cn":"两端：上方是枯落物，而诊断层则给这种土壤定名。"}]},"affixes":{"intro":{"en":"Soil horizon joins a Latin-derived noun with a Greek-derived one: soil from solum, horizon from horos plus the ending -izōn.","cn":"soil horizon 把拉丁来源的名词与希腊来源的名词结合：soil 出自 solum，horizon 出自 horos 加词尾 -izōn。"},"latinIntro":{"en":"Only the soil half has Latin ancestry; horizon is Greek and Latin borrowed it rather than inheriting it, so no genuine Latin entry exists for that half.","cn":"只有 soil 一半有拉丁语来源；horizon 是希腊语词，拉丁语是借用而非继承，因此该一半没有真正的拉丁词条。"},"items":[{"word":"solum","structure":"solum (Latin, ground or sole)","meaning":"ground; base","meaningCN":"地面；底部","example":"Soil descends from solum through French.","exampleCN":"soil 经法语上溯 solum。"},{"word":"horos","structure":"horos (Greek, boundary or marker stone)","meaning":"boundary; limit","meaningCN":"边界；界限","example":"The horizon element originally named a boundary.","exampleCN":"horizon 这一成分原指一条边界。"},{"word":"horizein","structure":"horizein (Greek verb, to bound)","meaning":"to bound; to separate","meaningCN":"划界；分开","example":"The verb supplies the participle behind horizon.","exampleCN":"这个动词提供了 horizon 背后的分词形式。"},{"word":"horizon","structure":"horizōn (Greek participle, bounding)","meaning":"a bounding line; a layer","meaningCN":"界线；一层","example":"The horizon between the bands was easy to follow.","exampleCN":"两条带之间的界线很容易跟着看。"},{"word":"horizontal","structure":"horizon + -al (relating to)","meaning":"parallel to the ground","meaningCN":"与地面平行的","example":"Soil horizons are roughly horizontal.","exampleCN":"土壤层大致是水平的。"},{"word":"horizontally","structure":"horizontal + -ly (in a manner)","meaning":"in a level direction","meaningCN":"以水平方向","example":"Water moved horizontally along the boundary.","exampleCN":"水沿界线水平移动。"},{"word":"topsoil","structure":"top + soil","meaning":"the surface horizon","meaningCN":"表层土壤","example":"Topsoil is the first horizon in the description.","exampleCN":"表土是描述中的第一个土层。"},{"word":"subsoil","structure":"sub- (under) + soil","meaning":"the horizon below the surface","meaningCN":"表层之下的土层","example":"The subsoil horizon held most of the clay.","exampleCN":"底土层含住了大部分黏土。"},{"word":"boundary","structure":"bound- (bound) + -ary (place or thing)","meaning":"the line where one layer ends","meaningCN":"一层结束处的那条线","example":"The boundary was sharp and easy to trace.","exampleCN":"那条界线清晰易辨。"}],"latinEntries":[{"word":"solum","structure":"Latin noun solum (ground, base)","meaning":"ground, floor, sole","meaningCN":"地面、地板、脚底","example":"The soil half of the term comes from this noun.","exampleCN":"该术语中 soil 一半来自这个名词。"}]}},{"word":"topsoil","ipa_uk":"/ˈtɒpsɔɪl/","ipa_us":"/ˈtɑːpsɔɪl/","definition_zh":"表土；土壤剖面最上部富含有机质的一层","definition_en":"the upper, darker and more fertile layer of soil, where roots and organic matter are concentrated","core_image":"苗床边一车深褐色松软的土被摊平，铁锹划过时留下湿润的土纹","scene":"花坛边上，园艺工把一车深褐色的松软土倒在苗床上，用铁锹摊平，说 A good topsoil holds moisture without turning to mud after rain.","sceneCN":"这里 topsoil 指「剖面最上部富含有机质的那层土」，取第 1 个义项（表土层本身）；句意为好的表土能保住水分，雨后又不会变成烂泥。图中可辨识物件：苗床、土堆、铁锹、土纹。","pos":[{"tag":"n.","zh":"表土（多作不可数，指具体土类时可用复数 topsoils）"}],"collocations":[{"phrase":"a layer of topsoil","zh":"一层表土"},{"phrase":"topsoil removal","zh":"表土剥离"},{"phrase":"topsoil loss","zh":"表土流失"},{"phrase":"imported topsoil","zh":"外购表土"},{"phrase":"strip the topsoil","zh":"剥离表土"},{"phrase":"topsoil depth","zh":"表土厚度"}],"forms":[{"label":"不可数名词","form":"topsoil"},{"label":"复数（指土类）","form":"topsoils"},{"label":"对照术语（底土）","form":"subsoil"},{"label":"相关名词（表土铺设）","form":"topdressing"},{"label":"相关动词（剥离表土）","form":"strip"}],"derivatives":[{"word":"topsoils","pos":"n.","zh":"各类表土（复数，用于土壤调查比较）"},{"word":"topdressing","pos":"n.","zh":"表层施肥；在表面铺一层土或肥料"},{"word":"subsoil","pos":"n.","zh":"底土、心土"},{"word":"soil","pos":"n./v.","zh":"土壤；弄脏"}],"senses":[{"no":"01","title":"The fertile surface layer","titleCN":"表土（总称）","definition":"the upper layer of soil, darker and richer in organic matter than what lies beneath","definitionCN":"土壤的上部层，比下面的土颜色更深、有机质更多","example":"Most of the field's fertility sits in the topsoil.","exampleCN":"这块田的肥力大部分集中在表土里。","why":"Top marks the upper position and soil names the material, so the compound simply says which layer is meant.","whyCN":"top 标出上部位置，soil 指明材料，因此这个复合词只是说明所指是哪一层。"},{"no":"02","title":"The plough layer","titleCN":"耕作层","definition":"the part of the topsoil that tillage mixes and crops are sown into","definitionCN":"被耕作搅动、作物播种其中的那部分表土","example":"Deep ploughing buries weed seeds below the plough layer of topsoil.","exampleCN":"深耕把杂草种子埋到耕作层下面。","why":"Farming measures the layer by the depth of the plough, so the word often means the worked slice rather than the whole surface.","whyCN":"农业以犁的深度来计量这一层，因此这个词常指被翻动的那一片，而不是整个表层。"},{"no":"03","title":"Bought soil for gardens","titleCN":"商品表土（园艺用）","definition":"bagged or delivered soil sold for beds, lawns and planters","definitionCN":"装袋或送货上门、用于花坛、草坪与种植箱的土壤","example":"The new border was filled with imported topsoil.","exampleCN":"新花境是用外购表土填起来的。","why":"Once gardens were built on subsoil or rubble, suppliers began selling the good upper layer as a product with its own name.","whyCN":"当花园建在底土或碎砖上时，供应商开始把优质的上层土当作商品出售，这个词也就成了商品名。"},{"no":"04","title":"Stripping before construction","titleCN":"施工前的表土剥离","definition":"the practice of removing and stockpiling the surface layer before building or mining","definitionCN":"在施工或采矿前把表层土取走并堆存的做法","example":"Topsoil stripping was required before the foundations were dug.","exampleCN":"开挖基础之前必须先剥离表土。","why":"Because the layer is slow to form, regulations require it to be saved and put back rather than buried.","whyCN":"由于这一层形成极慢，法规要求把它保存下来再回填，而不是直接埋掉。"},{"no":"05","title":"Loss through erosion","titleCN":"表土流失","definition":"the removal of the fertile layer by water or wind, leaving poorer ground behind","definitionCN":"肥沃表层被水或风带走，留下更贫瘠的地面","example":"Topsoil loss on the slope doubled after the hedges were cleared.","exampleCN":"树篱被清除后，坡地上的表土流失翻了一倍。","why":"The layer is the first thing moving water meets, so it is lost before anything deeper is touched.","whyCN":"这一层是流水最先碰到的东西，因此在更深处被动到之前它就已被带走。"},{"no":"06","title":"Where roots and seeds live","titleCN":"根系与种子最密集的一层","definition":"the zone holding most fine roots, soil animals and the seed bank","definitionCN":"容纳大部分细根、土壤动物与种子库的那一层","example":"Almost every fine root in the meadow was inside the topsoil.","exampleCN":"草甸里几乎每一条细根都在表土之内。","why":"Air, water and organic matter all peak near the surface, so life concentrates there by necessity.","whyCN":"空气、水与有机质都在近地表处最充足，因此生命必然集中在那里。"},{"no":"07","title":"Replacement in restoration","titleCN":"复垦中的表土回填","definition":"the return of stored surface soil after mining or construction so that vegetation can recover","definitionCN":"采矿或施工结束后把堆存的表土回填，使植被得以恢复","example":"Topsoil replacement gave the restored slope a chance to green again.","exampleCN":"表土回填让修复后的坡面有了重新变绿的机会。","why":"Stored soil keeps its seeds and microbes, which is why returning it is cheaper than rebuilding fertility.","whyCN":"堆存的土保有种子与微生物，因此回填比重新造肥力更省事。"},{"no":"08","title":"Disturbed urban surface soil","titleCN":"城市扰动表土","definition":"the mixed, compacted surface layer of cities, often part rubble and part imported soil","definitionCN":"城市里被混合、压实的表层，常一半是碎砖一半是外运来的土","example":"Urban topsoil often drains badly because it has been compacted for decades.","exampleCN":"城市表土常因被压实几十年而排水很差。","why":"City soils are made by digging and filling rather than by slow formation, so the word marks position rather than quality.","whyCN":"城市土壤由挖填而成，而非缓慢生成，因此这个词在这里标出的是位置而不是质量。"}],"etymology":{"intro":{"en":"Topsoil is an English compound of top, from Old English topp, a tuft or summit, and soil, from Old French soil and Latin solum. The agricultural compound is recorded from the nineteenth century.","cn":"topsoil 是英语复合词，由 top 与 soil 组成：top 来自古英语 topp「一簇、顶端」，soil 来自古法语 soil 与拉丁 solum。这个农业复合词在十九世纪已有书证。"},"items":[{"era":"OLD ENGLISH TOPP","en":"Topp meant a tuft of hair or the summit of something, and top kept the idea of the highest position.","cn":"topp 意为一撮毛发或某物的顶端，top 保留了「最高位置」的意思。"},{"era":"LATIN SOLUM","en":"Soil came through Old French from Latin solum, ground or sole, so the second half names the material rather than a place.","cn":"soil 经古法语来自拉丁 solum「地面、脚底」，因此后半部分命名的是材料而非地点。"},{"era":"AGRICULTURAL COMPOUND","en":"Nineteenth-century farming and soil survey needed to separate the fertile surface from the poorer layer beneath, and topsoil supplied that contrast with subsoil.","cn":"十九世纪的农业与土壤调查需要把肥沃表层与下面较贫瘠的层分开，topsoil 与 subsoil 正好提供这对区分。"},{"era":"ENGINEERING USE","en":"Twentieth-century construction and mining added stripping and replacement, treating the layer as a resource to be moved and stored.","cn":"二十世纪的施工与采矿增加了剥离与回填的用法，把这一层当作可搬运、可储存的资源。"},{"era":"SPELLING","en":"The compound is written as one word in technical use and is uncountable except when soil types are compared.","cn":"这个复合词在技术文献中写作一个词，除比较土类外通常不可数。"}]},"similar":{"note":{"en":"Group one holds the layer words that sit beside topsoil in any description; group two holds materials often sold or spread like topsoil.","cn":"第一组是任何描述中都会与表土并列的层位词；第二组是常被当作表土出售或铺撒的材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"subsoil","ipa":"/ˌsʌbˈsɔɪl/","tag":"the layer below","definition":"The layer beneath the topsoil, usually poorer in organic matter and richer in clay.","definitionCN":"表土之下的层，通常有机质更少、黏土更多。"},{"word":"soil","ipa":"/sɔɪl/","tag":"the whole material","definition":"The general word for the plant-growing layer; topsoil names only its upper part.","definitionCN":"指能生长植物的土层的统称；topsoil 只指它的上部。"},{"word":"top","ipa":"/tɒp/","tag":"position word","definition":"The highest part of anything; on its own it says nothing about soil.","definitionCN":"任何事物的最高部分；单独使用时与土壤无关。"},{"word":"overburden","ipa":"/ˌəʊvəˈbɜːdn/","tag":"mining term","definition":"Material lying above a coal seam or ore body; it includes topsoil but is defined by what lies beneath.","definitionCN":"压在煤层或矿体之上的材料；它包含表土，但以所覆盖之物来定义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"surface soil","ipa":"/ˈsɜːfɪs sɔɪl/","tag":"neutral synonym","definition":"A descriptive phrase for the uppermost soil, common in survey writing without the agricultural overtone.","definitionCN":"对最上部土壤的描述性说法，常见于土壤调查文献，不带农业色彩。"},{"word":"plough layer","ipa":"/ˈplaʊ leɪə/","tag":"worked slice","definition":"The depth actually turned by the plough, which may be thinner than the whole topsoil.","definitionCN":"犁实际翻到的深度，可能比整个表土层薄。"},{"word":"loam","ipa":"/ləʊm/","tag":"a texture, not a layer","definition":"A balanced mix of sand, silt and clay; a topsoil can be loam, but loam is not a position.","definitionCN":"砂、粉砂与黏土的均衡混合；表土可以是壤土，但壤土不是位置。"},{"word":"compost","ipa":"/ˈkɒmpɒst/","tag":"made organic material","definition":"Decomposed organic waste used as a soil amendment; it is added to topsoil rather than being it.","definitionCN":"腐解的有机废弃物，用作土壤改良剂；它是加进表土的东西，而不是表土本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Old English top word and the real topsoil-subsoil pair.","cn":"正常联想：真实的古英语 top 词与真实的表土—底土成对关系。"},"normal":[{"en":"Top plus soil: the soil at the top, which is exactly what the word says.","cn":"top 加 soil：最上面的那层土，词面说的就是这意思。"},{"en":"Topsoil and subsoil come as a pair, like roof and cellar.","cn":"表土与底土成对出现，就像屋顶与地窖。"},{"en":"Most roots, seeds and organic matter sit in the topsoil.","cn":"大部分根、种子与有机质都在表土里。"},{"en":"Construction language adds stripping and replacement of topsoil.","cn":"施工语境里还有表土剥离与表土回填的说法。"},{"en":"Topsoil loss is the first damage reported after land is cleared.","cn":"土地被清理后，最先报告的破坏就是表土流失。"}],"abstract":[{"en":"Picture a thin dark blanket over pale ground, and everything alive living inside that blanket.","cn":"想象浅色地面上盖着一条深色薄毯，所有活物都住在毯子里。"},{"en":"Picture a bulldozer pushing the good layer into a heap to keep it for later.","cn":"想象推土机把好土推成一堆，留着以后再用。"},{"en":"Picture rain carrying the dark blanket downhill and leaving stones behind.","cn":"想象雨水把那层深色毯子冲下山坡，只留下石头。"}]},"examples":[{"en":"The topsoil here is only a few centimetres deep.","cn":"这里的表土只有几厘米深。"},{"en":"Builders must strip and store the topsoil before grading the site.","cn":"施工方在平整场地前必须剥离并堆存表土。"},{"en":"Adding compost improved the topsoil within two seasons.","cn":"加入堆肥后，表土在两个季节内就改善了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「头顶那层土」——top 是顶，soil 是土，最上面那层肥沃的土就是表土","word":"topsoil"},"root":"top（古英语 topp「顶端、一簇」）+ soil（古法语 soil「一块地」，上溯拉丁 solum「地面」）；「位于最上部的土壤」。","sensesIntro":{"en":"Eight senses move from the layer itself to the worked slice, the bagged product, stripping, erosion, the root zone, restoration and the disturbed city surface.","cn":"八个义项从这一层本身走到被耕作的切片、袋装商品、剥离、侵蚀、根区、复垦，以及受扰动的城市表层。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dark crumbly layer spread over a pale bed.","cn":"核心意象：一层深色松软的土铺在浅色苗床上。"},"chain":["SURFACE LAYER","PLOUGH DEPTH","SOLD PRODUCT","STRIPPING","EROSION LOSS","ROOT ZONE"],"branches":[{"senses":"S1 · S2","en":"POSITION AND WORK: the layer at the top, and the slice a plough actually turns.","cn":"位置与作业：位于顶部的那层，以及犁实际翻到的那一片。"},{"senses":"S3","en":"COMMERCE: good surface soil becomes a bagged product for gardens.","cn":"买卖：优质表层土变成花园用的袋装商品。"},{"senses":"S4 · S7","en":"MOVING IT: stripped before building, put back after mining.","cn":"搬运：施工前剥离，采矿后回填。"},{"senses":"S5","en":"LOSING IT: water and wind take the layer first.","cn":"失去它：水与风最先带走这一层。"},{"senses":"S6 · S8","en":"LIFE AND CITY: the root zone, and the compacted urban version of the same layer.","cn":"生命与城市：根区，以及同一层在城市里被压实后的样子。"}]},"affixes":{"intro":{"en":"Topsoil joins two free morphemes, top and soil, and both halves also appear in other compounds.","cn":"topsoil 由 top 与 soil 两个自由语素组成，两半也出现在其他复合词中。"},"latinIntro":{"en":"Top is native English, while soil reaches Latin solum through French. The Latin entry below records only that second half.","cn":"top 是英语本族词，soil 则经法语上溯拉丁 solum。下面的拉丁词条只记录后半部分。"},"items":[{"word":"top","structure":"top (Old English topp, tuft or summit)","meaning":"the highest part","meaningCN":"最高部分","example":"The top of the slope dries out first.","exampleCN":"坡顶最先变干。"},{"word":"soil","structure":"soil (Old French soil, a plot of land)","meaning":"ground in which plants grow","meaningCN":"植物生长的土地","example":"The soil here is thin and stony.","exampleCN":"这里的土薄而多石。"},{"word":"topsoil","structure":"top + soil (compound)","meaning":"the fertile upper layer","meaningCN":"肥沃的上部土层","example":"Topsoil was saved in a heap beside the site.","exampleCN":"表土被堆存在工地旁边。"},{"word":"topsoils","structure":"topsoil + -s (plural)","meaning":"several kinds of surface soil","meaningCN":"多种表土","example":"The survey compared topsoils across the valley.","exampleCN":"调查比较了谷地各处的表土。"},{"word":"subsoil","structure":"sub- (under) + soil","meaning":"the layer beneath the surface soil","meaningCN":"表层土之下的土层","example":"Subsoil showed up as soon as the pit deepened.","exampleCN":"坑一挖深，底土就露出来了。"},{"word":"topdressing","structure":"top + dressing (compound, surface application)","meaning":"material spread on the surface","meaningCN":"铺在表面的材料","example":"A light topdressing evened out the lawn.","exampleCN":"轻轻铺一层表土把草坪找平了。"},{"word":"topmost","structure":"top + -most (superlative)","meaning":"highest of all","meaningCN":"最高的","example":"The topmost layer is the darkest.","exampleCN":"最上面一层颜色最深。"},{"word":"soil-forming","structure":"soil + forming (compound adjective)","meaning":"producing soil","meaningCN":"形成土壤的","example":"Litter is a soil-forming input.","exampleCN":"枯落物是成土的输入之一。"}],"latinEntries":[{"word":"solum","structure":"Latin noun solum (ground, base)","meaning":"ground, floor, sole","meaningCN":"地面、地板、脚底","example":"The soil in topsoil is this Latin noun, worn down through French.","exampleCN":"topsoil 中的 soil 就是经法语磨损后的这个拉丁名词。"}]}},{"word":"subsoil","ipa_uk":"/ˌsʌbˈsɔɪl/","ipa_us":"/ˌsʌbˈsɔɪl/","definition_zh":"底土、心土；表土之下的土层","definition_en":"the layer of soil below the topsoil, usually poorer in organic matter and richer in clay or gravel","core_image":"坑壁上半是黑土，下半是紧实的黄褐色黏土，锹刃卡在交界处","scene":"挖到一半时，铁锹在深色表土之下碰到了紧实的黄褐色土，铲刃一滑，工人说 This subsoil is stiff clay that water can hardly pass through.","sceneCN":"这里 subsoil 指「表土之下的那层土」，取第 1 个义项（层位本身）；句意为这层底土是紧实的黏土，水几乎渗不过去。图中可辨识物件：坑壁、深色表土、黄褐黏土、铁锹。","pos":[{"tag":"n.","zh":"底土、心土（多作不可数，指具体土类时可用复数 subsoils）"}],"collocations":[{"phrase":"the subsoil layer","zh":"底土层"},{"phrase":"heavy subsoil","zh":"紧实的底土"},{"phrase":"subsoil drainage","zh":"底土排水"},{"phrase":"subsoil clay","zh":"底土黏土"},{"phrase":"topsoil and subsoil","zh":"表土与底土"},{"phrase":"subsoil compaction","zh":"底土压实"}],"forms":[{"label":"不可数名词","form":"subsoil"},{"label":"复数（指土类）","form":"subsoils"},{"label":"对照术语（表土）","form":"topsoil"},{"label":"相关动词（深松）","form":"subsoil"},{"label":"相关名词（母质）","form":"parent material"}],"derivatives":[{"word":"subsoils","pos":"n.","zh":"各类底土（复数，调查用语）"},{"word":"subsoiling","pos":"n.","zh":"深松作业；不翻乱土层的深层松土"},{"word":"subsoiler","pos":"n.","zh":"深松机、深松铲"},{"word":"topsoil","pos":"n.","zh":"表土"}],"senses":[{"no":"01","title":"The layer under the surface soil","titleCN":"底土（总称）","definition":"the soil layer lying immediately below the topsoil, lower in organic matter and usually denser","definitionCN":"紧接表土之下、有机质更少且通常更紧实的土层","example":"Roots stopped where the subsoil turned stony.","exampleCN":"根在底土变多石的地方就停住了。","why":"The Latin prefix sub- means under, so the word simply places a soil layer beneath the one named first.","whyCN":"拉丁前缀 sub- 意为「在下」，因此这个词只是把一层土放在先说到的那层之下。"},{"no":"02","title":"Clay-enriched subsoil","titleCN":"黏土富集的心土层","definition":"the layer where clay washed down from above has collected, forming a dense band","definitionCN":"从上方淋洗下来的黏土在此聚集、形成紧实条带的那一层","example":"The red subsoil holds so much clay that it cracks in summer.","exampleCN":"红色底土含黏土太多，夏天会开裂。","why":"Fine clay particles move downward with water until they stick, so the densest band forms below the leached zone.","whyCN":"细小黏粒随水下移直到附着，因此最紧实的那条带形成于淋溶层之下。"},{"no":"03","title":"A mineral layer with little life","titleCN":"缺乏有机质的矿质层","definition":"the part of the profile where roots, worms and organic matter are scarce","definitionCN":"剖面上根系、蚯蚓与有机质都很少的那部分","example":"Few earthworms reach the subsoil except along old root channels.","exampleCN":"除了沿着旧根孔，很少有蚯蚓到达底土。","why":"Fresh organic matter is added at the surface, so life thins out with depth and the layer stays mineral.","whyCN":"新鲜有机质只在地表加入，因此生命随深度变稀，这一层始终保持矿质状态。"},{"no":"04","title":"Bearing layer for foundations","titleCN":"工程上的持力层","definition":"the firm layer engineers rely on to carry the weight of a structure","definitionCN":"工程师依靠来承受建筑物重量的紧实土层","example":"The footings were taken down to the firm subsoil.","exampleCN":"基础一直做到坚硬的底土层。","why":"Loose surface soil settles, so loads are transferred to the denser layer below it.","whyCN":"松散的表土会沉降，因此荷载被传到它下面更紧实的层。"},{"no":"05","title":"A barrier to roots and water","titleCN":"限制根系与水分的紧实层","definition":"a compacted or clay-rich band that stops roots and slows drainage","definitionCN":"压实或富黏土的条带，阻止根系下扎并减慢排水","example":"A hard subsoil kept the orchard waterlogged all spring.","exampleCN":"紧实的底土让果园整个春天都积水。","why":"Water fills the pores above a dense layer and cannot drain, which is why farmers deep-loosen such subsoil.","whyCN":"水在紧实层之上的孔隙里积满而排不出去，因此农民要对这种底土做深松。"},{"no":"06","title":"Layers below the topsoil in a trench","titleCN":"探坑中表土以下的沉积","definition":"the sediment or buried soil beneath the modern surface, read in excavations","definitionCN":"现代地表之下的沉积物或埋藏土，在发掘中读取","example":"The trench showed a buried subsoil under the modern fill.","exampleCN":"探沟显示现代填土之下有一层埋藏底土。","why":"Excavation uses the word for any layer under the present surface, even when it is no longer soil in the farming sense.","whyCN":"考古发掘把这个词用于现今地表之下的任何一层，即使它已不是农业意义上的土壤。"},{"no":"07","title":"Material dug for fill","titleCN":"采挖用作填方的底土","definition":"subsoil removed and used as bulk fill on another site","definitionCN":"被挖出并用于别处作为大体量填方的底土","example":"Trucks carried the subsoil to the embankment works.","exampleCN":"卡车把底土运到路堤工地。","why":"Because the layer is abundant, cheap and stony, it is quarried for fill rather than saved for growing.","whyCN":"由于这一层量大、便宜又多石，它常被采作填方，而不是留作种植。"},{"no":"08","title":"Contrast with topsoil and parent material","titleCN":"与表土、母质的区分","definition":"the middle term in the standard three-part division of the profile","definitionCN":"剖面标准三分法中居中的那一项","example":"Descriptions separate topsoil, subsoil and parent material before naming the soil.","exampleCN":"描述时先区分表土、底土与母质，再给土壤命名。","why":"Field survey needed three simple terms, and subsoil was the neutral middle one that is neither worked nor unweathered.","whyCN":"野外调查需要三个简单术语，而底土正是既不耕作、也未风化的那个中性中间项。"}],"etymology":{"intro":{"en":"Subsoil is Latin sub-, under, welded to the English noun soil, which itself came from Old French and Latin solum. The compound belongs to nineteenth-century agricultural writing.","cn":"subsoil 是拉丁前缀 sub-「在下」加英语名词 soil 构成，而 soil 本身来自古法语与拉丁 solum。这个复合词属于十九世纪的农业文献。"},"items":[{"era":"LATIN SUB-","en":"Sub- meant under or below in Latin and appears in dozens of English words such as submarine and subsoil.","cn":"sub- 在拉丁语中意为「在下、低于」，出现在 submarine、subsoil 等大量英语词中。"},{"era":"LATIN SOLUM","en":"Solum meant ground, floor or sole, and it reached English as soil through Old French.","cn":"solum 意为地面、地板或脚底，经古法语以 soil 的形式进入英语。"},{"era":"AGRICULTURAL TERM","en":"Nineteenth-century writers paired subsoil with topsoil to describe the depth that the plough did not reach.","cn":"十九世纪作者把 subsoil 与 topsoil 配对使用，用来描述犁所达不到的深度。"},{"era":"ENGINEERING EXTENSION","en":"In the twentieth century the same word covered bearing layers under foundations and bulk fill dug from below the surface.","cn":"到二十世纪，同一个词又涵盖基础下的持力层，以及从地表以下挖出的大体量填方。"},{"era":"VERB USE","en":"The verb to subsoil, meaning to loosen deep layers without turning them up, is a back-formation from the noun.","cn":"动词 subsoil 意为深松而不把下层翻上来，是由名词逆构而来。"}]},"similar":{"note":{"en":"Group one holds layer terms whose positions are easy to confuse; group two holds materials that resemble subsoil in use.","cn":"第一组是位置容易混淆的层位词；第二组是用途上与底土相似的材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"topsoil","ipa":"/ˈtɒpsɔɪl/","tag":"the layer above","definition":"The fertile dark layer at the surface, the direct opposite in position and usually in quality.","definitionCN":"地表那层肥沃深色的土，在位置与质量上通常都与之相对。"},{"word":"parent material","ipa":"/ˈpeərənt məˈtɪəriəl/","tag":"the layer below","definition":"The rock or sediment from which the soil formed, lying beneath the subsoil or forming its lower limit.","definitionCN":"形成土壤的岩石或沉积物，位于底土之下或构成其下限。"},{"word":"substrate","ipa":"/ˈsʌbstreɪt/","tag":"general base","definition":"Any underlying material or surface; it is used in biology and engineering rather than soil survey.","definitionCN":"任何底层材料或表面；用于生物学与工程，而非土壤调查。"},{"word":"subgrade","ipa":"/ˈsʌbɡreɪd/","tag":"road-building term","definition":"The prepared soil surface under a road or pavement, which may be natural subsoil or imported fill.","definitionCN":"道路或铺面之下经过处理的土面，可能是天然底土，也可能是外运填方。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hardpan","ipa":"/ˈhɑːdpæn/","tag":"a cemented layer","definition":"A very dense layer cemented by clay, iron or calcium carbonate that roots and water cannot pass.","definitionCN":"由黏土、铁或碳酸钙胶结成的极紧实层，根系与水都无法通过。"},{"word":"clay pan","ipa":"/ˈkleɪ pæn/","tag":"clay-rich band","definition":"A dense clay-rich horizon inside the subsoil; it is a kind of subsoil rather than a synonym.","definitionCN":"底土内部的富黏土紧实层；它是底土的一种，而不是同义词。"},{"word":"overburden","ipa":"/ˌəʊvəˈbɜːdn/","tag":"mining term","definition":"All material above a seam, including topsoil and subsoil; the word is defined by the seam, not by soil layers.","definitionCN":"覆盖在矿层之上的全部材料，包含表土与底土；该词以矿层定义，而非以土层定义。"},{"word":"fill","ipa":"/fɪl/","tag":"placed material","definition":"Material deliberately put in place to raise ground; subsoil becomes fill only after it is dug and moved.","definitionCN":"为抬高地面而特意填入的材料；底土只有被挖出搬运后才成为填方。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin prefix, the real topsoil pair and the real engineering uses.","cn":"正常联想：真实的拉丁前缀、真实的表土配对与真实的工程用法。"},"normal":[{"en":"Sub- means under, so subsoil is simply the under-soil.","cn":"sub- 意为在下，因此 subsoil 就是「下面的土」。"},{"en":"Topsoil is dark and full of roots; subsoil is pale, dense and stony.","cn":"表土深色多根；底土浅色、紧实、多石。"},{"en":"Three-part profile: topsoil, subsoil, parent material.","cn":"剖面三分：表土、底土、母质。"},{"en":"A dense subsoil causes waterlogging, which is why farmers deep-loosen it.","cn":"紧实的底土会造成积水，因此农民要深松它。"},{"en":"Engineers look for subsoil when they need a firm bearing layer.","cn":"工程师需要坚实地基时找的就是底土。"}],"abstract":[{"en":"Picture a sponge on top of a brick: water passes the sponge and stops at the brick.","cn":"想象一块海绵压在砖上：水穿过海绵，到砖就停住了。"},{"en":"Picture a layer that holds up a building while nothing lives in it.","cn":"想象一层土撑着整栋楼，里面却没有任何生命。"},{"en":"Picture clay that cracks into deep plates in a dry summer.","cn":"想象干旱的夏天黏土裂成一块块深板。"}]},"examples":[{"en":"The subsoil here is heavy clay with very little air.","cn":"这里的底土是几乎不含空气的重黏土。"},{"en":"Water sat on the field because the subsoil drained poorly.","cn":"水积在田里，因为底土排水很差。"},{"en":"Engineers tested the subsoil before choosing the foundation type.","cn":"工程师先检测底土，再决定基础类型。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sub 在下 + soil 土」——表土下面那层紧实少肥的土，就是底土","word":"subsoil"},"root":"sub-（拉丁前缀「在下」）+ soil（古法语 soil，上溯拉丁 solum「地面」）；「位于表层土之下的土层」。","sensesIntro":{"en":"Eight senses move from the layer itself to its clay band, its lack of life, its role under foundations, its barrier effect, its use in trenches, its use as fill, and its place in the three-part division.","cn":"八个义项从这一层本身走到黏土带、缺乏生命、基础持力、阻水阻根、探沟中的用法、作填方，以及三分法中的位置。"},"semanticMap":{"core":{"en":"CORE IMAGE: a spade striking stiff clay just under the dark surface.","cn":"核心意象：铁锹在深色表层之下碰到紧实的黏土。"},"chain":["LAYER BELOW","CLAY ACCUMULATION","LITTLE LIFE","BEARING LAYER","DRAINAGE BARRIER","EXCAVATED FILL"],"branches":[{"senses":"S1 · S8","en":"POSITION: the middle term between topsoil and parent material.","cn":"位置：介于表土与母质之间的中间项。"},{"senses":"S2 · S3","en":"COMPOSITION: clay washed down, and life left behind.","cn":"组成：黏土淋洗下来，生命被留在上面。"},{"senses":"S4 · S5","en":"ENGINEERING: strong enough to carry a building, dense enough to stop water.","cn":"工程：强到能承重，紧到能阻水。"},{"senses":"S6","en":"EXCAVATION: any buried layer under the present surface.","cn":"发掘：现今地表之下的任何埋藏层。"},{"senses":"S7","en":"MATERIAL: dug out and sold as fill.","cn":"材料：被挖出并作为填方出售。"}]},"affixes":{"intro":{"en":"Subsoil is the Latin prefix sub- plus the noun soil, and the prefix recurs in a large family of English words.","cn":"subsoil 由拉丁前缀 sub- 加名词 soil 构成，该前缀在英语中构成一大族词。"},"latinIntro":{"en":"Both parts have Latin ancestry: sub- is a Latin prefix and solum is a Latin noun. The entries below record both.","cn":"两部分都有拉丁语来源：sub- 是拉丁前缀，solum 是拉丁名词。下面的词条记录两者。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, under)","meaning":"under; below","meaningCN":"在下；低于","example":"Submarine and subsoil both use the same prefix.","exampleCN":"submarine 与 subsoil 使用同一前缀。"},{"word":"solum","structure":"solum (Latin, ground or sole)","meaning":"ground; base","meaningCN":"地面；底部","example":"Soil and sole both come from solum.","exampleCN":"soil 与 sole 都来自 solum。"},{"word":"soil","structure":"soil (English noun from Old French)","meaning":"the plant-growing layer","meaningCN":"能生长植物的土层","example":"The soil was thin over chalk.","exampleCN":"白垩之上的土层很薄。"},{"word":"subsoil","structure":"sub- + soil (compound)","meaning":"the layer under the topsoil","meaningCN":"表土之下的土层","example":"Subsoil was exposed when the pit was deepened.","exampleCN":"坑挖深后底土露了出来。"},{"word":"subsoiler","structure":"subsoil + -er (implement)","meaning":"a deep loosening plough","meaningCN":"深松机具","example":"The subsoiler broke the compacted layer without turning it.","exampleCN":"深松机把紧实层破开而不翻转它。"},{"word":"subsoiling","structure":"subsoil + -ing (process noun)","meaning":"deep loosening of soil","meaningCN":"土壤深松作业","example":"Subsoiling improved drainage in one pass.","exampleCN":"一次深松就改善了排水。"},{"word":"topsoil","structure":"top + soil (contrast compound)","meaning":"the fertile layer above","meaningCN":"上方肥沃的土层","example":"Topsoil was stored separately from the subsoil.","exampleCN":"表土与底土分开堆存。"},{"word":"subsurface","structure":"sub- + surface","meaning":"beneath the surface","meaningCN":"地表之下","example":"Subsurface flow fed the spring.","exampleCN":"地表之下的水流补给着泉水。"}],"latinEntries":[{"word":"sub","structure":"Latin preposition and prefix sub (under)","meaning":"under, below","meaningCN":"在下、低于","example":"Latin subter, beneath, is built on the same prefix.","exampleCN":"拉丁语 subter（在下面）建立在同一前缀上。"},{"word":"solum","structure":"Latin noun solum (ground, base)","meaning":"ground, floor, sole","meaningCN":"地面、地板、脚底","example":"It supplies the soil half of subsoil.","exampleCN":"它提供 subsoil 中 soil 那一半。"}]}},{"word":"humus","ipa_uk":"/ˈhjuːməs/","ipa_us":"/ˈhjuːməs/","definition_zh":"腐殖质；土壤中充分腐解的深色有机物","definition_en":"the dark, stable organic material in soil formed from fully decomposed plant and animal remains","core_image":"落叶层下抓起一把黑褐色松软的腐殖土，手指一捏便散成细屑","scene":"林地落叶层下面露出一层黑褐色的松软物质，抓一把在手里像海绵，雨水从指缝渗出，向导说 This humus holds water and keeps the forest floor cool.","sceneCN":"这里 humus 指「土壤中充分腐解的深色有机物」，取第 1 个义项（腐殖质本身）；句意为这层腐殖质能保住水分，让林地地表保持阴凉。图中可辨识物件：落叶层、黑褐色腐殖土、指缝、渗出的水。","pos":[{"tag":"n.","zh":"腐殖质（不可数，土壤学与园艺学用语）"}],"collocations":[{"phrase":"a layer of humus","zh":"一层腐殖质"},{"phrase":"humus content","zh":"腐殖质含量"},{"phrase":"rich in humus","zh":"富含腐殖质"},{"phrase":"humus layer","zh":"腐殖质层"},{"phrase":"humus formation","zh":"腐殖质形成"},{"phrase":"humus-rich soil","zh":"富含腐殖质的土壤"}],"forms":[{"label":"不可数名词","form":"humus"},{"label":"形容词（腐殖的）","form":"humic"},{"label":"名词（腐殖化）","form":"humification"},{"label":"相关形容词（已腐殖化的）","form":"humified"},{"label":"相关名词（腐殖酸）","form":"humic acid"}],"derivatives":[{"word":"humic","pos":"adj.","zh":"腐殖的；与腐殖质有关的"},{"word":"humification","pos":"n.","zh":"腐殖化作用；有机物转变为腐殖质的过程"},{"word":"humified","pos":"adj.","zh":"已腐殖化的"},{"word":"humic acid","pos":"n.","zh":"腐殖酸（腐殖质中可碱溶的组分）"}],"senses":[{"no":"01","title":"Stable dark organic matter in soil","titleCN":"腐殖质（土壤学定义）","definition":"the dark, finely decomposed organic fraction of soil that resists further rapid breakdown","definitionCN":"土壤中深色、充分腐解、难以再快速分解的有机部分","example":"Humus gives the forest soil its dark colour and its smell.","exampleCN":"腐殖质赋予林地土壤深色与气味。","why":"The Latin word for earth was applied to the earth-like end product of decay, so the name says what it looks like.","whyCN":"拉丁语表示「土地」的词被用来指腐解的最终产物，因此这个名字说的是它看起来像什么。"},{"no":"02","title":"Spongy, water-holding material","titleCN":"海绵状、保水的性质","definition":"the physical behaviour of humus, holding several times its weight in water and keeping soil open","definitionCN":"腐殖质的物理表现：能吸持自身重量数倍的水，并让土壤保持疏松","example":"Humus keeps the sandy bed moist long after watering.","exampleCN":"浇水很久之后，腐殖质仍让砂质苗床保持湿润。","why":"Its crumb structure creates tiny pores, so water is held by surface tension rather than running straight through.","whyCN":"它的团粒结构造出微小孔隙，因此水被表面张力留住，而不是直接流走。"},{"no":"03","title":"The humus layer","titleCN":"腐殖质层","definition":"a distinct dark band of fully decomposed matter at the top of a forest soil","definitionCN":"森林土壤顶部由充分腐解物质构成的明显深色层","example":"The humus layer under the beeches was thick and soft.","exampleCN":"山毛榉林下的腐殖质层又厚又软。","why":"Where litter falls faster than it decays, the end product accumulates as its own layer within the profile.","whyCN":"当枯落物落下的速度快于分解速度，最终产物便作为独立一层堆积在剖面中。"},{"no":"04","title":"Mature compost","titleCN":"堆肥成熟后的腐殖质","definition":"the dark crumbly end product of a compost heap, ready to be dug into soil","definitionCN":"堆肥堆腐熟后得到的深色疏松产物，可翻入土中","example":"The bin finally produced crumbly black humus after a year.","exampleCN":"一年之后，堆肥箱终于产出了疏松的黑色腐殖质。","why":"Gardeners borrowed the soil-science word because mature compost is visually and chemically close to natural humus.","whyCN":"园艺者借用了土壤学的这个词，因为成熟堆肥在外观与化学性质上都接近天然腐殖质。"},{"no":"05","title":"Humus from forest litter","titleCN":"森林凋落物形成的腐殖质","definition":"the product of leaf litter, fungi and soil animals working together over decades","definitionCN":"树叶、真菌与土壤动物经数十年共同作用形成的产物","example":"Fungi do most of the work that turns leaf litter into humus.","exampleCN":"把落叶变成腐殖质的工作主要由真菌完成。","why":"Decay passes through fungal and animal stages, so humus is a residue of the whole food web rather than of one organism.","whyCN":"腐解要经过真菌与动物几个阶段，因此腐殖质是整个食物网的残余，而不是某一种生物的产物。"},{"no":"06","title":"A measure of fertility","titleCN":"作为肥力指标","definition":"the percentage of humus used to compare soils and to judge how much organic input they need","definitionCN":"用来比较土壤、判断需多少有机投入的腐殖质百分比","example":"The humus content fell sharply after decades of continuous cropping.","exampleCN":"连续耕作几十年后，腐殖质含量大幅下降。","why":"Because humus stores nutrients and water, its share is a compact index of how well a soil will yield.","whyCN":"由于腐殖质储存养分与水，它的比例就成了判断土壤产量表现的一个简洁指标。"},{"no":"07","title":"Humic substances in chemistry","titleCN":"化学上的腐殖酸类物质","definition":"the extracted acids and fractions such as humic and fulvic acid studied in the laboratory","definitionCN":"实验室提取研究的腐殖酸、富里酸等组分","example":"The study separated humic acids from the humus for analysis.","exampleCN":"研究把腐殖酸从腐殖质中分离出来分析。","why":"Analysts needed soluble fractions rather than the whole dark material, so the word split into named chemical groups.","whyCN":"分析者需要可溶组分而不是整块深色物质，因此这个词分裂成若干有名字的化学类别。"},{"no":"08","title":"Brown organic matter in water","titleCN":"水体中的腐殖质","definition":"dissolved dark organic matter that stains rivers and lakes brown","definitionCN":"把河流与湖泊染成褐色的溶解态深色有机物","example":"Humus washed from the peat turned the stream tea-coloured.","exampleCN":"从泥炭中洗出的腐殖质把溪水染成茶色。","why":"The same material that darkens soil dissolves in water, so hydrologists use the word for the colour it causes.","whyCN":"在土中使它变黑的同一物质也能溶于水，因此水文学家用它来指所造成的颜色。"}],"etymology":{"intro":{"en":"Humus is simply the Latin noun for earth, ground or soil, taken into modern science unchanged. Latin humilis, low, and homo, human being, are related to it through the idea of ground.","cn":"humus 就是拉丁语表示土地、地面、土壤的名词，原样进入近代科学。拉丁 humilis「低」与 homo「人」都通过「土地」这一观念与之相关。"},"items":[{"era":"LATIN HUMUS","en":"Humus meant earth, ground or soil, and it named the substance itself rather than any property of it.","cn":"humus 意为土地、地面、土壤，命名的是物质本身，而不是它的某种性质。"},{"era":"HUMILIS AND HOMO","en":"Humilis, low or humble, comes from humus, on the ground; homo, a human being, was understood as earth-born. Both are genuine relatives, not look-alikes.","cn":"humilis「低的、谦卑的」来自 humus「在地上」；homo「人」被理解为「土生的」。两者都是真正的同族词，而非仅仅形近。"},{"era":"GREEK COGNATE","en":"Greek chamai, on the ground, is generally considered a cognate of this root, which suggests an old Indo-European word for ground.","cn":"希腊语 chamai「在地上」一般被认为是这个词根的同源词，这表明存在一个古老的印欧语「地面」词。"},{"era":"SCIENTIFIC TERM","en":"Nineteenth-century soil science adopted humus for the dark residue of decay, distinguishing it from fresh litter and from mineral matter.","cn":"十九世纪的土壤学采用 humus 指腐解的深色残余，把它与新鲜枯落物和矿物区分开。"},{"era":"MODERN EXTENSIONS","en":"Twentieth-century chemistry added humic and fulvic fractions, and limnology applied the word to brown dissolved matter in water.","cn":"二十世纪的化学补充了腐殖酸与富里酸组分，湖沼学又把这个词用于水中的褐色溶解物。"}]},"similar":{"note":{"en":"Group one holds words that share the Latin earth root and are often mistaken for unrelated look-alikes; group two holds organic materials often confused with humus.","cn":"第一组是共享拉丁「土地」词根、常被误认为只是形近的词；第二组是常与腐殖质混淆的有机材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"human","ipa":"/ˈhjuːmən/","tag":"same earth root","definition":"From Latin homo, understood as earth-born; it shares the humus root rather than merely resembling it.","definitionCN":"来自拉丁 homo，被理解为「土生的」；它与 humus 共享词根，而不只是形近。"},{"word":"humble","ipa":"/ˈhʌmbl/","tag":"same root via humilis","definition":"From Latin humilis, low, literally on the ground, from humus; it describes position then character.","definitionCN":"来自拉丁 humilis「低的」，字面为「在地上」，出自 humus；先指位置，后指品性。"},{"word":"exhume","ipa":"/ɪɡˈzjuːm/","tag":"out of the ground","definition":"ex- out plus humus earth: to bring a body out of the ground.","definitionCN":"ex-「出」加 humus「土」：把遗体从地下取出。"},{"word":"humic","ipa":"/ˈhjuːmɪk/","tag":"adjective form","definition":"The adjective meaning relating to humus, used of acids and fractions rather than the whole material.","definitionCN":"表示与腐殖质有关的形容词，多用于酸与组分，而非整块物质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"compost","ipa":"/ˈkɒmpɒst/","tag":"made by people","definition":"Organic waste decomposed under managed conditions; it becomes humus-like but is a product, not a soil fraction.","definitionCN":"在人工管理条件下腐解的有机废弃物；它近似腐殖质，但属产品而非土壤组分。"},{"word":"leaf mould","ipa":"/ˈliːf məʊld/","tag":"partly decayed leaves","definition":"Leaf litter rotted to a crumbly state; it is an input on its way to humus rather than the end product.","definitionCN":"腐解到疏松状态的落叶；它是通往腐殖质的输入，而非最终产物。"},{"word":"peat","ipa":"/piːt/","tag":"waterlogged accumulation","definition":"Partly decayed plant matter preserved under water; it is not fully humified soil organic matter.","definitionCN":"在水下保存的部分腐解植物残体；它并未完全腐殖化为土壤有机质。"},{"word":"organic matter","ipa":"/ɔːˈɡænɪk ˈmætə/","tag":"the wider category","definition":"All organic material in soil, fresh or decomposed; humus is only its stable dark end.","definitionCN":"土壤中全部有机物质，无论新鲜或已腐解；腐殖质只是其稳定的深色末端。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin earth word and its genuine relatives, plus real soil-science terms.","cn":"正常联想：真实的拉丁「土地」词及其真正同族词，加上真实的土壤学术语。"},"normal":[{"en":"Humus is the Latin word for earth, so humus is earth reduced to its richest form.","cn":"humus 是拉丁语的「土地」，因此腐殖质就是土地被浓缩成最肥沃的形态。"},{"en":"Humble and human share the root: low to the ground, and earth-born.","cn":"humble 与 human 共享词根：贴近地面，以及土生。"},{"en":"Humus is what is left when the leaf no longer looks like a leaf.","cn":"当叶子不再像叶子时，剩下的就是腐殖质。"},{"en":"The measurable index in soil tests is humus content.","cn":"土壤检测中最可测的指标就是腐殖质含量。"},{"en":"Humic acid is the extracted fraction, not the whole dark layer.","cn":"腐殖酸是提取出的组分，而不是整层深色物质。"}],"abstract":[{"en":"Picture a forest floor as a slow kitchen where leaves are cooked down to black crumbs.","cn":"想象林地地表是一间慢火厨房，把叶子熬成黑色碎屑。"},{"en":"Picture a sponge made of old leaves that holds rain for weeks.","cn":"想象一块由旧叶子做成的海绵，能把雨水含住几周。"},{"en":"Picture a river running tea-brown because the ground itself has dissolved into it.","cn":"想象一条河呈茶褐色，因为地面本身溶进了水里。"}]},"examples":[{"en":"Humus darkens the soil and keeps nutrients from washing away.","cn":"腐殖质使土壤变深，并防止养分被冲走。"},{"en":"The garden beds were improved with leaf humus every autumn.","cn":"每年秋天都用落叶腐殖质改良花坛。"},{"en":"Humus content is the first figure any soil test reports.","cn":"腐殖质含量是任何土壤检测报告的第一个数字。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「胡姆斯」——林下那层黑乎乎、捏起来像海绵的土，就是腐殖质","word":"humus"},"root":"拉丁 humus「土地、地面、土壤」；同根另有 humilis「低的」（英语 humble）与 homo「人」（被理解为土生），希腊 chamai「在地上」一般视为同源。","sensesIntro":{"en":"Eight senses move from the soil fraction itself to its water-holding behaviour, its layer, compost, forest litter, fertility measurement, extracted acids, and finally the brown matter in water.","cn":"八个义项从土壤组分本身走到保水表现、独立层、堆肥、森林枯落物、肥力测定、提取的酸类，最后到水中的褐色物质。"},"semanticMap":{"core":{"en":"CORE IMAGE: a handful of black crumbly forest soil that holds water.","cn":"核心意象：一把黑褐色、能含水的林地土。"},"chain":["DECAYED ORGANIC MATTER","WATER RETENTION","HUMUS LAYER","MATURE COMPOST","FERTILITY INDEX","DISSOLVED IN WATER"],"branches":[{"senses":"S1 · S5","en":"ORIGIN: leaves and animals pass through fungi until only the stable residue remains.","cn":"来源：叶子与动物经真菌作用，最后只剩下稳定残余。"},{"senses":"S2","en":"BEHAVIOUR: the crumb structure holds water and air at the same time.","cn":"表现：团粒结构同时容纳水与空气。"},{"senses":"S3","en":"POSITION: where litter falls faster than it rots, humus forms its own band.","cn":"位置：当枯落物落得快于腐解，腐殖质就自成一层。"},{"senses":"S4","en":"PRODUCT: a compost heap reaches the same look and feel.","cn":"产品：堆肥堆最终也会达到同样的外观与手感。"},{"senses":"S6 · S7 · S8","en":"MEASUREMENT AND WATER: a fertility figure, extractable acids, and a brown stain in rivers.","cn":"测定与水：一个肥力数值、可提取的酸，以及河流里的褐色。"}]},"affixes":{"intro":{"en":"Humus is a bare Latin stem; the derived family uses -ic, -ification and compound forms such as humic acid.","cn":"humus 是一个光杆拉丁词干；派生族使用 -ic、-ification 以及 humic acid 这类复合形式。"},"latinIntro":{"en":"The stem is Latin and has genuine Latin relatives, so the Latin entries below record both the noun and its adjective.","cn":"该词干来自拉丁语并有真正的拉丁同族词，因此下面的拉丁词条记录名词及其形容词。"},"items":[{"word":"humus","structure":"humus (Latin noun, earth or ground)","meaning":"earth; soil","meaningCN":"土地；土壤","example":"Humus entered science without any change of spelling.","exampleCN":"humus 进入科学时拼写毫无变化。"},{"word":"humilis","structure":"humilis (Latin adjective, low, from humus)","meaning":"low; near the ground","meaningCN":"低的；贴近地面的","example":"Humble reaches English through this Latin adjective.","exampleCN":"humble 经这个拉丁形容词进入英语。"},{"word":"homo","structure":"homo (Latin noun, human being, earth-born)","meaning":"a human being","meaningCN":"人","example":"Human and humane both descend from homo.","exampleCN":"human 与 humane 都源自 homo。"},{"word":"humic","structure":"humus + -ic (relating to)","meaning":"relating to humus","meaningCN":"与腐殖质有关的","example":"Humic substances colour the water brown.","exampleCN":"腐殖物质把水染成褐色。"},{"word":"humification","structure":"humus + -ification (process of making)","meaning":"the formation of humus","meaningCN":"腐殖质的形成过程","example":"Humification slows in cold, waterlogged soil.","exampleCN":"在寒冷积水的土壤里，腐殖化会变慢。"},{"word":"humified","structure":"humus + -ified (made into)","meaning":"converted into humus","meaningCN":"已转化为腐殖质的","example":"The humified layer sits above the mineral soil.","exampleCN":"腐殖化的那一层位于矿质土之上。"},{"word":"humic acid","structure":"humic + acid (compound term)","meaning":"the alkali-soluble fraction of humus","meaningCN":"腐殖质中可碱溶的组分","example":"Humic acid was extracted with dilute alkali.","exampleCN":"腐殖酸用稀碱提取出来。"},{"word":"exhume","structure":"ex- (out) + humus (earth)","meaning":"to bring out of the ground","meaningCN":"从地下取出","example":"The grave was exhumed for identification.","exampleCN":"为辨认身份而掘开了坟墓。"},{"word":"inhume","structure":"in- (into) + humus (earth)","meaning":"to bury","meaningCN":"埋葬","example":"The custom was to inhume the dead outside the walls.","exampleCN":"当时的习俗是把死者葬在城墙之外。"}],"latinEntries":[{"word":"humus","structure":"Latin noun humus (earth, ground)","meaning":"earth, ground, soil","meaningCN":"土地、地面、土壤","example":"Latin inhumare means to put into the earth.","exampleCN":"拉丁语 inhumare 意为「埋入土中」。"},{"word":"humilis","structure":"humus (earth) + -ilis (adjective suffix)","meaning":"low, on the ground","meaningCN":"低的、在地上的","example":"Latin humilis means low, literally on the ground.","exampleCN":"拉丁语 humilis 意为低的，字面义是「在地上的」。"}]}},{"word":"organic matter","ipa_uk":"/ɔːˈɡænɪk ˈmætə/","ipa_us":"/ɔːrˈɡænɪk ˈmætər/","definition_zh":"有机物、有机质；来源于生物的残体及其腐解产物","definition_en":"material derived from living things, fresh or decayed, present in soil, water or sediment","core_image":"苗床边撒下一把深褐色碎屑，翻进土里后蚯蚓立刻围过来","scene":"农技员在苗床边抓起一把深褐色的碎屑撒进土里，翻土后蚯蚓很快围了过来，说 A handful of organic matter feeds the worms before it feeds the crop.","sceneCN":"这里 organic matter 指「来源于生物的残体及其腐解产物」，取第 1 个义项（土壤有机质整体）；句意为一把有机质先养活蚯蚓，然后才养活作物。图中可辨识物件：碎屑、苗床、翻土、蚯蚓。","pos":[{"tag":"n.","zh":"有机物、有机质（不可数，土壤学、生态学与水质用语）"}],"collocations":[{"phrase":"soil organic matter","zh":"土壤有机质"},{"phrase":"organic matter content","zh":"有机质含量"},{"phrase":"dissolved organic matter","zh":"溶解态有机质"},{"phrase":"particulate organic matter","zh":"颗粒态有机质"},{"phrase":"decomposition of organic matter","zh":"有机质的分解"},{"phrase":"organic matter accumulation","zh":"有机质积累"}],"forms":[{"label":"不可数名词","form":"organic matter"},{"label":"相关名词（有机质总量）","form":"organic content"},{"label":"相关术语（无机物）","form":"inorganic matter"},{"label":"相关名词（腐殖质）","form":"humus"},{"label":"相关形容词","form":"organic"}],"derivatives":[{"word":"organic","pos":"adj.","zh":"有机的；生物的"},{"word":"inorganic","pos":"adj.","zh":"无机的"},{"word":"organism","pos":"n.","zh":"生物体"},{"word":"material","pos":"n./adj.","zh":"材料；物质的"}],"senses":[{"no":"01","title":"Living and dead biological material in soil","titleCN":"土壤有机质（总称）","definition":"all material in soil that came from organisms, from living roots to fully decayed residue","definitionCN":"土壤中全部来自生物的物质，从活根一直到完全腐解的残余","example":"Soil organic matter is the main reserve of nitrogen in most fields.","exampleCN":"土壤有机质是大多数田地里氮的主要储备。","why":"Organic marks a biological origin, matter marks the physical stuff, so the phrase covers the whole range at once.","whyCN":"organic 标明生物来源，matter 标明物质实体，因此这个短语一次覆盖整个范围。"},{"no":"02","title":"The living fraction","titleCN":"活性部分：活根与土壤生物","definition":"roots, fungi, bacteria and soil animals that are part of the organic pool while alive","definitionCN":"活着时即属于有机库的根、真菌、细菌与土壤动物","example":"Living organic matter releases sugars into the soil within hours.","exampleCN":"活体有机质在几小时内就把糖释放进土里。","why":"The pool is defined by origin rather than by life state, so an organism counts before it dies.","whyCN":"这个库以来源定义而不以生死定义，因此生物在死前就已计入。"},{"no":"03","title":"The stable humified fraction","titleCN":"稳定的腐殖质部分","definition":"the dark, slow-turning portion that remains after most material has decomposed","definitionCN":"大部分物质腐解后留下、颜色深且周转缓慢的部分","example":"Most of the organic matter in the old pasture was stable humus.","exampleCN":"这片老牧场的大部分有机质是稳定的腐殖质。","why":"Each year's input loses its easy parts and leaves a resistant core, so the pool splits into fast and slow fractions.","whyCN":"每年的输入先失去易分解部分，留下抗分解的核心，因此这个库分成了快与慢两部分。"},{"no":"04","title":"Dissolved organic matter","titleCN":"溶解态有机质","definition":"organic compounds small enough to pass a fine filter, carried in soil water or streams","definitionCN":"小到能通过细滤膜的有机化合物，随土壤水或溪流迁移","example":"Dissolved organic matter gave the stream its brown colour.","exampleCN":"溶解态有机质让这条溪流呈褐色。","why":"Water carries the soluble part away, so analysts filter samples and treat what passes as a separate pool.","whyCN":"水把可溶部分带走，因此分析者过滤样品，并把透过的部分当作另一个库。"},{"no":"05","title":"Particulate organic matter","titleCN":"颗粒态有机质","definition":"recognisable fragments of plant or animal material held between soil grains","definitionCN":"夹在土粒之间、仍可辨认的动植物残片","example":"Particulate organic matter was easy to see in the sandy soil.","exampleCN":"在砂质土里，颗粒态有机质很容易看见。","why":"Coarse fragments remain distinct from the fine matrix, so a size cut separates this pool from the dissolved one.","whyCN":"粗碎片与细基质界限分明，因此按粒径切分就把这个库与溶解态分开。"},{"no":"06","title":"A fertility indicator","titleCN":"有机质含量与肥力指标","definition":"the measured percentage used to judge nutrient supply, structure and water holding","definitionCN":"用来判断养分供给、结构与保水能力的实测百分比","example":"Organic matter content had dropped below one per cent after years of burning.","exampleCN":"连年焚烧之后，有机质含量降到百分之一以下。","why":"A single figure summarises several benefits, which is why soil tests report it before anything else.","whyCN":"一个数字就概括了好几项好处，因此土壤检测总把它列在最前面。"},{"no":"07","title":"Organic matter in water","titleCN":"水体中的有机物","definition":"the organic load in water or waste water, measured by how much oxygen its decay demands","definitionCN":"水或废水中的有机负荷，以其腐解所需氧气量来衡量","example":"Organic matter in the discharge raised the oxygen demand sharply.","exampleCN":"排放水中的有机物让需氧量急剧上升。","why":"Microbes consume oxygen while breaking the material down, so its amount can be read as an oxygen figure.","whyCN":"微生物分解这些物质时要耗氧，因此其含量可以换算成一个需氧数值。"},{"no":"08","title":"Buried organic matter in sediments","titleCN":"沉积物与烃源岩中的有机质","definition":"organic material buried in muds and rocks, which over geological time becomes oil or gas","definitionCN":"埋在泥与岩石中的有机物质，经地质时间可变成石油或天然气","example":"The shale is rich in organic matter that never fully decayed.","exampleCN":"这层页岩富含未曾完全腐解的有机质。","why":"Burial cuts off oxygen, so decay stops part way and the residue is cooked into hydrocarbons.","whyCN":"埋藏隔绝了氧，腐解半途停止，残余物以后被热解成烃类。"}],"etymology":{"intro":{"en":"Organic comes from Greek organon, an instrument or organ, with Latin -icus; matter comes from Latin materia, timber or substance, from mater, mother. The phrase is a modern scientific pairing.","cn":"organic 出自希腊 organon「工具、器官」，加拉丁 -icus；matter 出自拉丁 materia「木料、物质」，源于 mater「母亲」。这个短语是近代科学的搭配。"},"items":[{"era":"GREEK ORGANON","en":"Organon meant a tool or instrument, and later an organ of the body, since an organ is the body's instrument.","cn":"organon 意为工具、器具，后来指身体器官，因为器官正是身体的工具。"},{"era":"LATIN ORGANICUS","en":"Latin organicus rendered the Greek adjective, and English organic first meant relating to bodily organs before it meant relating to living things in general.","cn":"拉丁 organicus 转写了这个希腊形容词，英语 organic 最初指与身体器官有关，后来才泛指与生物有关。"},{"era":"LATIN MATERIA","en":"Materia meant timber, building material and substance, from mater, mother, since material is what things are made from.","cn":"materia 意为木料、建筑材料与物质，出自 mater「母亲」，因为材料正是造物所出之处。"},{"era":"SCIENTIFIC PAIRING","en":"Nineteenth-century chemistry needed a term for biological residue in soil and water, and organic matter supplied it without naming any single compound.","cn":"十九世纪的化学需要为土壤与水中的生物残余找一个说法，organic matter 正好提供了这个既不指名某化合物的词。"},{"era":"MODERN FRACTIONS","en":"Twentieth-century research split the phrase into dissolved and particulate pools and added the buried organic matter of petroleum geology.","cn":"二十世纪的研究把这个短语分为溶解态与颗粒态，并增加了石油地质学中的埋藏有机质。"}]},"similar":{"note":{"en":"Group one holds the pairs and opposites that sit closest to this phrase; group two holds specific organic materials that are often used loosely in its place.","cn":"第一组是与该短语最贴近的配对与对立说法；第二组是常被随手代替它的具体有机材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"inorganic matter","ipa":"/ˌɪnɔːˈɡænɪk ˈmætə/","tag":"the direct opposite","definition":"Material not derived from organisms, such as minerals and salts; the pair defines the boundary of the concept.","definitionCN":"非来源于生物的物质，如矿物与盐；这一对说法界定概念边界。"},{"word":"organic","ipa":"/ɔːˈɡænɪk/","tag":"adjective alone","definition":"Relating to living things or carbon compounds; it can describe farming or food without naming any material.","definitionCN":"与生物或碳化合物有关的；可不指名任何材料而形容农业或食品。"},{"word":"organism","ipa":"/ˈɔːɡənɪzəm/","tag":"a living being","definition":"An individual living thing; organic matter may come from organisms but is not itself one.","definitionCN":"单个生物体；有机质可以来自生物体，但它本身不是生物体。"},{"word":"material","ipa":"/məˈtɪəriəl/","tag":"the second half","definition":"Any substance used or present; on its own it carries no biological meaning.","definitionCN":"任何被使用或存在的物质；单独使用时不含生物含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"humus","ipa":"/ˈhjuːməs/","tag":"one fraction","definition":"The stable dark end product of decomposition; it is part of organic matter, not the whole of it.","definitionCN":"腐解稳定的深色末端产物；它是有机质的一部分，而非全部。"},{"word":"biomass","ipa":"/ˈbaɪəʊmæs/","tag":"living or recently living","definition":"The mass of living organisms or of material recently derived from them, usually measured as fuel or energy.","definitionCN":"活生物体或新近由生物来源的物质的量，通常作为燃料或能量计量。"},{"word":"compost","ipa":"/ˈkɒmpɒst/","tag":"a managed product","definition":"Organic waste rotted under controlled conditions; it is added to soil as a source of organic matter.","definitionCN":"在受控条件下腐解的有机废弃物；作为有机质来源加入土壤。"},{"word":"litter","ipa":"/ˈlɪtə/","tag":"fresh fall","definition":"Dead plant material lying on the surface before decay; it is the input that becomes organic matter.","definitionCN":"腐解前落在地表的枯死植物材料；它是变成有机质的输入。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek organ word, the real Latin material word and the real soil-testing pairs.","cn":"正常联想：真实的希腊「器官」词、真实的拉丁「材料」词，以及真实的土壤检测用语。"},"normal":[{"en":"Organic means from an organism, matter means the stuff, so the phrase is literally living-origin stuff.","cn":"organic 意为来自生物，matter 意为物质，因此这个短语字面就是「生物来源的东西」。"},{"en":"Organic matter and inorganic matter are the two halves of any soil test.","cn":"有机质与无机质是任何土壤检测的两半。"},{"en":"Three pools in one phrase: living, particulate and dissolved.","cn":"一个短语里有三个库：活的、颗粒的、溶解的。"},{"en":"Humus is the stable fraction, not a synonym for the whole phrase.","cn":"腐殖质是稳定部分，而不是整个短语的同义词。"},{"en":"Buried organic matter is the beginning of oil and gas.","cn":"被埋藏的有机质是石油与天然气的起点。"}],"abstract":[{"en":"Picture a handful of crumbs that worms recognise before plants do.","cn":"想象一把碎屑，蚯蚓比植物更早认出它。"},{"en":"Picture a dark stain in a stream that came from a forest floor miles away.","cn":"想象溪水里的一道褐色，来自数英里外的林地地表。"},{"en":"Picture ancient swamp mud that is now a black rock full of stored carbon.","cn":"想象远古沼泽的泥，如今成了蓄满碳的黑色岩石。"}]},"examples":[{"en":"Organic matter improves both the structure and the fertility of the soil.","cn":"有机质既能改善土壤结构，也能提高肥力。"},{"en":"The wetland stores organic matter in peat that has built up for centuries.","cn":"这片湿地把有机质储存在堆积了几个世纪的泥炭里。"},{"en":"Dissolved organic matter made the lake water hard to treat.","cn":"溶解态有机质让湖水难以处理。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「有机 + 物质」——凡是来自活物的东西，不管是碎叶还是腐屑，都叫有机质","word":"organic matter"},"root":"organic（希腊 organon「器官、工具」加 -ic，经拉丁 organicus）+ matter（拉丁 materia「木料、物质」，源于 mater「母亲」）；「来源于生物的物质」。","sensesIntro":{"en":"Eight senses split the phrase into its soil pools, then follow the material into water and into buried rock.","cn":"八个义项把这个短语分成土壤中的几个库，然后跟着这些物质进入水体与埋藏的岩石。"},"semanticMap":{"core":{"en":"CORE IMAGE: dark crumbs scattered on a seed bed, feeding worms first.","cn":"核心意象：撒在苗床上的深色碎屑，先喂饱蚯蚓。"},"chain":["BIOLOGICAL ORIGIN","LIVING ROOTS","STABLE HUMUS","DISSOLVED FRACTION","FERTILITY FIGURE","BURIED CARBON"],"branches":[{"senses":"S1 · S2","en":"ORIGIN: it is defined by coming from life, including things still alive.","cn":"来源：以来自生命来定义，包括仍然活着的部分。"},{"senses":"S3 · S5","en":"SIZE AND AGE: fragments you can see, and a dark residue you cannot.","cn":"大小与年龄：看得见的碎片，与看不见的深色残余。"},{"senses":"S4 · S6","en":"MEASUREMENT: what passes a filter and what a soil test reports.","cn":"计量：什么能通过滤膜，以及土壤检测报出什么。"},{"senses":"S7","en":"WATER: the same material becomes an oxygen demand figure.","cn":"水：同一物质变成一项需氧量数值。"},{"senses":"S8","en":"DEEP TIME: buried and cooked into hydrocarbons.","cn":"深时：被埋藏并热解成烃。"}]},"affixes":{"intro":{"en":"Organic matter is made of an adjective and a noun, and both have analyzable stems with large families.","cn":"organic matter 由形容词与名词组成，两者都有可分析、族系庞大的词干。"},"latinIntro":{"en":"Greek organon reached Latin as organicus, and materia is native Latin; the entries below record both routes, marking which one is Greek in origin.","cn":"希腊 organon 以 organicus 进入拉丁语，materia 则是拉丁本族词；下面的词条记录两条路径，并标明哪一条源自希腊语。"},"items":[{"word":"organon","structure":"organon (Greek, tool or instrument)","meaning":"tool; organ","meaningCN":"工具；器官","example":"Organ, organelle and organic all trace to this Greek word.","exampleCN":"organ、organelle 与 organic 都可上溯这个希腊词。"},{"word":"-ic","structure":"-ic (Latin -icus, relating to)","meaning":"relating to","meaningCN":"与…有关的","example":"Organic and inorganic form a matched pair.","exampleCN":"organic 与 inorganic 构成一对。"},{"word":"organism","structure":"organ + -ism (system or body)","meaning":"a living body","meaningCN":"活的躯体、生物体","example":"A single organism can supply organic matter for years.","exampleCN":"一个生物体可以为土壤提供数年的有机质。"},{"word":"inorganic","structure":"in- (not) + organic","meaning":"not derived from life","meaningCN":"非来源于生命的","example":"Inorganic matter dominates the sandy subsoil.","exampleCN":"砂质底土中以无机质为主。"},{"word":"materia","structure":"materia (Latin, timber or substance)","meaning":"material; substance","meaningCN":"材料；物质","example":"Material and matter both descend from materia.","exampleCN":"material 与 matter 都源自 materia。"},{"word":"material","structure":"materia + -al (relating to)","meaning":"substance used to make things","meaningCN":"用于制造的物质","example":"Building material was hauled up the slope.","exampleCN":"建筑材料被运上坡。"},{"word":"matter","structure":"matter (English noun from materia via French)","meaning":"physical substance","meaningCN":"物质实体","example":"Matter can be solid, liquid or gas.","exampleCN":"物质可以是固体、液体或气体。"},{"word":"materially","structure":"material + -ly (in a manner)","meaning":"in a physical or significant way","meaningCN":"在物质上或实质上","example":"The soil was materially changed by the ash.","exampleCN":"火山灰在实质上改变了这片土壤。"},{"word":"immaterial","structure":"im- (not) + material","meaning":"without physical substance","meaningCN":"没有物质实体的","example":"The difference is immaterial to the crop.","exampleCN":"这个差别对作物并无实质影响。"}],"latinEntries":[{"word":"materia","structure":"Latin noun materia (timber, substance)","meaning":"timber, building material, substance","meaningCN":"木料、建筑材料、物质","example":"Latin materia meant timber before it meant subject matter.","exampleCN":"拉丁语 materia 先指木料，后来才指题材。"},{"word":"organicus","structure":"Greek organon (instrument) + Latin -icus","meaning":"relating to an organ or instrument","meaningCN":"与器官或工具有关的","example":"Medieval Latin organicus is the adjective behind English organic.","exampleCN":"中世纪拉丁语 organicus 是英语 organic 背后的形容词。"}]}},{"word":"nutrient cycle","ipa_uk":"/ˈnjuːtriənt ˈsaɪkl/","ipa_us":"/ˈnuːtriənt ˈsaɪkl/","definition_zh":"养分循环；营养元素在生物与环境之间往复流动的过程","definition_en":"the movement of nutrient elements between living things and their surroundings, and back again","core_image":"林地落叶被蚯蚓拖进土里，来年又从树冠上长出新叶","scene":"林地上蚯蚓把落叶一层层拖进土里，第二年树冠又抽出新叶，护林员说 The nutrient cycle returns what the leaves held to the trees that dropped them.","sceneCN":"这里 nutrient cycle 指「营养元素在生物与环境之间往复流动的过程」，取第 1 个义项（总称）；句意为养分循环把叶子所含的养分还给落下这些叶子的树。图中可辨识物件：落叶、蚯蚓、土层、新叶。","pos":[{"tag":"n.","zh":"养分循环（可数，复数 nutrient cycles）"}],"collocations":[{"phrase":"the nutrient cycle in a forest","zh":"森林中的养分循环"},{"phrase":"nutrient cycle and energy flow","zh":"养分循环与能量流动"},{"phrase":"closed nutrient cycle","zh":"闭合养分循环"},{"phrase":"disrupt the nutrient cycle","zh":"扰乱养分循环"},{"phrase":"nutrient cycling","zh":"养分循环（动名词形式）"},{"phrase":"soil nutrient cycle","zh":"土壤养分循环"}],"forms":[{"label":"复数","form":"nutrient cycles"},{"label":"动名词形式","form":"nutrient cycling"},{"label":"相关名词（养分）","form":"nutrient"},{"label":"相关术语（生物地球化学循环）","form":"biogeochemical cycle"},{"label":"相关术语（食物链）","form":"food chain"}],"derivatives":[{"word":"nutrient","pos":"n./adj.","zh":"养分；营养物；有营养的"},{"word":"nutrition","pos":"n.","zh":"营养；营养学"},{"word":"nutritious","pos":"adj.","zh":"有营养的"},{"word":"cycling","pos":"n.","zh":"循环过程（如 nutrient cycling）"}],"senses":[{"no":"01","title":"Nutrients moving round a system","titleCN":"养分循环（总称）","definition":"the general circulation of nutrient elements through organisms, soil, water and air","definitionCN":"营养元素在生物、土壤、水与空气之间的总体流转","example":"The nutrient cycle in a rainforest is fast because decay is fast.","exampleCN":"雨林的养分循环很快，因为腐解也很快。","why":"Cycle means a circle, so the phrase says the elements come back to where they started instead of disappearing.","whyCN":"cycle 意为圆圈，因此这个短语说的是元素回到起点，而不是消失。"},{"no":"02","title":"Global biogeochemical cycles","titleCN":"全球生物地球化学循环","definition":"the planet-scale circulation of carbon, nitrogen, phosphorus and other elements between rock, water, air and life","definitionCN":"碳、氮、磷等元素在岩石、水、空气与生命之间的行星尺度流转","example":"The carbon nutrient cycle links the atmosphere to forests and oceans.","exampleCN":"碳的养分循环把大气与森林、海洋连在一起。","why":"At planetary scale the loop includes geological reservoirs, so the same idea is studied as a biogeochemical cycle.","whyCN":"在行星尺度上这个环包含地质储库，因此同一观念被作为生物地球化学循环来研究。"},{"no":"03","title":"Internal ecosystem cycling","titleCN":"生态系统内部的生物循环","definition":"uptake by plants, transfer to animals, return through litter and decay within one ecosystem","definitionCN":"植物吸收、传给动物、经枯落物与腐解归还，都在同一生态系统内完成","example":"A closed nutrient cycle keeps the old forest productive without fertiliser.","exampleCN":"闭合的养分循环让老林子不施肥料也能保持生产力。","why":"Because the same atoms are reused on site, ecologists describe the ecosystem as a loop rather than a one-way flow.","whyCN":"由于同样的原子在原地被重复使用，生态学家把这个系统描述成环而不是单向流。"},{"no":"04","title":"Field cycles under farming","titleCN":"农田养分循环","definition":"the loop of fertiliser, crop uptake, harvest removal and returned residues on a farm","definitionCN":"农田上肥料、作物吸收、收获带走与残体归还构成的环","example":"Harvest removes so much that the field nutrient cycle must be topped up.","exampleCN":"收获带走太多，因此农田的养分循环必须补充。","why":"Harvest breaks the loop by exporting nutrients, so farming has to buy back what the crop sold.","whyCN":"收获把养分带出系统而打断了环，因此农业必须把作物卖掉的养分买回来。"},{"no":"05","title":"Litter fall and decay","titleCN":"森林凋落物循环","definition":"leaves, twigs and dead wood falling, being pulled down by soil animals, and releasing nutrients to roots","definitionCN":"叶、枝与枯木落下，被土壤动物拖入土中，再把养分释放给根系","example":"Earthworms drive the nutrient cycle of the deciduous wood.","exampleCN":"蚯蚓推动着这片落叶林的养分循环。","why":"Most forest nutrients leave the tree as litter, so the fall and the decay are the visible half of the loop.","whyCN":"森林的大部分养分以枯落物离开树木，因此落下与腐解正是这个环可见的一半。"},{"no":"06","title":"Nutrients in lakes and rivers","titleCN":"水体养分循环与富营养化","definition":"the circulation of nitrogen and phosphorus in water, which in excess feeds algal blooms","definitionCN":"氮与磷在水中的流转，过量时便养出藻华","example":"Fertiliser runoff changed the nutrient cycle of the whole lake.","exampleCN":"肥料径流改变了整个湖的养分循环。","why":"Water carries nutrients downstream, so a cycle that is balanced on land becomes an overload in the lake.","whyCN":"水把养分带到下游，因此陆地上平衡的循环在湖里变成过量。"},{"no":"07","title":"Leakage and imbalance","titleCN":"养分漏失与循环失衡","definition":"losses by leaching, erosion or gas that break the loop and force external inputs","definitionCN":"淋失、侵蚀或气体逸出造成的损失，打断循环并迫使外部投入","example":"Leaching broke the nutrient cycle and the land needed lime every year.","exampleCN":"淋失打断了养分循环，这片土地每年都要施石灰。","why":"A cycle is only closed if nothing leaves, and in real fields something always does.","whyCN":"只有当没有东西离开时循环才是闭合的，而真实田地里总会有东西离开。"},{"no":"08","title":"Rotations and green manure","titleCN":"轮作与绿肥维持的田间循环","definition":"the deliberate use of legumes, catch crops and rotations to keep nutrients circulating on the farm","definitionCN":"有意用豆科、覆盖作物与轮作让养分在农场内持续流转","example":"A legume in the rotation closes part of the nutrient cycle on the farm.","exampleCN":"轮作中加入一种豆科作物，就让农场内的养分循环闭合了一部分。","why":"Legumes fix nitrogen from the air, so the loop is fed from outside the field but inside the farm.","whyCN":"豆科从空气中固定氮，因此这个环的补给来自田块之外、却在农场之内。"}],"etymology":{"intro":{"en":"Nutrient comes from Latin nutrire, to nourish, through the present participle nutriens. Cycle comes from Greek kyklos, a circle or wheel, through Latin cyclus and French. The compound belongs to twentieth-century ecology.","cn":"nutrient 出自拉丁 nutrire「滋养」，经其现在分词 nutriens 而来。cycle 出自希腊 kyklos「圆圈、车轮」，经拉丁 cyclus 与法语传入。这个复合词属于二十世纪的生态学。"},"items":[{"era":"LATIN NUTRIRE","en":"Nutrire meant to nourish or feed, and the participle nutriens, nourishing, became the English noun nutrient.","cn":"nutrire 意为滋养、喂养，其分词 nutriens「滋养的」变成了英语名词 nutrient。"},{"era":"GREEK KYKLOS","en":"Kyklos meant a circle or a wheel, and Greek writers used it for the recurrent order of events as well as for physical wheels.","cn":"kyklos 意为圆圈或车轮，希腊作者既用它指实物车轮，也用它指事件周而复始的次序。"},{"era":"LATIN CYCLUS","en":"Latin borrowed cyclus from Greek for a wheel or a recurring period, and English cycle came through French with the same idea.","cn":"拉丁语从希腊语借入 cyclus 表示车轮或周期，英语 cycle 经法语传入，含义相同。"},{"era":"ECOLOGY TERM","en":"Twentieth-century ecology paired the two words to describe elements returning to their source, replacing older one-way descriptions of feeding.","cn":"二十世纪的生态学把这两个词配在一起，描述元素回到源头，取代了较早把取食描述为单向流动的做法。"},{"era":"MODERN SCOPE","en":"The phrase now runs from a single field to the whole planet, and from scientific measurement to farming practice.","cn":"这个短语如今从一块田延伸到整个行星，也从科学测量延伸到农业实践。"}]},"similar":{"note":{"en":"Group one holds terms built on nutrient or cycle; group two holds related ecological ideas that stress flow, storage or feeding rather than return.","cn":"第一组是建立在 nutrient 或 cycle 之上的术语；第二组是强调流动、储存或取食而非回归的相关生态概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nutrient cycling","ipa":"/ˈnjuːtriənt ˈsaɪklɪŋ/","tag":"process form","definition":"The activity of nutrients moving round, used when the emphasis is on the process rather than a named loop.","definitionCN":"养分流转这一活动，强调过程而非某一个被命名的环。"},{"word":"nutrition","ipa":"/ˌnjuːˈtrɪʃn/","tag":"feeding, not moving","definition":"The taking in of food for growth and health; it describes feeding, not the return of elements.","definitionCN":"为生长与健康摄入食物；描述取食，而非元素回归。"},{"word":"nutrient","ipa":"/ˈnjuːtriənt/","tag":"the element itself","definition":"A substance used for growth; on its own it names no movement at all.","definitionCN":"供生长用的物质；单独使用时完全不表示流动。"},{"word":"cycle","ipa":"/ˈsaɪkl/","tag":"the loop word","definition":"Any recurring sequence; combined with nutrient it names a specific biological loop.","definitionCN":"任何周而复始的序列；与 nutrient 连用才指特定的生物环。"}]},{"heading":"NEAR MEANING","entries":[{"word":"biogeochemical cycle","ipa":"/ˌbaɪəʊdʒiəˈkemɪkl ˈsaɪkl/","tag":"planetary scale","definition":"The global circulation of an element through living and non-living reservoirs, including rock and atmosphere.","definitionCN":"元素在生物与非生物储库（含岩石与大气）之间的全球流转。"},{"word":"energy flow","ipa":"/ˈenədʒi fləʊ/","tag":"one-way, not circular","definition":"The passage of energy through a food web, which cannot return because it is lost as heat.","definitionCN":"能量在食物网中的传递，因以热的形式散失而无法返回。"},{"word":"food chain","ipa":"/ˈfuːd tʃeɪn/","tag":"feeding order","definition":"The sequence of who eats whom; it tracks feeding links, not chemical return pathways.","definitionCN":"谁吃谁的顺序；追踪取食链条，而非化学回归路径。"},{"word":"nutrient budget","ipa":"/ˈnjuːtriənt ˈbʌdʒɪt/","tag":"accounting, not circle","definition":"The measured inputs and outputs of a nutrient for a defined area, often used to test whether a cycle is closed.","definitionCN":"某一划定区域内养分的实测输入与输出，常用来检验循环是否闭合。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin feed word, the real Greek wheel word and the standard ecological pair.","cn":"正常联想：真实的拉丁「喂养」词、真实的希腊「车轮」词，以及标准的生态学配对。"},"normal":[{"en":"Nutrient comes from a verb meaning to nourish; cycle comes from a word for a wheel.","cn":"nutrient 出自意为滋养的动词；cycle 出自意为车轮的词。"},{"en":"Litter falls, worms pull it down, roots take it up: the loop in three steps.","cn":"落叶落下、蚯蚓拉下去、根系吸上来：三步走完一个环。"},{"en":"Energy flows one way, nutrients go round: the standard contrast.","cn":"能量单向流，养分循环走：这是标准对照。"},{"en":"Harvest opens the loop, legumes help close it.","cn":"收获打开这个环，豆科作物帮它闭合。"},{"en":"In lakes the same loop becomes eutrophication when it is overloaded.","cn":"在湖泊里，同一个环一旦超载就变成富营养化。"}],"abstract":[{"en":"Picture a forest as a machine that never throws anything away.","cn":"想象森林是一台从不扔掉任何东西的机器。"},{"en":"Picture an atom taken from a leaf, carried down by rain, and lifted back into a new leaf.","cn":"想象一个原子从叶子出发，被雨水带下去，又被抬进一片新叶。"},{"en":"Picture a wheel whose rim is soil, roots and litter, turning without a beginning.","cn":"想象一只轮子，轮圈是土壤、根与枯落物，转起来没有起点。"}]},"examples":[{"en":"Clearing the forest broke the nutrient cycle and the soil lost fertility within a decade.","cn":"砍掉森林打断了养分循环，十年之内土壤就失去了肥力。"},{"en":"The course compares the nutrient cycle of a rainforest with that of a temperate wood.","cn":"这门课把雨林与温带林地的养分循环作比较。"},{"en":"Farmers use rotations to keep the nutrient cycle working without buying more fertiliser.","cn":"农民用轮作让养分循环持续运转，而不必买更多肥料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「养分 + 圆圈」——养分在土、根、叶之间转了一圈又回来，就是养分循环","word":"nutrient cycle"},"root":"nutrient（拉丁 nutrire「滋养」的现在分词 nutriens）+ cycle（希腊 kyklos「圆圈、车轮」，经拉丁 cyclus 与法语）；「养分在系统内转圈回流」。","sensesIntro":{"en":"Eight senses move from the general loop to the planetary scale, the ecosystem loop, the farm loop, the litter route, the lake, the broken loop, and the managed loop of rotations.","cn":"八个义项从总环走到行星尺度、生态系统内部、农场、枯落物路径、湖泊、被打断的环，最后到轮作维持的人工环。"},"semanticMap":{"core":{"en":"CORE IMAGE: a leaf falling, being pulled underground, and returning as a new leaf.","cn":"核心意象：一片叶子落下，被拖进地下，又以新叶的形态回来。"},"chain":["ELEMENTS RETURN","PLANETARY LOOP","ECOSYSTEM LOOP","FARM LOOP","LITTER ROUTE","BROKEN LOOP"],"branches":[{"senses":"S1","en":"THE IDEA: the same atoms come back rather than vanishing.","cn":"核心观念：同样的原子会回来，而不是消失。"},{"senses":"S2","en":"SCALE: at planetary level rock and air join the loop.","cn":"尺度：在行星层面，岩石与大气也加入这个环。"},{"senses":"S3 · S5","en":"INSIDE THE FOREST: uptake, litter fall and decay close the circle on site.","cn":"森林内部：吸收、落叶与腐解在原地闭合这个圈。"},{"senses":"S4 · S7 · S8","en":"THE FARM: harvest opens the loop, losses widen it, and rotations partly close it again.","cn":"农场：收获打开这个环，漏失扩大它，轮作又部分闭合它。"},{"senses":"S6","en":"WATER: the same loop becomes an overload and an algal bloom.","cn":"水：同一个环变成超载与藻华。"}]},"affixes":{"intro":{"en":"Nutrient cycle joins a Latin-derived noun in -ent with the Greek-derived noun cycle, and both build large families.","cn":"nutrient cycle 把一个带 -ent 的拉丁来源名词与一个希腊来源的名词 cycle 结合，两者都构成庞大的词族。"},"latinIntro":{"en":"Nutrire is native Latin; kyklos is Greek but was borrowed into Latin as cyclus. The entries below mark that distinction.","cn":"nutrire 是拉丁本族词；kyklos 是希腊语，但以 cyclus 的形式被拉丁语借入。下面的词条标明这一区别。"},"items":[{"word":"nutri-","structure":"nutri- (Latin root from nutrire, to nourish)","meaning":"nourish; feed","meaningCN":"滋养；喂养","example":"Nutrient, nutrition and nutritious share this root.","exampleCN":"nutrient、nutrition 与 nutritious 共享这个词根。"},{"word":"-ent","structure":"-ent (Latin participle ending)","meaning":"the thing that does or undergoes","meaningCN":"执行或承受该动作的事物","example":"A nutrient is literally a nourishing thing.","exampleCN":"nutrient 字面上就是「滋养之物」。"},{"word":"nutrition","structure":"nutri- + -tion (process noun)","meaning":"the process of being nourished","meaningCN":"获得营养的过程","example":"Nutrition depends on what the roots can reach.","exampleCN":"营养取决于根系能接触到什么。"},{"word":"nutritious","structure":"nutrit- + -ious (full of)","meaning":"full of nourishment","meaningCN":"富于营养的","example":"The leaves are surprisingly nutritious for the herd.","exampleCN":"这些叶子对畜群来说营养出乎意料地好。"},{"word":"nutrient-rich","structure":"nutrient + -rich (compound adjective)","meaning":"containing much nutrient","meaningCN":"含养分很多的","example":"Nutrient-rich water flowed into the marsh.","exampleCN":"富含养分的水流进了沼泽。"},{"word":"kyklos","structure":"kyklos (Greek, circle or wheel)","meaning":"circle; wheel","meaningCN":"圆圈；车轮","example":"Cyclone and cycle both descend from this Greek noun.","exampleCN":"cyclone 与 cycle 都源自这个希腊名词。"},{"word":"cycle","structure":"cycle (from Latin cyclus, from Greek kyklos)","meaning":"a recurring round","meaningCN":"周而复始的一轮","example":"The water cycle and the nutrient cycle are taught together.","exampleCN":"水循环与养分循环被放在一起讲。"},{"word":"cyclic","structure":"cycle + -ic (relating to)","meaning":"happening in rounds","meaningCN":"按轮次发生的","example":"Nutrient release is cyclic in this woodland.","exampleCN":"在这片林地，养分释放是按周期发生的。"},{"word":"recycle","structure":"re- (again) + cycle","meaning":"to send round again","meaningCN":"再循环、回收利用","example":"Composting recycles nutrients on the farm.","exampleCN":"堆肥让养分在农场内再循环。"}],"latinEntries":[{"word":"nutrire","structure":"Latin verb nutrire (nutri-, nutritum; to nourish)","meaning":"to nourish, feed","meaningCN":"滋养、喂养","example":"Latin nutrix, a nurse, is built on the same verb.","exampleCN":"拉丁语 nutrix（乳母）建立在同一动词上。"},{"word":"cyclus","structure":"Latin cyclus, borrowed from Greek kyklos (circle)","meaning":"a circle, a recurring period","meaningCN":"圆圈、周期","example":"Latin cyclus meant a circle and gives English cycle.","exampleCN":"拉丁语 cyclus 意为圆圈，并给出英语 cycle。"}]}}]);
